/**
 * AP English Language — Exit Quiz Question Pool
 * Lesson-aligned items for every routed topic (15+ per topic, 2+ per lesson
 * part, each tagged with the teaching `part`). Feeds topic exit quizzes, the
 * course diagnostic (by domain), unit tests (by domain), and the daily question.
 */

import { relevantPool } from './relevance-fallback'
import { shuffleArray } from '@/lib/shuffle-options'
export interface EngLangQuestion {
  question: string
  options: string[]
  correctAnswer: number
  explanation: string
  difficulty: 'easy' | 'medium' | 'hard'
  domain: string
  topicSlug: string
  formSet: number
  /** Lesson part (1–7) that teaches this item; a failed exit quiz routes back to it. */
  part?: number
}

export const engLangQuestionPool: EngLangQuestion[] = [
  // ── Domain: rhetorical-situation ────────────────────
  // englang-intro-rhetoric
  { question: 'A fire chief tells the town council: “In my twenty-two years with this department, I have pulled people out of buildings that met every code on paper. I am asking you to revisit the code.” The chief’s reference to her years with the department primarily serves to', options: ['evoke sympathy for firefighters who risk their lives on every call', 'supply statistical proof that the town’s rules have failed', 'establish her authority to judge whether the current rules protect residents', 'suggest that the council members lack practical experience'], correctAnswer: 2, explanation: 'Her two decades of rescues give her standing to say the code falls short, which is an appeal to credibility. She offers no statistics, and she never dwells on firefighters’ danger to win sympathy. Nothing in the sentence belittles the council’s experience.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 1, part: 1 },
  { question: 'A hospital posts two notices about the same flu clinic. The one for nurses uses clinical terms; the one for parents uses plain words and a cartoon. The difference between the notices best illustrates which idea?', options: ['Word choice should fit what the readers already know', 'Plain words show that a writer lacks real expertise', 'Clinical terms should be avoided in public writing', 'The purpose of a notice shifts with each new reader'], correctAnswer: 0, explanation: 'Both notices share a purpose, announcing the clinic, but each is pitched to what its readers know. Plain words for parents are a strategic choice, not a sign of ignorance, and clinical terms suit the nurses perfectly well. The purpose stays the same; only the audience changes.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 2, part: 1 },
  { question: 'A charity letter opens: “Last winter, Mara, age seven, did her homework by flashlight after her family’s power was shut off. This winter, your gift can keep the lights on for families like hers.” The opening story about Mara chiefly serves to', options: ['establish that the charity has a long record of managing donations well', 'provide statistical evidence that utility shutoffs are rising', 'concede that some families have misused aid in the past', 'make the abstract problem of utility shutoffs feel personal to donors'], correctAnswer: 3, explanation: 'One named child doing homework by flashlight turns a policy problem into a human one, an appeal to emotion aimed at the donors. The letter offers no track record for the charity and no numbers. It also concedes nothing about misuse.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 1, part: 1 },
  { question: 'A student’s rhetorical analysis essay includes this sentence: “In paragraph two, the author uses pathos.” Which revision would most improve the sentence as analysis?', options: ['Add a second appeal so the sentence names logos as well as pathos', 'Explain how the emotional details advance the author’s purpose', 'Quote the entire second paragraph so readers can see the appeal', 'State whether the student agrees with the author’s position'], correctAnswer: 1, explanation: 'Analysis has to explain how a choice works on the audience and why it serves the writer’s purpose; naming an appeal is only a label. Naming a second appeal or quoting more text still leaves the explanation out. Giving one’s own opinion turns analysis into argument.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 2, part: 1 },
  { question: 'A principal writes to parents: “I know many of you are angry about the new start time. You are right that I did not ask for your input soon enough. Here is what the first month of data shows.” The admission in the second sentence most likely affects the audience by', options: ['proving that the new start time was a mistake that must be reversed', 'lowering their defensiveness so they will weigh the evidence that follows', 'shifting attention from the policy to the parents’ own behavior', 'replacing the logical evidence with a plea for forgiveness'], correctAnswer: 1, explanation: 'Conceding a fair point to an angry audience builds goodwill, so the parents are more likely to listen to the data. The principal admits a flaw in the process, not that the policy itself was wrong. The data still follows, so the admission adds to the evidence rather than replacing it, and no blame shifts to the parents.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 1, part: 1 },
  { question: 'A speaker learns that most of her audience doubts her main claim. Which adjustment would most likely make her more persuasive?', options: ['Speak louder and repeat her claim with more force', 'Replace her evidence with stories that are easier to recall', 'Leave out the objection to keep her focus on the claim', 'Acknowledge their concerns before answering them'], correctAnswer: 3, explanation: 'A doubtful audience listens more readily when its concerns are taken seriously, so acknowledging the doubt and then answering it is the strongest move. Repeating the claim more forcefully does nothing to address the doubt. Dropping evidence or skipping the objection gives skeptics less reason to change their minds.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 2, part: 1 },
  { question: 'Two letters oppose closing a city park. One opens: “As someone who has walked Elm Park every morning for thirty years, I know what it means to this block.” The other opens: “The city’s own survey found that Elm Park draws more weekday visitors than any other park in the district.” Which statement best describes the difference between the openings?', options: ['The first relies on the writer’s credibility, the second on data', 'The first appeals to logic, the second to the reader’s emotions', 'The first targets city officials, the second targets nearby neighbors', 'The first states a claim, the second concedes an opposing view of it'], correctAnswer: 0, explanation: 'Thirty years of daily walks establishes the first writer’s standing to speak, while the second cites the city’s survey as evidence. Calling the first opening logical reverses the two strategies. Neither opening concedes anything, and nothing signals that they address different audiences.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 1, part: 1 },
  { question: 'A nurse tells a medical conference: “You have all seen the readmission numbers. What the numbers do not show is Mr. Alvarez, who came back to our ward three times in one month because no one explained his discharge papers in Spanish.” The shift from the numbers to Mr. Alvarez primarily serves to', options: ['reject the statistics her listeners rely on as unreliable', 'establish her own expertise by showing she has studied the hospital data', 'suggest that the data misses a human cost her listeners should weigh', 'shift the blame for the readmissions onto the patient himself'], correctAnswer: 2, explanation: 'The nurse accepts the numbers (“you have all seen” them) and then adds what they leave out, a single patient’s experience, to make the cost felt. She never calls the statistics wrong, so reading the shift as a rejection goes too far. The story points to a failure in communication, not the patient’s fault, and it shows her firsthand experience rather than any study of the data.', difficulty: 'hard', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 2, part: 1 },
  { question: 'A student writes to the school board, whose members have said their main concern is cost, arguing that the high school should start later. Which evidence would most effectively serve her purpose with this audience?', options: ['A poll showing that most students prefer a later start to the day', 'A sleep researcher’s account of how teen body clocks shift with age', 'A personal story about a classmate who fell asleep during a test', 'A nearby district’s report that later starts cut its spending on extra bus routes'], correctAnswer: 3, explanation: 'Evidence persuades when it speaks to what the audience already cares about, and this board has named cost. Student preferences, sleep science and a classmate’s story may be true and relevant to the topic, but none of them answers the board’s budget concern.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 1, part: 1 },
  { question: 'A student explains how a speechwriter’s choices of appeal advance the speech’s purpose. The student is practicing which skill?', options: ['Building an argument', 'Synthesizing sources', 'Rhetorical analysis', 'Judging a claim’s truth'], correctAnswer: 2, explanation: 'Rhetorical analysis examines how a writer persuades, which is what the student is doing. Building an argument means making one’s own case, and synthesis means combining several sources. Analysis judges how a text works, not whether its claims are true.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 2, part: 1 },
  { question: 'A 1960s speech praising the “conquest” of wilderness by new highways drew applause when it was delivered. Today many listeners find the same word troubling. This difference best illustrates that', options: ['a text’s meaning is fixed by what the writer intended at the time', 'an audience’s response to a text depends on its historical context', 'speeches about highways rely more on logos than on pathos', 'older speeches use more figurative language than modern speeches do'], correctAnswer: 1, explanation: 'The same word gets opposite reactions because the audience’s values and historical moment have changed, which shows how context shapes reception. If meaning were fixed by intent, the reaction would not have changed. The other claims are generalizations the example does not support.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 1, part: 1 },
  { question: 'In March, during a dry season, a columnist publishes an argument for stronger flood barriers, and it draws little notice. The week after a major flood, she republishes it word for word, and it is shared widely. Which conclusion is best supported?', options: ['The new timing gave the same words a sense of urgency for readers', 'The argument became more logically sound after the flood', 'The column’s intended audience shifted from experts to the general public', 'The tone was revised to match readers’ heightened emotions'], correctAnswer: 0, explanation: 'The text did not change, but the moment did, and the recent flood made her claim feel urgent and relevant. Her reasoning is no more or less sound than it was in March, and nothing suggests a new intended audience. The tone could not have been revised because the column was republished word for word.', difficulty: 'hard', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 2, part: 1 },
  { question: 'A student’s argument to the city council about a proposed teen curfew opens with this thesis: “Curfews are a controversial topic with many sides.” Which revision provides a clear, defensible claim?', options: ['The council should replace the curfew with funded late-night youth programs', 'Members of the council have strong feelings about the curfew', 'Curfews have been used in cities across the country for decades', 'This essay will explain the many sides of the curfew debate'], correctAnswer: 0, explanation: 'A defensible thesis takes a position that a reasonable person could dispute, and only the proposal to replace the curfew does so. Noting that council members have feelings and that curfews have a long history are facts, not arguable claims. Announcing that the essay will explain both sides describes the essay but takes no stance.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 1, part: 1 },
  { question: 'Which sentence states an arguable claim rather than a fact?', options: ['Our school assigns homework four nights a week.', 'Homework should count less toward grades.', 'Students reported about two hours of homework a night.', 'The homework policy was last revised three years ago.'], correctAnswer: 1, explanation: 'An arguable claim is a position that reasonable people could dispute and that needs support. The proposal about grading takes such a position. The other sentences report checkable facts about the school’s schedule, student surveys and policy history.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 2, part: 1 },
  { question: 'A student writes to her town newspaper urging residents to attend Thursday’s zoning hearing and speak against a proposed parking garage. Which choice best states the letter’s purpose?', options: ['to inform readers about the history of the garage site', 'to establish the student as an expert in zoning law', 'to rally readers to oppose the garage at the hearing', 'to explain what usually happens at a zoning hearing'], correctAnswer: 2, explanation: 'The letter urges readers to show up and speak against the garage, so its goal is a call to action. Background on the site or on hearing procedure might appear along the way, but it is not the point. Nothing suggests the student is trying to present herself as a legal expert.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 1, part: 1 },
  { question: 'From a commencement speech: “I failed the bar exam twice. I tell you this not to earn your pity but because the woman who failed is the reason I now teach law at this university.” The speaker’s disclosure primarily functions to', options: ['earn the graduates’ pity for the hardships she has endured', 'prove with evidence that failing an exam often leads to later success', 'warn graduates that the bar exam is harder than they expect', 'build trust by presenting her success as earned through setbacks'], correctAnswer: 3, explanation: 'By admitting failure and linking it to her current position, the speaker makes her authority feel honest and earned, which builds her credibility with graduates facing their own setbacks. She explicitly rejects pity, so reading the disclosure as a bid for sympathy misreads it. One personal case is not proof of a general rule, and the speech is not about how hard the bar exam is.', difficulty: 'hard', domain: 'rhetorical-situation', topicSlug: 'englang-intro-rhetoric', formSet: 2, part: 1 },
  // englang-rhetorical-situation
  { question: 'After the city council voted to close the only public library branch on the east side, a retired teacher wrote to the local paper urging residents to attend the next council meeting. What is the exigence of her letter?', options: ['the teacher’s long years as a patron of the public library', 'readers of the paper who live close to the branch', 'the council’s recent vote to close the east-side library branch', 'the next meeting where residents may lobby the council'], correctAnswer: 2, explanation: 'Exigence is the specific event or problem that prompts the writing, here the vote to close the branch. Her years as a library patron are part of who the speaker is, and the paper’s readers are the audience. The upcoming meeting is where she wants readers to act, not what moved her to write.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 1, part: 1 },
  { question: 'A scientist will present vaccine safety data at a town meeting where many attendees have said they distrust health officials. Which tone would most likely serve her purpose?', options: ['Measured and respectful', 'Urgent and openly alarmed', 'Playful and lightly mocking', 'Detached and highly technical'], correctAnswer: 0, explanation: 'A hostile or wary audience is more likely to listen to a speaker who stays calm and treats its concerns with respect. Alarm can sound like pressure, and mockery confirms the distrust. A detached, technical tone keeps listeners who already doubt experts at a distance.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 2, part: 1 },
  { question: 'Version 1: “The intervention yielded a statistically significant reduction in absenteeism.” Version 2: “Kids who got breakfast at school missed fewer days.” Version 2 was most likely written for', options: ['researchers reviewing a journal submission', 'members of a federal grant committee', 'statisticians checking the study design', 'parents reading a district newsletter'], correctAnswer: 3, explanation: 'Plain, concrete diction like “kids” and “missed fewer days” suits a general audience such as parents. Researchers, statisticians and grant reviewers expect the technical vocabulary of the first version. The shift in diction signals a shift in audience.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 1, part: 1 },
  { question: 'A student uses SOAPSTone to prepare for analyzing a eulogy delivered at a firefighter’s funeral. Under which element should she list “the firefighter’s death in the warehouse blaze”?', options: ['Tone', 'Occasion', 'Speaker', 'Audience'], correctAnswer: 1, explanation: 'In SOAPSTone, the occasion is the event that prompts the text, its exigence, and the death is what calls for the eulogy. The speaker is whoever delivers it, and the audience is the mourners. Tone describes the speaker’s attitude, not an event.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 2, part: 1 },
  { question: 'A 1942 radio talk on saving cooking fat for the war effort ends: “Every can of fat you save is a cartridge in a soldier’s rifle.” The final sentence is best understood as a response to', options: ['a scientific audience expecting data on nutrition and food supply', 'a wartime audience eager to see how small sacrifices at home could help troops', 'a farming audience worried about falling prices for its crops', 'an audience of soldiers who needed advice on caring for rifles'], correctAnswer: 1, explanation: 'In 1942 listeners at home wanted to know their efforts mattered, and the line ties a kitchen chore directly to the fighting. It offers no nutritional data and says nothing about crop prices. The radio talk addresses families saving fat, not soldiers in the field.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 1, part: 1 },
  { question: 'A county pamphlet describes overflowing landfills, warns that space will run out in four years, explains a new compost program, and ends by asking readers to sign up. This structure best fits which purpose?', options: ['a balanced overview', 'a personal narrative', 'a scholarly analysis', 'a call to action'], correctAnswer: 3, explanation: 'Problem, urgency, solution and a direct request is the classic structure of a call to action. A balanced overview would weigh positions without asking readers to do anything. The pamphlet tells no personal story and makes no scholarly argument.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 2, part: 1 },
  { question: 'After a chemical spill upstream, a water utility issued two statements. The one for customers began: “Your tap water is safe to drink, and here is how we know.” The one for state regulators began: “Sampling at intakes 3 and 4 found benzene below the 5 ppb limit.” What best explains the difference?', options: ['Each statement is fitted to what its readers need and already know', 'The customer statement warns of danger, while the other reports none', 'The regulator statement persuades, while the other one entertains', 'The customer statement hides data the utility wants to keep secret'], correctAnswer: 0, explanation: 'Both statements answer the same spill, but customers want reassurance in plain words while regulators need technical readings. The customer statement says the water is safe, so it does not warn of danger, and both report the same finding. The customer version informs and reassures rather than entertains, and promising to explain “how we know” is the opposite of hiding data.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 1, part: 1 },
  { question: 'In a letter to fellow members of his hunting club, a lifelong hunter argues for banning lead ammunition: “None of us wants to see the eagles we grew up watching disappear from this valley.” The writer’s use of “us” and “we” primarily serves to', options: ['concede that hunters are to blame for the eagles’ decline', 'signal that his argument is aimed mainly at environmental groups', 'present him as an insider who shares the club’s own values', 'show that his position is backed by scientific consensus'], correctAnswer: 2, explanation: 'Writing as one of “us,” the hunter frames the ban as protecting something club members already love, which lowers resistance from a potentially wary audience. The sentence assigns no blame, so it is not a concession. The letter is addressed to the club, not outside groups, and the line cites no scientific evidence.', difficulty: 'hard', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 2, part: 1 },
  { question: 'An op-ed begins: “Last Tuesday, a driver on Route 9 waited forty minutes for a wheelchair lift that never came.” The writer then argues that the transit agency must fund lift repairs. The opening anecdote primarily serves to', options: ['establish the writer as an engineer who has studied wheelchair-lift design', 'concede that the transit drivers are partly to blame for the delays', 'provide data showing how often the lifts break down in a typical year', 'ground the argument in a recent, concrete failure that feels urgent'], correctAnswer: 3, explanation: 'A specific, recent incident gives the op-ed its exigence and makes the need for funding feel pressing. Nothing in the opening says anything about the writer’s background. The driver is shown waiting, not at fault, and one incident is an anecdote rather than data on how often lifts fail.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 1, part: 1 },
  { question: 'A writer addressing readers who already strongly agree with her is most likely to adopt which tone?', options: ['Conciliatory and cautious', 'Detached and highly clinical', 'Passionate and direct', 'Apologetic and hesitant'], correctAnswer: 2, explanation: 'A sympathetic audience does not need to be won over gently, so writers often speak to it with passion and directness. A conciliatory, cautious tone suits a hostile audience. A clinical or apologetic tone would weaken the shared energy that agreement makes possible.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 2, part: 1 },
  { question: 'A 1919 pamphlet supporting women’s suffrage argues that women “have already proven their citizenship in the munitions factories.” A modern reader who ignores the date would most likely miss', options: ['that the pamphlet’s main purpose is to entertain its readers', 'how the recent war made factory work a timely proof of civic duty', 'that the writer was a factory owner who hoped to hire cheaper workers', 'that the phrase relies on statistics instead of on emotion'], correctAnswer: 1, explanation: 'Coming right after World War I, the reference to munitions work points to recent wartime service the audience would remember, which gives the claim to citizenship its force. The pamphlet argues for suffrage, so it is not meant to entertain. Nothing identifies the writer as a factory owner, and the phrase contains no statistics.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 1, part: 1 },
  { question: 'An essay on remote work opens: “When my company ordered everyone back to the office last month, I finally put into words what three years at my kitchen table had taught me.” Which choice identifies the essay’s exigence rather than its broader context?', options: ['the recent directive to come back to the workplace', 'the general rise of remote work over recent years', 'the writer’s three years of working away from the office', 'readers now debating whether to return to the office'], correctAnswer: 0, explanation: 'Exigence is the specific trigger, and the writer names it: the order last month that finally moved her to write. The broad trend toward remote work is context, and her years at home are part of her perspective as a speaker. Readers weighing the issue are the audience.', difficulty: 'hard', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 2, part: 1 },
  { question: 'A student’s notes on a speech read: Speaker, a mayor; Audience, residents angry about a tax increase; Purpose, win support for the increase. Which thesis best connects the rhetorical situation to the mayor’s choices?', options: ['Facing an angry crowd, the mayor admits past waste before tying the tax to repairs residents value', 'The mayor uses ethos, pathos, and logos to persuade the residents to back the new tax', 'In this speech the mayor talks about a tax increase that made many residents angry', 'The mayor’s speech is effective because it is well organized and clearly written'], correctAnswer: 0, explanation: 'A strong analytical thesis names specific choices and links them to the audience and purpose, and only the thesis about admitting waste does that. Listing the three appeals gives labels without explaining how they work. Summarizing the topic or praising organization in general says nothing about how the mayor responds to an angry crowd.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 1, part: 1 },
  { question: 'A student is about to analyze a commencement speech. Before examining its figurative language, which question should she answer first?', options: ['How many metaphors does the speech use?', 'Whom is the speaker addressing?', 'Does she agree with the speaker’s advice?', 'Which metaphor is the most original one?'], correctAnswer: 1, explanation: 'Rhetorical analysis starts with the rhetorical situation, and the audience shapes every decision a speaker makes. Counting or ranking metaphors without knowing who they are for leaves nothing to connect them to. Her own agreement with the advice is irrelevant to analysis.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 2, part: 1 },
  { question: 'In SOAPSTone, the “O” asks a reader to identify the', options: ['opinion the writer holds most', 'organization of the argument', 'occasion that prompts the text', 'objections the writer must answer'], correctAnswer: 2, explanation: 'The O stands for occasion, the event or situation that calls for the text, which is another name for exigence. The writer’s opinion relates to purpose, and organization and counterarguments are not part of SOAPSTone.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 1, part: 1 },
  { question: 'After a layoff, a factory owner writes to his employees: “I will not insult you by pretending this decision was easy, or by telling you it was anyone’s fault but mine.” The sentence primarily serves to', options: ['argue that outside forces beyond his control caused all the layoffs', 'comfort the employees by promising that jobs will return', 'concede that employees had warned him to avoid layoffs', 'accept responsibility in a way that may preserve workers’ trust'], correctAnswer: 3, explanation: 'Taking the blame himself with a hurt, angry audience is a bid to keep his credibility and their respect. The owner says the fault is his alone, the opposite of blaming outside forces. He promises nothing about jobs returning and mentions no earlier warnings from employees.', difficulty: 'hard', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation', formSet: 2, part: 1 },
  // englang-rhetorical-situation-writing
  { question: 'A student is writing to her city’s chamber of commerce in support of a bike-lane proposal. Which sentence would most effectively appeal to this audience’s priorities?', options: ['Cycling is a joyful way to rediscover the beauty of our own city streets', 'Bike lanes reduce carbon emissions and help our planet breathe again', 'Shops along protected bike lanes in nearby cities report gains in sales', 'Most cyclists I know feel unsafe riding on our busiest downtown streets'], correctAnswer: 2, explanation: 'A chamber of commerce represents local businesses, so evidence about sales and customer traffic speaks directly to its concerns. Joy, emissions and cyclist safety may matter to other audiences, but they do not address what business owners most care about.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 1, part: 1 },
  { question: 'A student argues for a later school start in one letter to parents and another to coaches. Which change between the letters reflects effective audience adaptation?', options: ['Citing research on sleep and athletes’ reaction times for coaches', 'Asking coaches to back a later start only on game days', 'Leading with test-score data in both letters to stay consistent', 'Opening the coaches’ letter with a parent’s carpool complaints'], correctAnswer: 0, explanation: 'Audience adaptation keeps the same claim but chooses framing and evidence that matter to each audience, and athletic performance is what coaches care about. Limiting the request to game days changes the claim itself rather than its framing. Using the same lead evidence in both letters shows no adaptation, and a parent’s carpool complaint speaks to parents, not coaches.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 2, part: 1 },
  { question: 'A student’s argument to the school board about the cell-phone policy opens: “Since the beginning of time, people have disagreed about rules.” In which respect is this opening weakest?', options: ['It uses too much technical vocabulary', 'It concedes too much to the opposing side', 'It relies on statistics instead of stories', 'It never shows why the issue is urgent'], correctAnswer: 3, explanation: 'A sweeping “since the beginning of time” opener is generic and sets no stakes, so the board has no reason to see the policy as urgent. The sentence uses no jargon, concedes nothing and cites no statistics, so those diagnoses do not fit.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 1, part: 1 },
  { question: 'Writing to a group of retired veterans, a student argues for a high school community-service requirement. Her main evidence is a viral video trend in which teens post their volunteer work. What is the main weakness of this evidence?', options: ['It does not include a clear claim about service hours', 'It is unlikely to seem credible to her readers', 'It is too formal for an audience of veterans', 'It proves the opposite of her overall position'], correctAnswer: 1, explanation: 'Evidence must be something the target audience trusts, and older readers are unlikely to be persuaded by a social media trend. The problem lies in the evidence, not in a missing claim. A viral video is not formal, and teens volunteering does not undercut a service requirement.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 2, part: 1 },
  { question: 'Writing to a city council that is skeptical of a new park, a student includes this sentence: “Anyone who opposes this park is simply against children.” What effect is this sentence most likely to have?', options: ['It strengthens her ethos by showing how firmly she is committed to the park', 'It may alienate doubtful members and make them less open to her case', 'It provides logical evidence that the park would benefit local children', 'It persuades the council by appealing to its members’ love of children'], correctAnswer: 1, explanation: 'Attacking opponents’ motives insults the very people the student needs to win over, so skeptical members are likely to dig in. Stridency reads as unfairness, not credibility, and the sentence offers no evidence about benefits. Insulting the audience’s motives is not an appeal that persuades it.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 1, part: 1 },
  { question: 'A student has two minutes to plan an argument essay. What should she decide before choosing her evidence?', options: ['Her most impressive vocabulary', 'The length of each body paragraph', 'Which rhetorical devices to include', 'Her audience and purpose'], correctAnswer: 3, explanation: 'Planning starts with the rhetorical situation, because the audience and purpose decide which evidence will persuade. Vocabulary, paragraph length and devices are later choices that depend on those first decisions.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 2, part: 1 },
  { question: 'A student claims, “Our town should build a dog park,” and plans to adapt the argument for different readers. Which pairing of audience and emphasis is best matched?', options: ['Town budget committee: low upkeep costs and donated land', 'Dog owners: projected cuts in property tax rates', 'Budget committee: the joy dogs feel running free', 'Health officials: how much the town’s residents love their pets'], correctAnswer: 0, explanation: 'A budget committee weighs cost, so low upkeep and donated land match its priorities. The joy of dogs and residents’ love of pets miss what the committee and health officials need to hear, and tax cuts are not the main concern of dog owners deciding whether they want a park.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 1, part: 1 },
  { question: 'A student is writing to the principal who created a new dress code, arguing that it should be revised. Which sentence best establishes a credible, fair-minded persona?', options: ['As a student, I know better than anyone what we should be allowed to wear.', 'The dress code violates our rights, and the courts would likely agree.', 'I see that the policy aims to reduce distractions, and I share that goal.', 'This policy was clearly written without asking a single student.'], correctAnswer: 2, explanation: 'Acknowledging the principal’s goal shows fairness and makes the reader, who wrote the policy, more willing to consider changes. Claiming to know better than anyone sounds arrogant rather than credible. The legal claim is unsupported, and accusing the principal of ignoring students puts the audience on the defensive.', difficulty: 'hard', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 2, part: 1 },
  { question: 'A student arguing for a four-day school week is writing to parents of young children. Which objection should she most likely address?', options: ['Teachers may want to use the day off for professional training', 'Students may lose some interest in after-school sports', 'The district may need to update its calendar software', 'Families may struggle to find and afford day care on the fifth weekday'], correctAnswer: 3, explanation: 'Addressing the objection the audience is most likely to raise makes an argument more persuasive, and parents of young children will worry first about care on the day off. Teacher training, sports interest and software are concerns for other groups or are minor to this audience.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 1, part: 1 },
  { question: 'A student writing to the school board adds: “Some board members worry that the plan costs too much; however, a state grant would cover the first two years.” This sentence is best described as', options: ['an appeal to the board’s emotions', 'a restatement of the thesis', 'a concession and rebuttal', 'a description of the exigence'], correctAnswer: 2, explanation: 'The sentence acknowledges an objection and then answers it, which is a concession followed by a rebuttal. It does not appeal to feelings, restate the main claim or explain what prompted the argument.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 2, part: 1 },
  { question: 'In January a student drafted an argument for heat-safety rules at outdoor sports practices. She will submit it in August, the week after two players were treated for heatstroke. Which revision best uses the change in her situation?', options: ['Cut the heatstroke cases so the argument does not seem exploitative', 'Open with the recent heatstroke cases to show why rules matter now', 'Remove references to the season to keep the essay timeless', 'Add a paragraph on the history of heat-safety rules in other sports'], correctAnswer: 1, explanation: 'The recent cases give the argument a clear exigence, and opening with them shows readers why the issue is urgent. Cutting the cases or making the essay timeless throws that urgency away. A history of other sports’ rules is background that does not use the new situation.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 1, part: 1 },
  { question: 'Which thesis for an argument about requiring computer science in high school shows the most nuanced awareness of real-world constraints?', options: ['Schools should phase in a computer science requirement as teachers are trained', 'Every school should require computer science starting this fall, no matter the cost', 'Computer science is important, but so are many other subjects in school', 'Some schools require computer science while others do not offer it at all'], correctAnswer: 0, explanation: 'Tying the requirement to teacher training takes a clear position while acknowledging a practical limit, the kind of qualified claim that can earn sophistication credit. Requiring it “no matter the cost” ignores constraints entirely. The other two sentences are vague or merely factual and take no defensible position.', difficulty: 'hard', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 2, part: 1 },
  { question: 'A student writing to a hospital’s nurses, hoping to win their support for a new scheduling plan, opens with: “Nurses complain a lot, but patients come first.” Which revision best suits this audience and purpose?', options: ['Few people understand the cost of a double shift better than the nurses reading this', 'Patients deserve better care than tired, overworked staff can give', 'Hospitals across the country are changing how they schedule shifts', 'Nurses should stop complaining and accept the new schedule plan'], correctAnswer: 0, explanation: 'Recognizing the nurses’ own experience treats the audience with respect and connects the plan to a burden they already feel. Shifting the focus to patients still implies the nurses are the problem, and a national trend gives them no personal reason to care. Telling them to stop complaining repeats the original insult.', difficulty: 'medium', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 1, part: 1 },
  { question: 'A student’s essay on the closing of a beloved local diner expresses outrage in every sentence. The most likely result is that the essay', options: ['gains credibility with neutral readers', 'seems rigid and simplistic', 'establishes exigence more effectively', 'appeals more strongly to logos'], correctAnswer: 1, explanation: 'A one-note tone makes writing sound rigid and simplistic because it leaves no room for nuance. Constant outrage tends to cost credibility with neutral readers rather than gain it. Tone alone does not supply exigence or logical reasoning.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 2, part: 1 },
  { question: 'Which question belongs to the exigence step of planning an argument?', options: ['What does my audience already believe?', 'Which tone will my readers find most credible?', 'Why does this issue need attention right now?', 'What do I most want my readers to do?'], correctAnswer: 2, explanation: 'Exigence answers why the argument matters now. Asking what the audience believes belongs to audience analysis, choosing a tone is part of the persona and tone plan, and deciding what readers should do defines purpose.', difficulty: 'easy', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 1, part: 1 },
  { question: 'Writing to skeptical local business owners, a student drafts: “The new recycling fee will hurt no one. Recycling saves the planet. Business owners should be happy to pay it.” Which revision would most improve the paragraph’s effectiveness for this audience?', options: ['Add vivid images of polluted oceans and landfills to strengthen the emotional appeal', 'Restate the claim more forcefully so owners see the writer’s conviction', 'Cut the line about the planet and end the paragraph with a question', 'Acknowledge the fee’s cost, then show how the program lowers waste-hauling bills'], correctAnswer: 3, explanation: 'Skeptical owners need their cost concern taken seriously and answered with evidence that matters to their businesses. Ocean imagery and stronger assertion ignore that concern, and more force may harden resistance. Ending with a question changes the style but does not supply the missing reasoning.', difficulty: 'hard', domain: 'rhetorical-situation', topicSlug: 'englang-rhetorical-situation-writing', formSet: 2, part: 1 },

  // ── Domain: claims-evidence ─────────────────────────
  // englang-claims-evidence
  { question: 'A city council member writes: “Raising the downtown parking fee led to a sharp drop in weekend foot traffic at local shops.” Which type of claim does this sentence make?', options: ['A policy claim urging the council to lower the fee', 'A value claim judging the fee increase to be unfair', 'A causal claim tying a drop in shoppers to the fee increase', 'A factual claim reporting the size of the new fee'], correctAnswer: 2, explanation: 'The sentence asserts that raising the fee produced an effect, fewer weekend shoppers, so it is a cause-and-effect claim. It recommends no action, so it is not a policy claim, and it passes no judgment of right or wrong, so it is not a value claim. It does more than report the fee itself.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 1, part: 1 },
  { question: 'A student claims that the school should replace soda in its vending machines with water. She cites a study finding that students who drink water score higher on afternoon quizzes, then comments: "This shows that soda is too expensive for families." The commentary\'s main weakness is that it', options: ['draws a conclusion about cost that the study does not support', 'explains the study\'s finding instead of simply quoting it', 'relies on research rather than a student\'s personal story', 'restates the claim instead of adding any new evidence'], correctAnswer: 0, explanation: 'Commentary should explain how the evidence supports the claim. The study is about quiz scores, so the commentary leaps to an unrelated point about cost and leaves the real link (water helps students learn) unstated. Explaining evidence is exactly what commentary should do, research is legitimate support, and the comment does not restate the claim; it connects the evidence to the wrong idea.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 2, part: 1 },
  { question: 'In an op-ed, a writer states: “Critics are right that a four-day school week leaves some working parents scrambling for Friday childcare. Yet districts that made the switch have kept nearly all of their teachers, a striking result in a staffing crisis.” The first sentence functions primarily as', options: ['the writer\'s central claim about the policy', 'a rebuttal of the critics\' position', 'evidence that supports the writer\'s view', 'a concession to a reasonable objection'], correctAnswer: 3, explanation: 'The writer grants that critics have a valid point about childcare before turning with “Yet” to a counterpoint. The rebuttal comes in the second sentence, not the first. The first sentence is not the writer\'s own claim and does not support the writer\'s view; it acknowledges the other side.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 1, part: 1 },
  { question: 'A blog post argues: “Towns with more coffee shops have higher median incomes, so opening coffee shops is a smart way for struggling towns to grow wealthier.” Which statement best identifies the flaw in the reasoning?', options: ['It relies on a single anecdote about one prosperous town', 'It treats a correlation as though it proves that one causes the other', 'It cites an expert whose field is unrelated to economics', 'It makes a value claim without stating what is good'], correctAnswer: 1, explanation: 'The writer observes that coffee shops and income rise together, then assumes the shops create the wealth; prosperous towns may simply attract coffee shops. The post cites a broad pattern rather than one town, and it quotes no expert. Its conclusion is a policy recommendation built on a causal leap, not an unsupported value judgment.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 2, part: 1 },
  { question: 'A writer claims that a new citywide bike-lane network caused traffic injuries to fall. Which additional evidence would most strengthen this causal claim?', options: ['Interviews with cyclists who say they now feel much safer', 'A detailed history of how the council voted to fund the lanes', 'Photographs showing how heavily the lanes are used on weekends', 'Crash trends in comparable cities lacking new lanes'], correctAnswer: 3, explanation: 'To show that the lanes caused the decline, the writer needs to rule out other explanations, and comparing similar cities without new lanes does that. Cyclists\' feelings, the funding history, and photos of usage are related to the lanes but say nothing about whether injuries fell because of them.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 1, part: 1 },
  { question: '“A school without arts classes is like a garden with only one crop: it may yield a harvest, but one blight can ruin everything.” The writer supports the point mainly with', options: ['An analogy', 'A survey', 'An anecdote', 'Expert testimony'], correctAnswer: 0, explanation: 'The sentence compares a school to a garden to clarify an idea, which is an analogy. It tells no story about a specific person or event, cites no data, and quotes no authority.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 2, part: 1 },
  { question: 'A speech on food insecurity opens with the story of Dana, a nurse who skips lunch so her children can eat, and then reports that one in six local households lacks reliable food. In this sequence, the story of Dana chiefly serves to', options: ['prove that the statistic is accurate', 'concede a point to the speech\'s opponents', 'make the later figure feel human and concrete', 'establish the speaker\'s credentials as an expert'], correctAnswer: 2, explanation: 'Pairing a vivid anecdote with a statistic makes an abstract number relatable; Dana puts a face on the one-in-six figure. One story cannot verify a statistic\'s accuracy, and the story grants nothing to opponents. It is about Dana, not about the speaker\'s qualifications.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 1, part: 1 },
  { question: 'A student writes: “A 2022 survey found that 61 percent of teens check their phones within five minutes of waking.” Which follow-up sentence provides the most effective commentary for the claim that phones shape teens\' habits before the day begins?', options: ['Another survey found that adults check their phones almost as often as teens do.', 'Phones were first sold to the public in the 1980s and have spread ever since.', 'Many teens also report checking social media late at night just before sleeping.', 'Such a reflex suggests that the phone now sets each morning\'s first priority for teens.'], correctAnswer: 3, explanation: 'Commentary interprets evidence and links it to the claim; this sentence explains what the waking habit reveals about who controls the start of the day. The other sentences add more information, about adults, phone history, or nighttime use, without explaining how the survey result supports the claim.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 2, part: 1 },
  { question: 'A draft paragraph argues for a later school start time. Its final sentence reads: “Of course, some say later start times would wreck after-school sports schedules.” The paragraph then ends. What is the most significant problem with this ending?', options: ['The concession should have opened the paragraph instead', 'The objection is raised but never answered', 'The sentence introduces a value claim that contradicts the thesis', 'The opposing view is stated too fairly to be persuasive'], correctAnswer: 1, explanation: 'Raising a counterargument helps only when the writer responds to it; left unanswered, the objection undercuts the paragraph\'s own claim. Concessions can appear late in a paragraph, and stating an opposing view fairly is a strength. The sentence reports what others think rather than making the writer\'s own value claim.', difficulty: 'hard', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 1, part: 1 },
  { question: 'Which revision best qualifies the claim “Standardized tests measure nothing of value”?', options: ['Standardized tests measure absolutely nothing that anyone values', 'Standardized tests should be abolished in every state immediately', 'Standardized tests measure some skills but miss others that matter', 'Many students say standardized tests cause them considerable stress'], correctAnswer: 2, explanation: 'Qualifying a claim means limiting an absolute statement so it acknowledges complexity, which this revision does. Intensifying the absolute language makes the claim even easier to attack, and switching to a call for abolition or a point about stress changes the claim rather than qualifying it.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 2, part: 1 },
  { question: 'An article published this year argues that few adults shop online, citing a 2003 survey in which only 8 percent of adults had bought anything on the internet. What is the main problem with this evidence?', options: ['It is too dated to describe current habits', 'It comes from a survey rather than an expert', 'It is an anecdote, not a statistic', 'It is irrelevant to online shopping'], correctAnswer: 0, explanation: 'Strong evidence must be accurate and current, and shopping habits have changed enormously since 2003. The survey is a statistic, not an anecdote, and it is relevant to the topic. Survey data is not inherently weaker than expert opinion; its age is the issue.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 1, part: 1 },
  { question: 'A columnist once wrote that “electric cars will never be practical for rural drivers.” Years later, after charging stations have spread along rural highways, she wants to revise that claim to fit the new evidence. Which revision is most defensible?', options: ['Electric cars now suit many rural drivers, though charging gaps still limit some regions', 'Electric cars are now the only sensible choice for any rural driver', 'Electric cars will never be practical for rural drivers whatever charging exists', 'Rural drivers should be required by law to buy electric cars soon'], correctAnswer: 0, explanation: 'A defensible claim fits the evidence and is qualified where complexity exists; this revision credits the new stations while noting remaining gaps. Swinging to a new absolute overstates the change, and repeating the original ignores the new evidence. A legal mandate is a different policy claim that the evidence about charging does not support.', difficulty: 'hard', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 2, part: 1 },
  { question: 'A writer claims that the town library\'s new evening hours have drawn in more visitors after work. Her data: before the change, 9 percent of all visits began after 5 p.m.; after it, 31 percent did. Which statement most accurately describes what this data shows?', options: ['Working adults now make up most of the library\'s visitors', 'The library\'s total number of visitors more than tripled', 'Evening visits rose as a share of all visits', 'The new evening hours caused weekday visits to decline overall'], correctAnswer: 2, explanation: 'The figures are percentages of all visits, so they show that a larger share of visits now happen in the evening. They reveal nothing about total visitor counts, who the visitors are, or whether daytime visits fell. Accurate use of data means claiming no more than the numbers show.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 1, part: 1 },
  { question: 'A student\'s claim: “Requiring a semester of personal finance would reduce student debt among graduates.” Which piece of evidence most directly supports this specific claim?', options: ['Most adults say they wish they had learned more about money in school', 'Young adults from states that mandate the course carry smaller loan balances', 'Personal finance courses are popular electives at many high schools', 'Student debt across the nation has more than doubled over the past fifteen years'], correctAnswer: 1, explanation: 'Only this evidence connects the required course to lower debt, the exact relationship the claim asserts. Adults\' regrets and the popularity of electives are related to the topic but do not show any effect on debt. Rising national debt establishes that a problem exists, not that this course would reduce it.', difficulty: 'hard', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 2, part: 1 },
  { question: 'To argue that remote work boosts productivity, a writer quotes three enthusiastic employees from one software firm that hand-picked them for the interview. Which weakness in this evidence is most serious?', options: ['It has no connection to the claim at all', 'It may not mirror the wider workforce', 'It is drawn from an outdated source', 'It confuses a value claim with a fact'], correctAnswer: 1, explanation: 'Three hand-picked employees from one firm may be atypical, so the evidence is not representative of remote workers generally. Their comments about productivity are relevant to the claim, and nothing suggests the source is old. The claim about productivity is causal, not a value judgment, so the problem is whose voices were chosen.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 1, part: 1 },
  { question: 'On the AP English Language argument essay, the evidence and commentary row is worth up to how many of the six possible points?', options: ['One point', 'Two points', 'Three points', 'Four points'], correctAnswer: 3, explanation: 'Each AP English Language essay is scored from 0 to 6: one point for the thesis, up to four for evidence and commentary, and one for sophistication. The evidence and commentary row is therefore the largest share of the score, which is why explaining evidence matters so much.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence', formSet: 2, part: 1 },
  // englang-claims-evidence-reading
  { question: 'Read the passage: “Every summer, cities lose millions of gallons of water to leaky municipal pipes. Repairing this aging infrastructure, not rationing lawn watering, should be the first priority of drought planning.” Which choice states the writer\'s claim rather than merely the topic?', options: ['Urban water systems and how they waste water each summer', 'Drought planning in cities facing hot and dry summers', 'Fixing old pipes matters more than limiting how residents water lawns', 'Leaky pipes and lawn watering during long droughts'], correctAnswer: 2, explanation: 'A claim is a specific, arguable assertion; the writer argues that pipe repair should take priority over watering limits. The other choices only name subjects the passage discusses, which is the topic. Confusing topic with claim is a classic wrong answer on AP reading questions.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 1, part: 1 },
  { question: 'A passage on vaccine safety quotes a celebrated astrophysicist who calls a new vaccine “perfectly safe.” A careful reader should question this evidence mainly because the', options: ['expert\'s field is unrelated to medicine', 'quotation is too short to count as evidence', 'passage uses expert testimony instead of statistics', 'astrophysicist is too famous to be trusted on any topic'], correctAnswer: 0, explanation: 'Expert testimony is strong only when the expert is qualified in the relevant field, and astrophysics says nothing about vaccine safety. Expert testimony is a legitimate evidence type, so using it is not the flaw, and brevity does not disqualify a quotation. Fame is not the problem either; misplaced authority is.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 2, part: 1 },
  { question: 'In an essay arguing that cities should plant more street trees, one paragraph cites a study showing that shaded blocks were up to 10 degrees cooler, and the next paragraph begins: “Admittedly, tree roots can crack sidewalks and raise repair costs.” The second paragraph primarily serves to', options: ['present the writer\'s main claim for the first time', 'add further data on how trees cool blocks', 'rebut the study in the first paragraph', 'acknowledge a drawback of the writer\'s proposal'], correctAnswer: 3, explanation: '“Admittedly” signals a concession: the writer grants a real cost of planting trees, presumably before answering it. The main claim already appears in the essay\'s argument for more trees, and the paragraph neither adds cooling data nor attacks the writer\'s own study.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 1, part: 1 },
  { question: 'A passage claims: “Students who eat breakfast earn higher grades, so schools that serve free breakfast will raise achievement.” Which question would a careful reader most reasonably raise about this reasoning?', options: ['Is breakfast truly the most important meal of the day?', 'Could other factors explain why breakfast eaters do better?', 'Do schools have enough cafeteria space for breakfast programs?', 'Should students be required to eat breakfast at home instead?'], correctAnswer: 1, explanation: 'The passage moves from a correlation to a causal prediction, so the key question is whether something else, such as family stability, drives both breakfast and grades. The other questions concern nutrition in general, logistics, or an alternative policy, none of which tests the causal link the reasoning depends on.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 2, part: 1 },
  { question: 'A passage argues: “When the factory closed, the town\'s diner lost its lunch crowd; when the diner closed, the last gathering place on Main Street disappeared; and so the town lost its civic life.” The writer\'s support is best described as', options: ['a single statistic offered as proof of a broad claim', 'a sequence of linked effects that each depend on the step before', 'a historical analogy comparing two different towns', 'a hypothetical scenario about what might happen next'], correctAnswer: 1, explanation: 'The writer builds a causal chain in which each closing leads to the next loss. No number is cited, only one town is discussed, and the events are presented as having already happened rather than as an imagined future.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 1, part: 1 },
  { question: '“Imagine a city where every bus arrived on time and cost nothing to ride. How many drivers would still choose to sit in traffic?” The writer supports her case for free transit chiefly by using', options: ['an anecdote from her own commute', 'statistics on traffic congestion', 'a historical example from another city', 'a hypothetical scenario'], correctAnswer: 3, explanation: '“Imagine” invites the reader into an invented situation, which makes this a hypothetical scenario. The writer tells no personal story, cites no data, and refers to no real city\'s past.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 2, part: 1 },
  { question: 'A writer argues that a state\'s new reading curriculum has failed, citing the three schools whose scores dropped most sharply. She does not mention that scores rose at most of the state\'s other 200 schools. Her evidence is weakest in terms of', options: ['how typical the chosen examples are', 'whether the scores relate to reading', 'how recent the test data is', 'whether test scores are credible sources'], correctAnswer: 0, explanation: 'By selecting only the worst results and omitting the broader trend, the writer cherry-picks, so the evidence is not representative. Reading scores are relevant to a reading curriculum, nothing suggests the data is old, and the scores\' credibility is not in question.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 1, part: 1 },
  { question: '“Opponents warn that a sugary-drink tax burdens low-income families. But the revenue from the city\'s tax has funded free pre-kindergarten seats for thousands of those same families.” The second sentence functions as', options: ['a concession that grants the opponents\' point', 'the thesis of the entire argument', 'a rebuttal that turns the objection back on itself', 'an anecdote that illustrates what the opponents fear most'], correctAnswer: 2, explanation: 'After “But,” the writer answers the objection by showing that the very families said to be burdened benefit from the tax. Granting the point is what the first sentence does, not the second. The sentence supports a position rather than stating the whole argument, and it reports a policy result rather than one person\'s story.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 2, part: 1 },
  { question: 'An essay\'s thesis is that public libraries remain essential in the digital age. One paragraph notes that the oldest library in the country was founded in 1731. How does this detail relate to the thesis?', options: ['It proves the thesis by showing libraries have lasted for centuries', 'It concedes that libraries are outdated in the digital age', 'It serves as the main evidence for the essay\'s central claim', 'It provides history but does not itself show why libraries matter today'], correctAnswer: 3, explanation: 'The founding date is background; longevity alone does not demonstrate that libraries are essential now. Treating age as proof or as the main evidence overstates the detail, and nothing in a founding date concedes that libraries are obsolete. AP questions often test whether a detail actually supports the central claim.', difficulty: 'hard', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 1, part: 1 },
  { question: 'Which sentence from an editorial makes a causal claim?', options: ['The city council ought to repeal the new curfew.', 'Curfews unfairly punish teenagers who do nothing wrong.', 'The curfew begins at 11 p.m. on weeknights.', 'The new curfew has led to fewer late-night arrests.'], correctAnswer: 3, explanation: '“Has led to” links the curfew to an effect, which marks a causal claim. A call to repeal the curfew is a policy claim, calling curfews unfair is a value claim, and stating the curfew\'s start time is a factual claim.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 2, part: 1 },
  { question: 'A passage published last month argues that teenagers rarely read news online, supporting the claim with a survey taken before smartphones were common. A reader evaluating this support should note chiefly that the survey', options: ['comes from a source that is not named in the passage', 'may be too old to reflect how teens get news today', 'is a statistic rather than expert testimony from a scholar', 'uses too large a sample to be reliable for teens'], correctAnswer: 1, explanation: 'News-reading habits changed dramatically once smartphones spread, so old data may not describe teenagers today. Nothing indicates the source is unnamed, survey data is not weaker than testimony, and a large sample strengthens rather than weakens a survey.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 1, part: 1 },
  { question: '“Twenty years ago, I argued that standardized tests predicted college success better than grades did. The newer studies have changed my mind: grades, it turns out, tell admissions officers more.” The writer\'s reference to her earlier view primarily serves to', options: ['concede that her current claim is probably mistaken', 'show that the tests have become more accurate over time', 'build credibility by showing she follows the evidence', 'prove that grades and tests measure exactly the same skills'], correctAnswer: 2, explanation: 'Admitting a past position and explaining how evidence changed it presents the writer as fair-minded and data-driven, which strengthens her credibility. She stands by her current claim rather than doubting it, and she says nothing about tests improving or about grades and tests measuring identical skills.', difficulty: 'hard', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 2, part: 1 },
  { question: 'A passage reports that a city\'s recycling program collected 40 percent more material this year, then concludes: “Residents have clearly become more environmentally conscious.” What is the main weakness in moving from this data to that conclusion?', options: ['Other changes such as new packaging could explain the increase', 'Recycling programs are not a relevant subject for the passage', 'A forty percent rise is far too small to be worth noting', 'The writer cites data instead of quoting experts on recycling habits'], correctAnswer: 0, explanation: 'The conclusion assumes the rise was caused by changed attitudes, but more packaging, population growth, or expanded pickup could also explain it. The data is relevant and the rise is substantial. Citing data is not a flaw; drawing an unsupported causal conclusion from it is.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 1, part: 1 },
  { question: 'A writer claims a four-day workweek improved employee well-being at her company. Which piece of her evidence offers the strongest support?', options: ['Sick days fell by a third over two years compared with the year before the change', 'Her two closest colleagues told her they feel much better rested now', 'The company\'s revenue held steady during the first six months', 'A poll shows 70 percent of workers nationally want a shorter week'], correctAnswer: 0, explanation: 'A sustained drop in sick days at her own company, measured against a baseline, is direct, sufficient evidence about well-being there. Two colleagues are an unrepresentative anecdote, steady revenue concerns business results rather than well-being, and a national poll shows what workers want, not what the change did.', difficulty: 'hard', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 2, part: 1 },
  { question: 'When working through a nonfiction passage on the AP English Language multiple-choice section, which step should come first to make questions about evidence easier to answer?', options: ['Count the statistics in each paragraph', 'Label every emotional appeal in the text', 'Locate the author\'s main claim', 'Look up any words you find unfamiliar first'], correctAnswer: 2, explanation: 'Evidence can only be judged in relation to the claim it supports, so identifying the main claim gives a map for every later question. Counting statistics or labeling appeals without knowing the claim treats evidence as isolated details, and unfamiliar words can usually be handled in context.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 1, part: 1 },
  { question: 'A passage argues that national parks should cap daily visitors. Its third paragraph describes a ranger\'s account of trash-strewn trails and eroded switchbacks at a popular canyon park. The primary purpose of this paragraph is to', options: ['trace the history of the park\'s trails', 'illustrate the damage that overcrowding does', 'establish the ranger as the passage\'s narrator', 'argue that rangers should be paid to clean trails'], correctAnswer: 1, explanation: 'The ranger\'s account supplies concrete evidence of harm from too many visitors, supporting the claim for a cap. The paragraph is not a history, the ranger is a source rather than the narrator, and paying rangers is a different proposal the passage never makes.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-reading', formSet: 2, part: 1 },
  // englang-claims-evidence-writing
  { question: 'A student is drafting an argument essay on whether cities should ban cars from downtown streets. Which thesis is most defensible?', options: ['Cars are the single worst thing ever to happen to American cities', 'Many cities have downtown streets that are often crowded with cars', 'Cities should close some downtown streets to cars on a trial basis', 'Every city should ban all cars from downtown immediately and forever'], correctAnswer: 2, explanation: 'A defensible thesis is clear, debatable, specific, and qualified, and a limited trial on some streets meets all four. Calling cars the worst thing ever and demanding a permanent ban everywhere are absolute claims that are easy to attack. Noting that streets are crowded is a fact, not an arguable position.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 1, part: 1 },
  { question: 'A student\'s draft reads: “In 2023, the city\'s new bus lanes cut average commute times by eleven minutes. ___” The student is arguing that dedicated bus lanes are worth their cost. Which sentence best fills the blank as commentary?', options: ['Time returned to riders is the payoff the lanes buy.', 'Bus lanes have also been built in many other large cities.', 'The lanes were painted red to make them easy for drivers to see.', 'Some drivers complained that the new lanes made their own trips slower.'], correctAnswer: 0, explanation: 'Commentary explains how evidence supports the claim; this sentence frames the saved minutes as the return on the lanes\' cost. Mentioning other cities or the lanes\' color adds information without interpreting the evidence. Raising drivers\' complaints introduces a counterargument the paragraph does not answer.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 2, part: 1 },
  { question: 'A student\'s thesis reads: “Homework always harms students.” Which revision best addresses the problem of overstatement while keeping a clear position?', options: ['Homework harms students, as all of the research clearly proves', 'Some people like homework and some do not', 'Homework is a topic that teachers and students debate', 'Excessive homework harms students more than it helps'], correctAnswer: 3, explanation: 'Limiting the claim to excessive homework removes the absolute “always” while still taking a firm, arguable stand. Dropping “always” but claiming that all research proves the point trades one overstatement for another. Saying people disagree or that the topic is debated abandons a position altogether.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 1, part: 1 },
  { question: 'A student argues that a school\'s new phone-free lunch policy increased face-to-face conversation. The student wants to add evidence that best supports this causal link. Which addition is most effective?', options: ['A quote from the principal praising the policy as a bold step', 'Counts of students talking at tables taken before and after the ban', 'Statistics showing how many hours students spend on phones each week', 'A description of the cafeteria\'s new tables and brighter paint colors'], correctAnswer: 1, explanation: 'A before-and-after comparison of conversations directly measures the effect the student claims the policy caused. The principal\'s praise is opinion, weekly phone hours concern a general habit rather than the policy\'s effect, and new furniture could itself be a competing explanation.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 2, part: 1 },
  { question: 'A student\'s draft states: “Since the town installed brighter streetlights, burglaries have fallen, which proves the lights stopped the burglars.” Which revision most improves the logic of this claim?', options: ['The brighter lights went up and burglaries fell, proving that darkness alone causes crime', 'Burglaries fell after the brighter lights went up, a pattern that hints the lights may have helped', 'The town installed brighter streetlights, and residents now feel safer walking at night', 'Brighter lights clearly stopped the burglars, as the falling numbers plainly demonstrate'], correctAnswer: 1, explanation: 'The original treats a sequence in time as proof of cause; the best revision keeps the observation but claims only what it supports. Declaring that darkness alone causes crime, or that the numbers plainly demonstrate the cause, repeats the overreach. Shifting to residents\' feelings drops the claim about burglaries entirely.', difficulty: 'hard', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 1, part: 1 },
  { question: 'A student writing an argument essay on community gardens has three examples, all personal stories from her own neighborhood. To strengthen her evidence set, what should she add?', options: ['A fourth story from another neighbor about the gardens', 'A longer retelling of her favorite garden story', 'More vivid sensory details in each of her stories', 'Research data on gardens in many other cities'], correctAnswer: 3, explanation: 'Three anecdotes from one neighborhood rely on a single evidence type and a narrow sample, so adding research data creates a balanced, more representative evidence mix. Another story, a longer story, or more vivid details all deepen the same weakness.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 2, part: 1 },
  { question: 'A student argues that cities should invest in public transit now, even when ridership is low at first. Which historical example would best support this claim?', options: ['A subway line that drew small crowds early but later anchored new neighborhoods', 'A highway project that was cancelled after residents protested its route', 'A bus system that has carried steady crowds since the first day it ran', 'A transit agency that raised fares sharply to close a budget gap during a recession'], correctAnswer: 0, explanation: 'The claim is that low early ridership should not stop investment, so the best precedent is a line that started slowly and later paid off. A system that was busy from the start does not address slow beginnings, and a cancelled highway or a fare increase does not speak to the value of patient transit investment.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 1, part: 1 },
  { question: 'A student\'s paragraph argues for a citywide composting program and ends: “Admittedly, collecting food scraps adds a weekly cost for the sanitation department.” Which sentence, added next, best completes the counterargument move?', options: ['Composting has been practiced by farmers for thousands of years in many parts of the world.', 'The sanitation department also handles recycling and yard waste each week.', 'Yet every ton composted is a ton the city no longer pays to bury in its landfill.', 'This cost is real, and the city may simply be unable to afford it at all.'], correctAnswer: 2, explanation: 'After a concession, the writer must rebut; this sentence answers the cost concern by pointing to savings that offset it. Agreeing that the city may be unable to afford the program concedes the whole argument. Facts about farming history or the department\'s other duties leave the objection unanswered.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 2, part: 1 },
  { question: 'A body paragraph in a student\'s essay argues that school gardens improve students\' eating habits. It presents survey data and explains it, then ends with this sentence: “Gardens are also a nice place to sit.” Which revision of the final sentence best concludes the paragraph?', options: ['Gardens also give students a calm and shady place to sit between classes', 'Many schools have started gardens over the past twenty years or so', 'School gardens can be expensive to build and maintain each year', 'In short, students who grow their own vegetables become far more willing to eat them'], correctAnswer: 3, explanation: 'A strong body paragraph ends by reconnecting its evidence to the claim, and this sentence returns to the link between gardening and eating habits. The original and its expanded version drift to an unrelated benefit, and the other choices introduce history or cost, which pull away from the paragraph\'s point.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 1, part: 1 },
  { question: 'A student\'s body paragraph contains a claim, then three statistics in a row, then a sentence restating the claim in different words. What revision would most improve the paragraph?', options: ['Add a fourth statistic from a more recent study', 'Explain how each figure supports the claim', 'Replace the statistics with personal anecdotes instead', 'Move the restated claim to the start of the next paragraph'], correctAnswer: 1, explanation: 'The paragraph dumps evidence without commentary; restating the claim is not analysis. Adding more statistics or swapping in anecdotes changes the evidence but still leaves it unexplained, and moving the restatement does not supply the missing reasoning.', difficulty: 'hard', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 2, part: 1 },
  { question: 'A student\'s essay argues that cities must prepare for extreme heat. Her only evidence is a heat wave from 1995. Which addition would best show that the problem is current and urgent?', options: ['A longer account of the 1995 heat wave and its aftermath', 'A precise definition of what meteorologists count as a heat wave', 'Data on heat-related hospital visits from the past few summers', 'A quotation from a poem about summer heat in the city'], correctAnswer: 2, explanation: 'Recent data shows the danger continues now, which establishes relevance and urgency. Expanding the 1995 account keeps the evidence in the past, a definition clarifies terms without showing a current problem, and a poem adds mood rather than proof.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 1, part: 1 },
  { question: 'First draft thesis: “Online classes are worse than in-person classes.” After research, the student finds online classes worked well for adult learners with jobs but poorly for most high schoolers. Which revised thesis best reflects this research?', options: ['Online classes suit employed adults but tend to shortchange teenagers', 'Online classes are worse than in-person classes for every single learner', 'Online classes and in-person classes each have advantages and disadvantages', 'Online classes are the best option for any adults who hold jobs'], correctAnswer: 0, explanation: 'The revision tracks the research by drawing the distinction it found between adult workers and high schoolers. Keeping the blanket claim ignores the new evidence, and declaring online classes best for any adults with jobs overgeneralizes in the other direction. Saying both formats have pros and cons is too vague to argue.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 2, part: 1 },
  { question: 'A source reports that 18 of the 30 students surveyed at one high school prefer a later start time. Which sentence uses this evidence most accurately in a student\'s argument?', options: ['Most of the thirty students surveyed at one school favored a later start', 'Most American teenagers want their school day to start later in the morning', 'Nearly every student at that school wants the school day to start later', 'Eighteen percent of the students surveyed at the school prefer a later start'], correctAnswer: 0, explanation: 'Eighteen of thirty is a 60 percent majority of a small sample at one school, and the accurate sentence says exactly that. Extending the result to all American teenagers or nearly every student overstates it, and reporting the count as a percentage misreads the numbers.', difficulty: 'hard', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 1, part: 1 },
  { question: 'A student claims that her town\'s new skate park has reduced vandalism downtown. Which source would be most useful to cite?', options: ['An interview with a skater about the park\'s best ramps', 'A history of skateboarding as a sport in the country', 'Police reports of vandalism before and after', 'A news story about vandalism in a different city entirely'], correctAnswer: 2, explanation: 'Comparing local vandalism reports from before and after the park opened directly tests the claim. A skater\'s opinion of the ramps and the history of skateboarding are related to the park but not to vandalism, and another city\'s vandalism says nothing about this town.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 2, part: 1 },
  { question: 'On the AP English Language essays, which row of the scoring rubric rewards explaining how quotations and examples support a line of reasoning, and is worth the most points?', options: ['Sophistication', 'Evidence and commentary', 'Thesis and claim', 'Grammar and mechanics row'], correctAnswer: 1, explanation: 'The evidence and commentary row is worth up to four of the six points and rewards explaining how evidence supports the argument. The thesis row and the sophistication row are each worth one point, and the rubric has no separate grammar row.', difficulty: 'easy', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 1, part: 1 },
  { question: 'During the argument essay, a student plans to support her thesis with one personal anecdote repeated across all three body paragraphs. Based on what AP readers reward, what is the best advice?', options: ['Keep the single anecdote and simply describe it in more detail', 'Keep the anecdote but add a counterargument to each paragraph', 'Replace the anecdote with famous quotations', 'Vary the types of evidence and explain each one fully'], correctAnswer: 3, explanation: 'AP readers reward specific, varied evidence that is explained, not repeated or name-dropped. Describing one anecdote more fully still leaves a single, narrow evidence type, and adding counterarguments does nothing to broaden the support for the thesis itself. Swapping in quotations without commentary is still evidence-dumping.', difficulty: 'medium', domain: 'claims-evidence', topicSlug: 'englang-claims-evidence-writing', formSet: 2, part: 1 },

  // ── Domain: reasoning-organization ──────────────────
  // englang-reasoning-org-reading
  { question: 'A passage on urban heat reads: "Cities are warming faster than the countryside around them. In Phoenix, for instance, nighttime temperatures have climbed far more quickly than in nearby desert towns." The second sentence primarily functions to', options: ['introduce an objection the writer will later rebut', 'state the conclusion the passage builds toward', 'narrow the broad opening claim to one illustrative case', 'shift the focus to weighing two rival city policies'], correctAnswer: 2, explanation: 'The first sentence makes a broad claim, and "for instance" signals that the second narrows it to a single supporting case, a general-to-specific move. Nothing in the sentence opposes the claim, so reading it as an objection misreads it. It is evidence for the opening claim rather than a conclusion drawn from earlier points, and no policies are being compared.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 1, part: 1 },
  { question: 'In an essay on library funding, paragraph 2 details five years of budget cuts, paragraph 3 describes branches that have closed, and paragraph 4 opens: "Consequently, the residents who most depend on free internet access have lost it." Paragraph 4 relates to what precedes it chiefly as', options: ['effects that follow from earlier causes', 'a concession to critics of the library budget', 'a contrast between two competing funding plans', 'a broad principle drawn from one specific case'], correctAnswer: 0, explanation: '"Consequently" marks a result: the cuts and closures in paragraphs 2 and 3 are causes, and lost internet access is their effect. Nothing acknowledges an opposing view, so this is not a concession, and no alternative plans are being weighed. The paragraph reports a consequence rather than generalizing from a single example.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 2, part: 1 },
  { question: 'An op-ed argues that the city should extend its light-rail line. Paragraph 5 consists entirely of three statistics about average commute times, and the next paragraph moves on to construction costs without comment. Which best describes the weakness in paragraph 5\'s contribution to the line of reasoning?', options: ['It raises a counterargument and never answers it.', 'It offers data but never explains what the data show.', 'It states the thesis too late to guide the reader.', 'It repeats key terms so often that it feels redundant.'], correctAnswer: 1, explanation: 'Evidence advances an argument only when the writer interprets it and connects it to the claim; here the statistics sit unexplained, so the reader must guess how they support extending the line. The paragraph contains no opposing view, so an unanswered counterargument is not the problem. The thesis has already been stated, and repeating key terms actually helps cohesion rather than hurting it.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 1, part: 1 },
  { question: '"Some parents insist that nightly homework teaches discipline. Yet the students who most need that discipline are often the ones working evening shifts, with no quiet hour to give. A policy meant to build responsibility thus ends up penalizing the students already shouldering it." The final sentence functions chiefly as', options: ['a concession that the parents\' view has real merit', 'a restatement of the parents\' original position', 'an inference drawn from the rebuttal before it', 'new evidence supporting the opposing view'], correctAnswer: 2, explanation: 'The second sentence rebuts the parents\' claim with a counterexample, and "thus" signals that the final sentence draws a conclusion from that rebuttal. Treating it as a concession misses that it turns the parents\' own goal against their policy. It neither restates their position nor supplies evidence for it; it extends the writer\'s counterargument to its ironic conclusion.', difficulty: 'hard', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 2, part: 1 },
  { question: 'Which sentence from a passage most clearly signals a cause-effect organization?', options: ['Although rents have risen, many teachers still live within the city.', 'Unlike renters, homeowners have seen their housing costs hold steady.', 'For instance, one teacher now commutes ninety minutes each way.', 'Rising rents pushed teachers out, and that exodus led to larger classes.'], correctAnswer: 3, explanation: 'The sentence about rising rents traces a chain: rent increases cause teachers to leave, and their departure results in larger classes. The sentence beginning with "Although" sets up a concession, and the one beginning with "Unlike" draws a contrast. The commute example illustrates a point but does not link a cause to its effect.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 1, part: 1 },
  { question: '"When the town paved over its wetlands, stormwater lost its natural sponge. Each spring the river now crests higher, and basements that stayed dry for decades fill with water." The passage develops its point mainly by', options: ['deriving a general rule from a single case', 'moving from a cause to its effects', 'conceding a point and then rebutting it', 'weighing two alternatives against each other'], correctAnswer: 1, explanation: 'Paving the wetlands is the cause, and the higher river crests and flooded basements are its consequences, so the passage moves from cause to effect. It does not generalize from one example to a broader rule. No opposing view is acknowledged, and no alternatives are compared.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 2, part: 1 },
  { question: 'An essay opens with the story of a volunteer firefighter who quit after one season, then tells of a second who left, then a third. Only in its final paragraph does it argue that rural fire departments face a staffing crisis. This organization moves', options: ['from a problem toward a proposed solution', 'from a broad claim down to individual cases', 'from a concession to a rebuttal', 'from individual cases to a broad claim'], correctAnswer: 3, explanation: 'The essay accumulates individual stories first and draws the broader claim about a staffing crisis only at the end, a specific-to-general pattern. Reversing that order describes general-to-specific, which would put the crisis claim first. No solution is proposed, and the stories support rather than concede anything to an opposing view.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 1, part: 1 },
  { question: '"Drought is no longer a distant threat to the region\'s farms. Last August, a family orchard outside the county seat lost half its peach crop when its well ran dry." The reference to the family orchard primarily serves to', options: ['concede that the threat has spared most growers', 'introduce a view the writer will go on to rebut', 'shift the focus from growers to the city\'s water policy', 'make an abstract warning concrete with a vivid case'], correctAnswer: 3, explanation: 'The first sentence makes a general warning, and the orchard gives that warning a specific, tangible example. The example supports the claim rather than conceding exceptions or presenting an opposing view. The passage stays focused on agriculture; nothing turns to municipal policy.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 2, part: 1 },
  { question: 'Paragraph 3 of a passage explains how a new curfew reduced late-night vandalism downtown. Paragraph 4 begins, "_____, the curfew has done nothing to curb daytime shoplifting." Which transition best conveys the relationship between the two paragraphs?', options: ['As a result', 'On the other hand', 'For instance', 'Similarly'], correctAnswer: 1, explanation: 'Paragraph 4 contrasts the curfew\'s success at night with its failure during the day, so a contrast transition fits. "As a result" would wrongly present the shoplifting point as a result of reduced vandalism. "For instance" would treat it as an example of the previous point, and "Similarly" would signal agreement where the paragraphs actually diverge.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 1, part: 1 },
  { question: '"Rideshare drivers set their own hours. The companies, however, set the fares, the routes, and the penalties for declined trips. This is why the freedom the drivers were promised is narrower than it appears." The word "This" at the start of the third sentence links the sentences by', options: ['pointing back to the companies\' control', 'introducing a new example of driver freedom', 'signaling a concession to the companies\' critics', 'marking a shift from evidence to a counterargument'], correctAnswer: 0, explanation: '"This" refers back to the companies\' control over fares, routes, and penalties, and that reference lets the third sentence draw its conclusion from the second. The sentence limits driver freedom rather than adding an example of it. Nothing concedes anything to critics, and the third sentence is the writer\'s own conclusion, not an opposing argument.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 2, part: 1 },
  { question: 'An editorial spends three paragraphs praising a city\'s new bike-share program, then opens paragraph 4: "But a program that serves only riders downtown is not yet a public service." Paragraph 4 most likely marks a shift from', options: ['approval of the program to a qualification of it', 'background on the program to the editorial\'s thesis', 'evidence for one benefit to evidence for another', 'a rebuttal of critics to a concession'], correctAnswer: 0, explanation: 'After three paragraphs of praise, "But" introduces a limit on that praise: the program is good yet incomplete, which qualifies the earlier assessment. The opening paragraphs evaluate the program rather than supply neutral background. Paragraph 4 names a shortcoming rather than another benefit, and no critics have been addressed earlier for the writer to concede to.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 1, part: 1 },
  { question: '"Supporters of the stadium promise jobs; opponents warn of traffic and debt. Both camps, though, assume the only question is whether to build. The more useful question is who will own what gets built." The third sentence primarily functions to', options: ['side with opponents by stressing the costs of building', 'concede the supporters\' point about new jobs', 'reframe the debate around an issue neither side raises', 'summarize both positions before choosing one'], correctAnswer: 2, explanation: 'The second sentence identifies an assumption both sides share, and the third replaces their question with a new one about ownership, turning the debate in a new direction. The writer does not endorse either camp, so siding with opponents or conceding to supporters misreads the move. The sentence goes beyond summary and never chooses between the two existing positions.', difficulty: 'hard', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 2, part: 1 },
  { question: 'A passage argues that high schools should require a personal-finance course. Paragraph 2 cites a survey showing that most graduates cannot explain how interest works; paragraph 3 immediately calls for the requirement. A reader finds the jump from paragraph 2 to paragraph 3 unconvincing. Which missing step best explains the reader\'s reaction?', options: ['Some statistic showing how many graduates struggle', 'Some description of what the course would cover', 'Some reasoning showing that a course would close the gap', 'Some concession that many families teach money skills'], correctAnswer: 2, explanation: 'The survey establishes a problem, but nothing explains why a required course is the way to solve it, so the link between evidence and proposal is missing. The survey already supplies statistics, and describing the course\'s content would not show that it fixes the gap. A concession might add nuance, but its absence does not explain why the jump itself feels unsupported.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 1, part: 1 },
  { question: '"Teen readership of print newspapers fell by half over the past decade. Clearly, teenagers no longer care about current events." The reasoning in this passage is weakest because the writer', options: ['treats one news format as the only way to stay informed', 'states the conclusion before offering any evidence', 'relies on a concession that undercuts the claim', 'uses a statistic that contradicts the conclusion'], correctAnswer: 0, explanation: 'The leap from declining print readership to indifference toward current events assumes print is the only way to follow the news, an unstated link the writer never defends. The evidence actually comes first, so the order is not the problem. The passage contains no concession, and the statistic is consistent with the conclusion; the flaw lies in the inference connecting them.', difficulty: 'hard', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 2, part: 1 },
  { question: 'Paragraph 1 of a passage claims that the loss of factory jobs has hollowed out small manufacturing towns. Paragraph 2 describes a single plant closing and the shuttered diner across the street. A question asks what paragraph 2 primarily does. Which answer best addresses the function of paragraph 2?', options: ['It describes a plant that closed in one town.', 'It grounds the opening claim in a concrete case.', 'It rebuts the opening claim with an exception.', 'It concedes that the opening claim has some limits.'], correctAnswer: 1, explanation: 'A function question asks what role the paragraph plays in the argument, and paragraph 2 supports the opening claim by illustrating it with a specific case. Describing the plant closing merely summarizes the paragraph\'s content without naming its role. The example confirms the claim rather than rebutting or limiting it.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 1, part: 1 },
  { question: '"Admittedly, a four-day school week saves districts money on buses and heating. What it costs families in child care, however, quickly erases those savings." Taken together, the two sentences', options: ['present two separate benefits of a shorter week', 'compare the budgets of two districts', 'define savings before giving an example', 'acknowledge a benefit and then outweigh it'], correctAnswer: 3, explanation: '"Admittedly" grants the opposing side a real advantage, and "however" introduces a cost that outweighs it, the concession-rebuttal pattern. The second sentence names a drawback, not a second benefit. No two districts are compared, and nothing is being defined.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-reading', formSet: 2, part: 1 },
  // englang-reasoning-org-writing
  { question: 'A student\'s thesis argues that the school district should replace suspensions for tardiness with mentoring. The topic sentence of body paragraph 2 reads: "Mentoring programs exist in many places." Which revision best makes this topic sentence advance the thesis?', options: ['Mentoring programs now exist in many districts across the country.', 'Suspensions and mentoring are two common responses to lateness.', 'Mentoring has a long and well-documented history in schools.', 'Mentoring addresses the causes of lateness that suspensions merely punish.'], correctAnswer: 3, explanation: 'A topic sentence works as a mini-claim, and the revision about causes of lateness states a reason that links directly to the thesis by contrasting mentoring with suspension. Adding detail about how widespread mentoring is still leaves the sentence a fact rather than a reason. Naming both responses without favoring one makes no claim, and a history of mentoring drifts away from the argument about tardiness.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 1, part: 1 },
  { question: 'A student writes: "Uniform policies reduce visible signs of income differences among students. _____, uniforms cannot erase the gaps that show up in who can afford tutoring or summer programs." Which transition best fits the relationship between the two sentences?', options: ['Furthermore', 'Consequently', 'However', 'For example'], correctAnswer: 2, explanation: 'The second sentence limits the benefit claimed in the first, so a contrast transition is needed. "Furthermore" would present the limitation as an additional benefit, and "Consequently" would wrongly make it a result of uniforms reducing visible differences. "For example" would treat it as an illustration of the first sentence rather than a qualification of it.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 2, part: 1 },
  { question: 'A draft reads: "Later start times give teenagers more sleep on school nights. ______, some districts worry that a later bell would complicate bus schedules." Which transition best fits the blank?', options: ['However', 'Therefore', 'In addition', 'Indeed'], correctAnswer: 0, explanation: 'The second sentence raises a concern that cuts against the benefit in the first, so a contrast transition marks the relationship. "Therefore" would present the bus worry as a result of extra sleep, "In addition" would treat it as another benefit, and "Indeed" would present it as emphasis of the same point.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 1, part: 1 },
  { question: 'A student\'s argument essay on banning phones in class ends: "In conclusion, phones distract students, phones hurt grades, and phones reduce face-to-face conversation. That is why phones should be banned." Which revision would best strengthen the conclusion?', options: ['Add a statistic on phone use that the essay has not yet cited', 'Explain what schools would gain from such a ban', 'Restate each body paragraph\'s reason in fuller detail', 'End with an expert\'s quotation on the topic'], correctAnswer: 1, explanation: 'The conclusion only lists the reasons again; a strong conclusion synthesizes them and explains the stakes, which is what describing the gains of a ban does. New statistics belong in the body, not the conclusion. Fuller restatement deepens the summary problem, and an expert quotation adds a voice without explaining why the argument matters.', difficulty: 'hard', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 2, part: 1 },
  { question: 'A student writes: "The district cut its bus routes in half last spring. _____, attendance at the two most rural schools dropped sharply by October." Which transition best signals the logical relationship between the sentences?', options: ['In contrast', 'Consequently', 'Admittedly', 'Similarly'], correctAnswer: 1, explanation: 'The second sentence describes an effect of the cuts in the first, so a result transition fits. "In contrast" would set the sentences against each other, and "Admittedly" would frame the attendance drop as a concession. "Similarly" would present the drop as a parallel example rather than a consequence.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 1, part: 1 },
  { question: 'In a paragraph arguing that free breakfast programs raise test scores, a student cites data showing that scores rose after one district began serving breakfast. The writer wants to add a sentence explaining how breakfast could produce that result. Which choice most effectively accomplishes this goal?', options: ['Breakfast programs are popular with students and parents in many districts.', 'The program cost the district less than its planners had expected it to.', 'Some critics argue that the scores rose for other reasons entirely.', 'Students who are not hungry can focus longer in class.'], correctAnswer: 3, explanation: 'The writer needs the causal link between eating breakfast and scoring higher, and the sentence about hunger and focus supplies that mechanism. Popularity and cost are related to the program but do not explain why scores would rise. Raising an alternative explanation introduces a counterargument rather than the missing link.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 2, part: 1 },
  { question: 'A student\'s essay supporting a city curfew has three body paragraphs. One argues the curfew would reduce late-night crime. A second argues it would free overnight officers for other patrols. A third answers critics who say the curfew is too costly to enforce by pointing to the officer hours saved. Where should the paragraph answering critics go?', options: ['Directly after the introduction, before either reason', 'Between the paragraphs on crime and on officer hours', 'After the paragraphs on crime and on officer hours', 'In the conclusion, in place of a final synthesis'], correctAnswer: 2, explanation: 'The rebuttal depends on the officer hours established in the second reason, so it must follow both supporting paragraphs. Placing it first or between the reasons would ask readers to accept savings the essay has not yet explained. Folding it into the conclusion would sacrifice the synthesis a conclusion should provide.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 1, part: 1 },
  { question: 'A student\'s paragraph reads: (1) Community gardens give city residents access to fresh produce. (2) In one neighborhood, volunteers planted a garden on a vacant lot three years ago. (3) Today, residents there buy fresh vegetables at its weekly market, a short walk from home. The writer wants to add: "Before the garden opened, residents there bought most of their food at corner stores." Where should this sentence go?', options: ['After sentence 2', 'Before sentence 1', 'After sentence 3', 'After sentence 1'], correctAnswer: 0, explanation: '"The garden" and "there" need the specific garden and neighborhood introduced in sentence 2, and the "before" picture must come ahead of sentence 3\'s "today" so the contrast runs in time order. Placed before or after sentence 1, the sentence would refer to a garden not yet mentioned. Placed last, it would jump back in time after "today" and end the paragraph on corner stores instead of the gain in access.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 2, part: 1 },
  { question: 'A student writes: "The council approved the recycling contract and the composting pilot, but it has already run over budget." The sentence is unclear chiefly because', options: ['it needs a transition word at the very start', 'the verb tense shifts partway through the sentence', 'the pronoun could refer to more than one antecedent', 'the claim about the budget is stated too forcefully'], correctAnswer: 2, explanation: '"It" could refer to the council, the contract, or the pilot, so the reader cannot tell what ran over budget. A transition would not resolve the unclear reference. The shift from "approved" to "has run" is logical, and the sentence makes no overstated claim.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 1, part: 1 },
  { question: 'A student\'s thesis argues that public libraries are essential support for job seekers. Body paragraph 1 describes free internet access and résumé workshops, then ends: "Many patrons also enjoy the library\'s film nights." Which revision of this final sentence best links the paragraph back to the thesis?', options: ['Film nights are among the many popular events that libraries host.', 'Those free tools can help a job seeker get hired sooner.', 'Job seekers, though, may not have time for the library\'s events.', 'Libraries have offered free public events for more than a century.'], correctAnswer: 1, explanation: 'Ending a paragraph by tying its evidence to the thesis strengthens coherence, and connecting the free tools to getting hired does exactly that. The sentence about film nights keeps the paragraph drifting toward entertainment. Noting that job seekers may lack time undercuts the claim, and the history of library events is off topic.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 2, part: 1 },
  { question: 'A student\'s thesis reads: "Standardized tests are useless and should be abolished." The body paragraphs argue that tests miss creativity and penalize anxious test takers, and one paragraph concedes that test results help identify schools needing resources. Which revision of the thesis best fits the essay\'s actual line of reasoning?', options: ['Standardized tests are entirely useless and should be abolished at once.', 'Standardized tests have strengths and weaknesses worth considering.', 'Standardized tests help schools and should be expanded nationwide.', 'Tests can flag schools in need but are too narrow to judge individuals.'], correctAnswer: 3, explanation: 'The essay concedes one real use of tests while arguing they fail individuals, so a qualified thesis that does both matches its reasoning. Making the claim more absolute contradicts the essay\'s own concession. Listing strengths and weaknesses takes no position, and calling for expansion reverses the essay\'s argument.', difficulty: 'hard', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 1, part: 1 },
  { question: 'A student\'s essay arguing for a four-day school week includes a paragraph describing the child-care burden on working parents, and the paragraph ends without returning to the essay\'s position. Which revision would most improve this paragraph\'s role in the argument?', options: ['Add a response showing why the benefits outweigh that burden', 'Delete the paragraph so the essay covers only supporting reasons', 'Move the paragraph to the start of the introduction', 'Add more detail on the size of the child-care burden'], correctAnswer: 0, explanation: 'A counterargument helps an essay only when the writer answers it, so adding a rebuttal turns a damaging paragraph into evidence of complexity. Deleting it throws away the chance to address an objection readers will raise. Moving it or enlarging the burden leaves the objection unanswered.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 2, part: 1 },
  { question: 'A student\'s body paragraph is meant to argue that later start times improve teen health. Midway through, it shifts into describing the cost of new bus contracts. What is the most effective revision?', options: ['Move the bus-cost material into a paragraph of its own', 'Add a transition before the bus-cost sentences', 'Add a second health study to balance the bus material', 'Shorten each sentence to tighten the paragraph'], correctAnswer: 0, explanation: 'The paragraph drifts off its claim, so the cost material must leave it and be developed separately if it belongs in the essay at all. A transition would smooth the jump but leave two topics in one paragraph. More health evidence or shorter sentences do not remove the off-topic material.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 1, part: 1 },
  { question: 'A draft paragraph reads: "Social media harms teen sleep. A recent survey found that most teens check their phones after midnight. This shows that social media harms teen sleep." Which revision would most improve the commentary in the final sentence?', options: ['Restate the survey statistic in different words for emphasis', 'Add a second survey that reports a similar percentage', 'Explain how late scrolling robs teens of rest', 'Qualify the claim by noting that some teens avoid social media'], correctAnswer: 2, explanation: 'The final sentence simply repeats the claim, so the commentary needs to explain how the evidence proves it, here by showing how late phone use reduces rest. Restating the statistic is summary, not commentary, and another survey adds evidence without reasoning. A qualification can add nuance, but it does not fix the missing link between data and claim.', difficulty: 'hard', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 2, part: 1 },
  { question: 'A student has forty minutes to write the argument essay. Which plan best reflects strong organization for a high-scoring response?', options: ['Cover six or seven reasons briefly so that no angle is missed', 'Spend most of the time crafting an elaborate, attention-grabbing introduction', 'Save the thesis for the conclusion so it builds suspense', 'Develop two or three reasons with commentary after each piece of evidence'], correctAnswer: 3, explanation: 'A line of reasoning is built from a few well-developed reasons, each with evidence explained through commentary. Many brief reasons produce shallow, disconnected points. An elaborate introduction steals time from development, and withholding the thesis leaves readers without a direction to follow.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 1, part: 1 },
  { question: 'A student\'s essay argues that cities should convert unused parking garages into housing. Which sentence would most effectively open the conclusion?', options: ['In conclusion, this essay has discussed parking garages and housing.', 'Empty garages are a housing supply hiding in plain sight.', 'Parking garages first spread widely in the 1950s.', 'Another reason to convert garages is that construction creates jobs.'], correctAnswer: 1, explanation: 'A strong conclusion restates the thesis with fresh nuance, and the image of a hidden housing supply does that while setting up the stakes. Announcing what the essay discussed is empty summary. Historical background and a brand-new reason both introduce material that belongs in the body, not the conclusion.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-reasoning-org-writing', formSet: 2, part: 1 },
  // englang-argument-structure
  { question: '"For most commuters who travel under ten miles, an e-bike costs less to own than a second car." The phrase "for most commuters who travel under ten miles" functions as', options: ['a warrant linking the evidence to the claim', 'a qualifier that limits how far the claim reaches', 'a rebuttal of an anticipated objection', 'backing that supports the warrant'], correctAnswer: 1, explanation: 'The phrase restricts the claim to a particular group, which is the job of a qualifier. A warrant is the assumption connecting evidence to claim, and backing supports that assumption; the phrase does neither. It also does not answer any objection, so calling it a rebuttal misreads its role.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 1, part: 1 },
  { question: '"Our town\'s library hours were cut last year, and reading scores at the elementary school fell. The council should restore the hours." Which unstated assumption must the audience accept for this argument to work?', options: ['Reading scores matter more than any other results in the district', 'The council has never cut library hours in past budget years', 'Elementary students prefer the library to reading at home', 'The cut hours helped cause the drop in scores'], correctAnswer: 3, explanation: 'The argument moves from two facts that happened together to a remedy, so it depends on the unstated warrant that the reduced hours contributed to the decline. Ranking reading above other results is not needed to accept the claim. The council\'s past budgets and students\' preferences are beside the point; neither bridges the evidence to the call to restore hours.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 2, part: 1 },
  { question: 'A student is writing to a town board whose members have twice voted against a proposed dog park. Which opening would best suit a Rogerian approach?', options: ['Begin by listing the flaws in the board\'s earlier votes', 'Open with the strongest statistic in favor of the park', 'Begin with concerns that the writer and the board share', 'Open by announcing the proposal and the date of the next vote'], correctAnswer: 2, explanation: 'A Rogerian argument starts by establishing common ground so a resistant audience is less defensive, which is what opening with shared concerns does. Attacking the board\'s earlier votes would harden opposition. Leading with a statistic or with the proposal itself skips the common ground a hostile audience needs first.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 1, part: 1 },
  { question: 'A writer tells a group of small-business owners: "The minimum wage has lost a third of its buying power since 1970, so lawmakers should raise it." Several owners accept the statistic yet reject the conclusion. In terms of the Toulmin model, the most likely explanation is that they', options: ['doubt that the loss by itself demands a remedy', 'distrust the source of the buying-power figure', 'object that the claim comes before the evidence', 'want more examples of affected workers'], correctAnswer: 0, explanation: 'When an audience accepts the evidence but not the claim, the break usually lies in the warrant, here the assumption that lost buying power obligates a wage increase. Distrusting the figure contradicts the owners\' acceptance of the statistic. The evidence actually comes first in the sentence, and more examples would only add evidence the owners already grant.', difficulty: 'hard', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 2, part: 1 },
  { question: 'An op-ed traces how a factory\'s closure drained the town\'s tax base and how that loss then forced cuts to the school budget, before urging the state to provide emergency aid. Which pattern does the op-ed follow?', options: ['Identify causes, show the effects, then argue for action', 'Find common ground, present a view, then compromise', 'Hook the reader, give background, then refute critics', 'State a claim, offer data, then supply a warrant'], correctAnswer: 0, explanation: 'The op-ed links a cause to a chain of effects and ends with a call for aid, which is the cause-effect structure. Nothing seeks common ground or proposes a compromise, as a Rogerian argument would. No critics are refuted, and the piece is organized around a causal chain rather than the claim-evidence-warrant breakdown of the Toulmin model.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 1, part: 1 },
  { question: '"Each winter, the shelter turns away dozens of people on the coldest nights. Converting the vacant armory would add sixty beds within a month. Critics worry about the cost, but state housing grants would cover most of it." The third sentence corresponds to which stage of a problem-solution argument?', options: ['Describing the scope of the problem', 'Proposing a solution to the problem', 'Answering an objection to the plan', 'Finding common ground with opponents'], correctAnswer: 2, explanation: 'The third sentence raises the critics\' concern about cost and responds to it, the objection-handling stage. The first sentence describes the problem and the second proposes the solution. No common ground is sought; the writer rebuts the critics rather than meeting them halfway.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 2, part: 1 },
  { question: 'A student\'s speech opens with an anecdote about a flooded basement, explains how the city\'s storm drains were built a century ago, declares that the city must replace them, and presents cost data and expert testimony before closing with an appeal to voters. Measured against classical structure, which section is missing?', options: ['A narration that gives historical background', 'A proposition that states the thesis', 'A confirmation that presents support', 'A refutation that answers opposing views'], correctAnswer: 3, explanation: 'The speech never acknowledges or answers anyone who disagrees, so it lacks a refutation. The history of the drains serves as narration, the declaration that the city must replace them is the proposition, and the cost data and testimony form the confirmation.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 1, part: 1 },
  { question: '"Everyone in this room wants our children to walk to school safely, and everyone here is tired of paying for projects that never get finished. I share both frustrations. That is why I am asking you to consider a smaller plan: crossing guards at three intersections, funded for one year, with a vote to renew." The speaker\'s strategy most closely resembles', options: ['a Toulmin backing for an unstated warrant', 'Rogerian common ground before a compromise', 'a classical refutation of the audience\'s view', 'a cause-effect chain that leads to action'], correctAnswer: 1, explanation: 'The speaker opens with values the audience already holds, aligns with their frustrations, and then offers a scaled-down plan, the Rogerian pattern. Nothing refutes the audience; the speaker agrees with them. The passage does not support a warrant or trace causes to effects.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 2, part: 1 },
  { question: 'In an argument essay, one paragraph lays out an opponent\'s objection to a recycling program. The next paragraph begins, "_____, the objection ignores how much the program has already saved." Which transition best signals a rebuttal following that concession?', options: ['Moreover', 'For example', 'Similarly', 'Nevertheless'], correctAnswer: 3, explanation: 'The second paragraph pushes back against the objection the first one granted, so a transition that signals rebuttal after concession is needed. "Moreover" would add the point as further support for the objection. "For example" and "Similarly" would present the paragraph as an illustration of or parallel to the objection rather than a reply to it.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 1, part: 1 },
  { question: 'A writer claims that the city should plant street trees, cites data showing that tree-lined blocks stay cooler in summer, and relies on the warrant that cooler streets protect residents\' health. Which sentence would best serve as backing for that warrant?', options: ['Extreme heat sends thousands of people to emergency rooms.', 'Tree-lined blocks were up to ten degrees cooler on the hottest days.', 'Some residents object that tree roots damage sidewalks and pipes.', 'The city should plant trees on every residential block by next year.'], correctAnswer: 0, explanation: 'Backing supports the warrant itself, and evidence that extreme heat harms people shows why cooler streets protect health. The temperature data is the original evidence, not support for the warrant. The complaint about roots is an objection, and the planting goal restates the claim.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 2, part: 1 },
  { question: 'A student\'s argument essay for year-round schooling presents three supporting reasons but never mentions the common objection that families would lose summer travel time. Which revision would most strengthen the essay\'s structure?', options: ['Add a fourth supporting reason about test scores', 'Add a section that concedes the objection and answers it', 'Open the essay by stating the objection as its own thesis', 'Remove one reason so the essay seems more focused'], correctAnswer: 1, explanation: 'An argument that ignores an obvious objection leaves readers\' doubts unanswered, so adding a concession and rebuttal strengthens the structure. Another supporting reason adds more of what the essay already has. Making the objection the thesis would reverse the argument, and cutting a reason does nothing to address the missing refutation.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 1, part: 1 },
  { question: '"Students who eat lunch after 1:00 p.m. visit the school nurse twice as often as those who eat at noon. The school should therefore move all lunch periods earlier." Which unstated assumption most directly links the evidence to the claim?', options: ['Nurse visits are logged the same way all day', 'Students would rather eat lunch at noon than later', 'The late lunch hour itself causes the extra visits', 'Moving lunch earlier would cost the school nothing'], correctAnswer: 2, explanation: 'The data show only that late lunch and nurse visits occur together; recommending earlier lunches assumes the timing is what produces the visits. Consistent record keeping and low cost might matter to the proposal, but neither bridges the correlation to the remedy. Student preferences are irrelevant to whether the change would reduce visits.', difficulty: 'hard', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 2, part: 1 },
  { question: 'A student\'s draft argues: "The school should ban energy drinks. Energy drinks contain a lot of caffeine." A peer reviewer says the argument has a gap. Which addition would best supply the missing warrant?', options: ['Cite the exact caffeine content of several popular brands', 'Note that some students drink them before sports games', 'Explain why that much caffeine harms teenagers\' health and focus', 'Restate that the school should ban the drinks outright'], correctAnswer: 2, explanation: 'The draft never says why high caffeine justifies a ban; explaining the harm to students supplies that bridge. Exact caffeine figures add evidence but leave the same gap. Describing when students drink them is a detail, and restating the claim adds no reasoning at all.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 1, part: 1 },
  { question: '"Cities that eliminated parking minimums saw more housing built within five years. Because zoning rules shape what developers can afford to build, our city should drop its parking minimums too." The clause beginning with "Because" functions chiefly as', options: ['evidence drawn from comparable cities\' records', 'the warrant linking the data to the claim', 'a qualifier that limits the scope of the claim', 'a rebuttal of an objection the writer expects'], correctAnswer: 1, explanation: 'The clause states the principle that lets results from other cities apply to this one, so it bridges the data and the claim as a warrant. The evidence is the housing record in the first sentence. The clause neither narrows the claim nor answers an opposing view; warrants are often unstated, but here the writer spells it out.', difficulty: 'hard', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 2, part: 1 },
  { question: '"Remote work raises productivity for most software teams. Teams that depend on hands-on lab equipment are the obvious exception, and nothing here argues that they should leave the building." The second sentence functions mainly as', options: ['an admission of cases the claim does not cover', 'backing that supports the writer\'s warrant', 'evidence proving that the main claim holds for every team', 'a call to action aimed at lab-based teams'], correctAnswer: 0, explanation: 'The second sentence names a group to which the claim does not apply and sets it aside, acknowledging an exception. It does not support the warrant or add evidence for higher productivity. Far from urging lab teams to act, it explicitly says they should stay where they are.', difficulty: 'medium', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 1, part: 1 },
  { question: 'In a classical argument, a writer has stated the thesis and now presents statistics, examples, and expert testimony in its support. Which section of the argument is this?', options: ['Narration', 'Introduction', 'Refutation', 'Confirmation'], correctAnswer: 3, explanation: 'The confirmation is where the writer develops support for the thesis with evidence. Narration supplies background and the introduction hooks the reader before the thesis. Refutation answers opposing views rather than presenting the writer\'s own support.', difficulty: 'easy', domain: 'reasoning-organization', topicSlug: 'englang-argument-structure', formSet: 2, part: 1 },

  // ── Domain: style ───────────────────────────────────
  // englang-diction-syntax
  { question: 'A city council member drafts the same sentence three ways: "The library\'s hours were reduced," "The library\'s hours were gutted," and "The library\'s hours were streamlined." The differences among the drafts are chiefly a matter of', options: ['sentence structure, shifting the order of subject and verb', 'register, moving from formal phrasing to informal slang', 'connotation, giving one event a distinct emotional coloring', 'specificity, swapping concrete detail for abstract terms'], correctAnswer: 2, explanation: 'All three drafts share one structure and report one event; only the verb changes, and each verb carries a different emotional charge (neutral, violent, approving). That is connotation. The word order never changes, none of the verbs is slang, and none of them is more concrete or abstract than the others.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 1, part: 1 },
  { question: '"Before the first bell, before the buses, before the coffee has cooled in the faculty lounge, the custodians have already unlocked every door." The structure of this sentence primarily serves to', options: ['withhold the subject to spotlight unnoticed workers', 'mimic the rush of a school morning through a series of fragments', 'contrast the custodians\' routine with the teachers\' late arrival', 'list the school\'s daily problems to build a case for reform'], correctAnswer: 0, explanation: 'The sentence is periodic: three introductory phrases delay the main clause, so the custodians arrive last and get the emphasis, which shows that their work is done before anyone else is around. It is one complete sentence, not a run of fragments. No teachers arrive late, and the phrases mark time rather than list problems.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 2, part: 1 },
  { question: '"The water came out brown. It smelled like pennies. Mrs. Alvarez boiled it anyway, because the baby needed a bath." Which choice best describes how the passage creates its effect?', options: ['Abstract diction and long periodic sentences lend the account real weight', 'Concrete sensory detail in short declaratives makes hardship immediate', 'Technical vocabulary and balanced clauses give the account authority', 'Loaded adjectives and rhetorical questions direct anger at officials'], correctAnswer: 1, explanation: 'Brown water and a smell of pennies are concrete sensory details, and the short, plain sentences present them without commentary, so the hardship feels close and real. The diction is not abstract or technical, the sentences are not periodic or balanced, and the passage asks no questions and names no officials.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 1, part: 1 },
  { question: 'A student writes: "The speaker uses parallel structure in the line \'we built the roads, we staffed the clinics, we taught the children.\'" Which revision best turns this observation into analysis?', options: ['The speaker repeats the pattern of we plus a past-tense verb three separate times in one line.', 'The parallel line is an effective device that makes the whole speech more persuasive overall.', 'The speaker lists roads, clinics, and schools to show the many jobs workers once held.', 'By stacking three we clauses, the speaker makes the workers\' claim to credit feel earned.'], correctAnswer: 3, explanation: 'Analysis explains what a choice does for the speaker\'s purpose, and stacking the clauses builds up the workers\' contributions until their claim to recognition feels earned. Counting the repetitions only describes the device again. Calling the line effective and persuasive is vague praise, and listing the jobs is a summary of content that says nothing about the structure.', difficulty: 'hard', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 2, part: 1 },
  { question: 'A writer revises "The company asked employees to return to the office" to "The company ordered employees back to the office." What is the most likely effect of the revision?', options: ['It makes the company sound more polite toward its staff', 'It casts the firm as more forceful and less willing to bargain', 'It adds technical precision about the new work policy', 'It shifts the sentence into a more informal register'], correctAnswer: 1, explanation: '"Ordered" carries a commanding connotation that "asked" lacks, so the revised sentence presents the employer as forceful and unwilling to negotiate. It makes the company sound less polite, not more. Both verbs are everyday words, so the revision adds no technical precision and does not change the register.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 1, part: 1 },
  { question: 'In a commencement speech, a speaker follows four long, winding sentences about uncertainty with "You will fail." The sudden short sentence most likely causes listeners to', options: ['lose track of the speech\'s larger argument about uncertainty', 'relax into the comforting rhythm the long sentences built', 'brace for a blunt and unwelcome truth', 'see the speaker as unsure of the claim being made'], correctAnswer: 2, explanation: 'A short sentence after several long ones breaks the rhythm and lands with force, so listeners stop and take in the hard truth. The contrast sharpens the argument instead of confusing it. It interrupts the comfortable rhythm rather than continuing it, and its flat certainty makes the speaker sound sure, not hesitant.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 2, part: 1 },
  { question: 'Version 1: "The flood destroyed the bridge, the mill, and the school." Version 2: "The flood destroyed the bridge. It destroyed the mill. It destroyed the school." Compared with Version 1, Version 2 primarily', options: ['speeds up the account by trimming repeated words', 'softens the losses by spreading them across several sentences', 'adds new details about the damage to the town', 'slows the pace and makes each loss land separately'], correctAnswer: 3, explanation: 'Splitting the series into three sentences that repeat the same verb slows the reader and gives each loss its own full stop, so each one feels heavy. Version 2 adds words rather than trimming them. Separating the losses intensifies them instead of softening them, and the facts in both versions are the same.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 1, part: 1 },
  { question: '"We will not wait for permission. We will not wait for funding. We will not wait for someone else to notice." The repetition at the start of each sentence is an example of', options: ['anaphora', 'irony', 'inversion', 'a fragment'], correctAnswer: 0, explanation: 'Repeating the same words at the beginning of successive sentences is anaphora, which builds momentum and emphasis. Inversion reverses normal word order, and these sentences keep standard subject-verb order. Each sentence is grammatically complete, so none is a fragment, and nothing in the lines says the opposite of what it means, so they are not ironic.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 2, part: 1 },
  { question: 'A public health official drafts two openings for a flyer to be posted in a neighborhood laundromat: "Hey, quick tip: wash your hands for twenty seconds" and "Hand hygiene compliance reduces pathogen transmission." Which reason best supports choosing the first opening?', options: ['Its technical vocabulary signals the official\'s expertise', 'Its formal register lends the flyer institutional authority', 'Its abstract wording invites reflection on public health', 'Its colloquial register suits a casual setting and a broad audience'], correctAnswer: 3, explanation: 'A laundromat flyer reaches a general audience in an informal place, and the first opening\'s casual, plain wording fits that situation. The technical and formal features described belong to the second opening, not the first. The first opening is a concrete instruction, not abstract wording.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 1, part: 1 },
  { question: '"The new parking garage, a gleaming monument to our council\'s priorities, will hold four hundred cars, roughly the number of families who lost bus service this year." The diction in this sentence conveys a tone best described as', options: ['bitterly ironic', 'admiring and celebratory', 'neutral and informational', 'nostalgic and wistful'], correctAnswer: 0, explanation: '"Gleaming monument" sounds like praise, but setting the garage beside the families who lost bus service turns the praise into criticism of the council\'s priorities, so the tone is bitter irony. The praise is not sincere admiration. The sentence is not neutral, because the comparison is chosen to sting, and it looks at a present decision rather than back at the past with longing.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 2, part: 1 },
  { question: '"For years I loved the old mill: its red brick, its humming looms, the smell of oil on warm summer evenings. Then the owners sold it. Now it is a parking lot." The shift between the first sentence and the last two is marked primarily by a move from', options: ['abstract terms to sensory description', 'lingering sensory detail to flat, clipped statement', 'objective reporting to emotional exaggeration', 'short declaratives to long, winding periodic sentences'], correctAnswer: 1, explanation: 'The first sentence lingers over sensory details of the mill, and the last two are short and flat, so the abrupt loss lands hard. The movement runs from sensory detail to plainness, the reverse of moving into description. The writer does not exaggerate, and the sentence length shrinks rather than grows.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 1, part: 1 },
  { question: 'An op-ed begins, "The district\'s proposal reflects careful deliberation and a sincere commitment to equity." Two paragraphs later it reads, "In practice, the plan quietly shovels the best teachers toward the wealthiest schools." The change in diction across these sentences primarily serves to', options: ['show that the writer has switched positions on the proposal', 'establish the writer\'s own expertise in school finance', 'expose a gap between the plan\'s stated aims and its results', 'suggest that the district\'s deliberations were kept secret'], correctAnswer: 2, explanation: 'The early, generous diction grants the plan its stated intentions, and the blunt verb "shovels" then shows what the plan actually does, which exposes the distance between the two. The writer has not switched positions; the praise is a concession that sets up the critique. Neither sentence shows financial expertise or says anything about secrecy.', difficulty: 'hard', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 2, part: 1 },
  { question: 'A student is writing a rhetorical analysis of a speech in which the speaker calls a proposed dam "a wall against our children\'s future." Which sentence would best serve as a defensible claim about this choice?', options: ['The speaker uses a metaphor about a wall in the speech’s opening', 'The dam would harm the region’s young people for many decades', 'The metaphor recasts the dam as a barrier to the next generation', 'The speech is persuasive and uses strong, memorable word choice'], correctAnswer: 2, explanation: 'A defensible analytical claim names the choice and says what it does, and here the metaphor turns a construction project into a threat to the next generation. Simply noting that a metaphor appears only identifies it. Saying the dam would harm young people argues about the dam rather than analyzing the speech, and "persuasive" and "strong" are too vague to defend.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 1, part: 1 },
  { question: 'A student\'s draft reads: "The mayor calls the factory closure \'a slow strangling of downtown.\' This is good diction." Which revision of the second sentence best adds commentary?', options: ['This is an example of strong and descriptive diction in the speech.', 'Many other speakers also use this kind of violent word in their speeches.', 'The mayor also uses the word downtown several more times later on.', 'Calling it murder casts those behind it as villains.'], correctAnswer: 3, explanation: 'Commentary explains the effect of a choice, and "strangling" makes the closure sound like a deliberate killing, which turns the people behind it into villains. Calling the diction strong and descriptive just restates "good diction." Comparing it to other speakers and counting later uses of a word both move away from what this choice does.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 2, part: 1 },
  { question: 'Which statement about analyzing diction and syntax on the AP exam is most accurate?', options: ['Each choice should be linked to its effect on the audience', 'Naming many devices earns more credit than explaining a few', 'Long block quotations work better than short quoted words', 'Diction and syntax should be analyzed in separate paragraphs'], correctAnswer: 0, explanation: 'Strong analysis ties every choice it discusses to its effect on the audience and to the writer\'s purpose. Two well-explained examples beat a long list of device labels, short high-impact quotations beat long blocks, and diction and syntax are usually strongest when analyzed together, not in separate paragraphs.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 1, part: 1 },
  { question: '"They told us the factory would bring prosperity. It brought prosperity, to them. To us it brought a fence, a smell, and a sign that said Keep Out." The phrase "to them," set off at the end of the second sentence, primarily serves to', options: ['introduce a list of the benefits the factory gave the town', 'isolate a qualification that reveals who truly benefited', 'signal a pause in which the writer doubts the claim', 'soften the accusation by adding an afterthought'], correctAnswer: 1, explanation: 'Placing "to them" at the end of the sentence limits the promised prosperity to the owners and sets up the contrast with what "us" received. The list that follows names harms, not benefits. The writer is certain, not doubtful, and the phrase sharpens the accusation instead of softening it.', difficulty: 'hard', domain: 'style', topicSlug: 'englang-diction-syntax', formSet: 2, part: 1 },
  // englang-style-reading
  { question: 'A cardiologist writing for a medical journal states, "Patients exhibited reduced left ventricular ejection fraction." Describing the same patients for a newspaper, she writes, "Their hearts were pumping weakly." The newspaper version replaces', options: ['concrete imagery with abstract, conceptual terms about the heart', 'neutral wording with emotionally loaded language about patients', 'colloquial phrasing with a more formal, professional register', 'technical jargon with plain words a general reader can follow'], correctAnswer: 3, explanation: 'The journal sentence uses specialized medical terms, and the newspaper sentence swaps them for plain words that a general reader understands. The newspaper version is more concrete, not more abstract. "Pumping weakly" is plain rather than emotionally charged, and the move runs from formal to plainer language, not the other way around.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-style-reading', formSet: 1, part: 1 },
  { question: 'A school board candidate asks the audience, "If we will not invest in our children now, when exactly do we plan to start?" The question primarily functions to', options: ['request specific information about the budget timeline', 'make listeners face how long the district has delayed', 'admit that the candidate lacks a clear plan of her own', 'introduce statistics on the district\'s past spending'], correctAnswer: 1, explanation: 'This is a rhetorical question: the speaker expects no answer and uses it to make listeners face how long the investment has been put off. She is not actually asking for a timeline. The question puts pressure on others rather than admitting her own weakness, and no statistics follow it.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-reading', formSet: 2, part: 1 },
  { question: '"We have studied the problem, we have funded the studies, and we have studied the studies. What we have not done is fix a single pothole." The repetition of "studied" in the first sentence primarily serves to', options: ['mock the city\'s habit of analysis without action', 'praise officials for researching the issue with great care', 'show that the problem is too complex for quick repair', 'list the steps the city must take before it acts'], correctAnswer: 0, explanation: '"Studied the studies" turns the repetition into an absurdity, and the short second sentence confirms the point: the city analyzes endlessly but never acts. The tone is mocking, not admiring. Nothing suggests the potholes are too complex to fix, and the sentence lists what has already been done, not steps still to come.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-reading', formSet: 1, part: 1 },
  { question: '"Only after the third flood in a decade, after the insurance companies fled and the young families followed them, did the county finally consider a levee." Which statement best analyzes how the sentence\'s structure supports the writer\'s purpose?', options: ['The sentence is periodic, so the main clause appears at the very end of it.', 'The long sentence shows that the writer has a lot of information to share.', 'Holding the decision until the end mirrors how long residents had to wait.', 'The list of disasters proves that levees prevent flood damage in every case.'], correctAnswer: 2, explanation: 'Delaying the main clause makes the reader wait for the county to act, just as residents did, which reinforces the criticism of a slow response. Labeling the sentence periodic is accurate but explains no effect. Saying the writer has a lot of information is vague, and the sentence makes no claim about whether levees always work.', difficulty: 'hard', domain: 'style', topicSlug: 'englang-style-reading', formSet: 2, part: 1 },
  { question: 'An editorial calls a proposed curfew "a cage for teenagers." Compared with calling it "a rule limiting late-night hours for minors," the editorial\'s phrasing most likely', options: ['pushes readers to see the policy as an unfair loss of freedom', 'gives readers a precise sense of the policy\'s exact hours', 'presents the policy in neutral and objective terms', 'makes the policy seem gentle and protective'], correctAnswer: 0, explanation: '"Cage" is loaded diction that presents the curfew as imprisonment, which pushes readers to see it as an unjust loss of freedom. The metaphor gives no information about hours. It is the opposite of neutral, and a cage suggests confinement rather than gentle protection.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-style-reading', formSet: 1, part: 1 },
  { question: 'In a letter urging the state to fund rural clinics, a nurse writes, "I have stitched a farmer\'s hand by the light of my phone because the power had been out for two days." The concrete imagery in this sentence most likely', options: ['shifts the letter\'s focus from rural clinics to power outages', 'establishes the nurse\'s technical expertise in emergency medicine', 'suggests the nurse prefers working without modern equipment', 'makes the clinics\' need vivid and hard to dismiss'], correctAnswer: 3, explanation: 'The specific image of stitching a wound by phone light makes the clinics\' shortage concrete, so readers find the request hard to brush aside. The outage serves the argument about clinics rather than replacing it. The sentence uses no technical language, and it shows a hardship, not a preference.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-reading', formSet: 2, part: 1 },
  { question: 'Passage 1: "Recycling rates have fallen eleven percent since the program\'s funding was cut." Passage 2: "Every week, more bottles that could have been reborn are buried in the landfill outside town." Compared with Passage 1, Passage 2 relies more heavily on', options: ['statistical evidence and a formal register', 'technical vocabulary and precise data', 'figurative language and concrete imagery', 'rhetorical questions and direct address'], correctAnswer: 2, explanation: '"Reborn" treats bottles figuratively, as if they could have a second life, and "buried in the landfill outside town" is a concrete image. The statistic and the precise data belong to Passage 1. Neither passage asks a question or speaks directly to the reader.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-reading', formSet: 1, part: 1 },
  { question: 'Which sentence is periodic?', options: ['The team won the game in the rain on a cold and windy night.', 'In the rain on a cold and windy night the team won the game.', 'The team won the game and then celebrated in the rain all night.', 'The team, soaked and cold, won the game on a windy night.'], correctAnswer: 1, explanation: 'A periodic sentence holds its main clause until the end, and only the sentence that opens with the rain and the night and closes with the team winning does that. Each of the other sentences completes its main clause before the end and then adds details, which makes it a loose sentence.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-style-reading', formSet: 2, part: 1 },
  { question: '"Oh, wonderful. Another meeting about the meeting we had about scheduling meetings." The writer\'s tone is best described as', options: ['warm and enthusiastic', 'exasperated and sarcastic', 'anxious and fearful', 'neutral and detached'], correctAnswer: 1, explanation: '"Oh, wonderful" says the opposite of what the writer means, and the pile-up of meetings exaggerates how pointless they are, which signals sarcasm and frustration. Read literally, "wonderful" might suggest enthusiasm, but the context reverses it. Nothing in the passage expresses fear, and the mockery is not detached.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-style-reading', formSet: 1, part: 1 },
  { question: 'A student council president is drafting a speech for a pep rally. Her draft opens, "It is incumbent upon the student body to manifest its collective enthusiasm." Which revision best fits her audience and purpose?', options: ['The student body should demonstrate its enthusiasm at this event.', 'Research shows that crowd energy improves team performance.', 'Let\'s get loud and show this team we\'ve got its back!', 'Fellow pupils, let us now exhibit our collective school pride!'], correctAnswer: 2, explanation: 'A pep rally calls for energetic, colloquial language that rallies peers, and short, direct words do that. The other revisions keep a stiff, formal register ("demonstrate," "exhibit our collective school pride") or switch to research evidence, so they still sound like a lecture rather than a cheer for classmates.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-reading', formSet: 2, part: 1 },
  { question: '"The first week at the plant was a revelation: polished floors, a cafeteria with real plates, a manager who learned my name. By the second month, I had learned the names of the three men who had been let go to pay for the plates." The shift in tone between the two sentences is best described as a move from', options: ['anxious uncertainty to calm acceptance', 'detached reporting to sentimental longing for the past', 'playful humor to formal seriousness', 'wide-eyed admiration to quiet disillusionment'], correctAnswer: 3, explanation: 'The first sentence admires the new workplace, and the second reveals the human cost of the perks, so the speaker\'s wonder sours into disillusionment. The narrator is not anxious at first, and the second sentence is pointed, not nostalgic. The first sentence is enthusiastic rather than joking, and the second stays plain rather than becoming formal.', difficulty: 'hard', domain: 'style', topicSlug: 'englang-style-reading', formSet: 1, part: 1 },
  { question: '(1) The new playground opened Saturday to cheers. (2) Children swarmed the climbing dome within minutes. (3) Parents snapped photos from the benches. (4) Nobody mentioned that the old one had been closed for six years. In which sentence does the tone shift?', options: ['Sentence 4', 'Sentence 1', 'Sentence 2', 'Sentence 3'], correctAnswer: 0, explanation: 'The first three sentences describe a celebration in upbeat images, and the last sentence\'s "Nobody mentioned" introduces a critical, ironic note about the long neglect. Sentences 2 and 3 extend the cheerful scene that sentence 1 sets up, so the tone holds steady until the closing remark.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-reading', formSet: 2, part: 1 },
  { question: 'A student\'s draft reads: "In her speech, the principal says the new schedule will \'free our students to breathe.\' This shows she uses figurative language." Which revision of the second sentence best explains the effect of the choice?', options: ['Framing the old timetable as suffocating makes change seem urgent and humane.', 'This is a metaphor, a type of figurative language used in many speeches.', 'She also uses figurative language later when describing the lunch period.', 'This sentence is important to her speech and helps her argument a lot.'], correctAnswer: 0, explanation: 'Saying students need to be freed to breathe implies that the old timetable was suffocating them, which makes the change feel urgent and caring. Naming the metaphor only labels the device. Pointing to another figure moves away from this one, and saying the sentence is important does not explain what it does.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-reading', formSet: 1, part: 1 },
  { question: 'A student claims that a columnist\'s diction portrays the city\'s new stadium as wasteful. Which quotation from the column would best support this claim?', options: ['"the stadium opened on schedule last spring"', '"a gilded vanity project on the waterfront"', '"a modern venue with excellent sightlines"', '"built mostly with funds from private donors"'], correctAnswer: 1, explanation: '"Gilded" suggests showy surface spending and "vanity" suggests self-indulgence, so the phrase directly supports the claim that the stadium is wasteful; the location it names is neutral. An on-time opening is neutral. Praise for the sightlines points the other way, and private funding would weaken a claim of public waste.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-reading', formSet: 2, part: 1 },
  { question: 'A multiple-choice question asks how a passage\'s repeated short sentences affect its argument. What kind of answer can a student most safely eliminate?', options: ['One that links the sentences to the writer\'s purpose', 'One that connects the pacing to an effect on readers', 'One that ties sentence length to the overall tone', 'One that names the device but states no clear effect'], correctAnswer: 3, explanation: 'The question asks about effect, so an answer that only identifies a feature, without saying what it does, cannot be correct. Answers that connect the sentences to purpose, to pacing and reader response, or to tone are all the kind of answer that could be right and have to be judged on the passage.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-style-reading', formSet: 1, part: 1 },
  { question: '"We were promised a park. We were promised a library. We were promised, in glossy brochures and at ribbon-cuttings, a neighborhood worth staying in. We received a parking lot." The effect of the final sentence depends chiefly on', options: ['its concrete imagery of the empty paved lot', 'its periodic structure that delays the subject', 'its break from the anaphora that came before it', 'its shift into a more informal, colloquial register'], correctAnswer: 2, explanation: 'Three sentences open with "We were promised," so when the last one switches to "We received," the broken pattern and the bare result deliver the disappointment. The sentence names a parking lot but gives no sensory description of it. Its subject comes first rather than last, and its register matches the sentences before it.', difficulty: 'hard', domain: 'style', topicSlug: 'englang-style-reading', formSet: 2, part: 1 },
  // englang-style-writing
  { question: 'A student\'s argument about school start times includes this sentence: "Starting school later would be good for a lot of people." Which revision most improves the precision of the sentence?', options: ['Starting school later would let sleep-deprived teenagers get the hours of rest that pediatricians recommend.', 'Starting school later would be extremely beneficial for many people in a great many ways.', 'A later start to the school day would be a good and helpful change for most people.', 'Starting school later would surely be, in every respect, an unquestionably good idea.'], correctAnswer: 0, explanation: 'The revision names a specific group (sleep-deprived teenagers), a specific benefit (rest), and an authority behind it, replacing the vague "good" and the phrase "a lot of people" in the original. The other versions only intensify or decorate the vague claim with words like "extremely" and "unquestionably" without making it any more specific.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-style-writing', formSet: 1, part: 1 },
  { question: 'Read the passage: "For three winters, the shelter\'s volunteers have stretched every donation, patched every cot, and turned away no one who knocked after dark. They have done this without heat in the east wing and without a single paid staff member. They are tired." The final sentence primarily serves to', options: ['introduce a counterargument about whether volunteers should be paid', 'emphasize the toll of the work by contrast with the long sentences', 'shift the tone from admiration to criticism of the volunteers\' choices', 'summarize the statistics presented in the first two sentences of the passage'], correctAnswer: 1, explanation: 'After two long, cumulative sentences of effort, the abrupt three-word sentence lands with force and makes the cost of that effort hit the reader. It does not argue about pay, criticize the volunteers, or summarize data; its work is emphasis created by the contrast in sentence length.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-writing', formSet: 2, part: 1 },
  { question: 'A student\'s draft thesis reads: "Cities should ban cars downtown." The student wants to acknowledge a specific competing concern while keeping the claim. Which revision best accomplishes this goal?', options: ['Because downtown traffic is dangerous, cities should ban private cars from their centers immediately.', 'Cities should ban cars downtown, although some people may or may not agree with this idea.', 'Although delivery businesses need street access, cities should close downtown cores to private cars.', 'Cities should ban cars downtown, which would reduce pollution, noise, and the number of crashes.'], correctAnswer: 2, explanation: 'The concession clause names a real competing concern (delivery access) and then reasserts the claim, which adds nuance without abandoning the position. The version about people who may or may not agree concedes nothing specific, and the versions with reasons only support the claim without acknowledging any opposing interest.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-writing', formSet: 1, part: 1 },
  { question: 'A student\'s formal essay on a zoning proposal includes this sentence: "The committee\'s proposal, honestly, is kind of a joke." Which revision of the sentence best fits the essay\'s formal register?', options: ['The committee\'s proposal, honestly, is a total joke and a waste.', 'The committee\'s proposal, to put it bluntly, is super unrealistic.', 'The committee\'s proposal ignores the costs that it would create.', 'The committee\'s proposal is something people won\'t really like.'], correctAnswer: 2, explanation: 'The revision replaces slang with a precise, formal criticism that names what the proposal gets wrong. The other versions either keep casual markers (honestly, total joke, super) or swap the slang for a vague statement about what people will like.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-writing', formSet: 2, part: 1 },
  { question: 'Read the sentence: "Despite two failed referendums, a shrinking tax base, and a decade of deferred repairs, the library board has kept every branch open." What is the main effect of holding the main clause until the end of the sentence?', options: ['It lists the board\'s failures in order to argue that the branches should close.', 'It hides the writer\'s position so that readers must infer the actual claim.', 'It shifts the passage from a formal register into an informal one.', 'It stacks up obstacles so the board\'s achievement lands with emphasis.'], correctAnswer: 3, explanation: 'This is a periodic sentence: the obstacles accumulate before the main clause arrives, so the achievement of keeping every branch open feels earned and emphatic. The obstacles are not an argument for closing branches, the claim is stated outright rather than hidden, and the register stays formal throughout.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-style-writing', formSet: 1, part: 1 },
  { question: 'In a letter to the city council, a resident revises "Many people use the late bus" to "Night-shift nurses and warehouse workers depend on the last bus of the night." What is the most likely effect of this revision on the council?', options: ['It weakens the claim by narrowing it to only two small groups of riders.', 'It makes the riders concrete figures whose needs officials can picture.', 'It adds an emotional appeal that removes the need for any ridership data.', 'It shifts the letter into a casual register that is unsuited to officials.'], correctAnswer: 1, explanation: 'Naming specific stakeholders makes the riders concrete and their need (getting to and from night work) easy to grasp, which is the point of precise diction. The groups are examples that sharpen the claim rather than limit it, the register stays formal, and specificity does not replace evidence.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-writing', formSet: 2, part: 1 },
  { question: 'A student writes: "The new schedule is cheaper, it reduces crowding, and teachers will be less tired." Which revision uses parallel structure to give the three benefits equal weight?', options: ['The new schedule is cheaper, and it reduces crowding, and teachers will feel less tired too.', 'The new schedule, being cheaper, also reduces crowding, leaving the teachers less tired.', 'The new schedule cuts costs, eases crowding, and reduces teacher fatigue.', 'The new schedule is cheaper; crowding is reduced; teachers will be less tired.'], correctAnswer: 2, explanation: 'Each benefit is now a verb followed by its object (cuts costs, eases crowding, reduces fatigue), so the three items share one grammatical form and carry equal weight. The other versions keep mixing forms, either by chaining clauses with "and," subordinating two benefits to the first, or switching to the passive voice in the middle.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-writing', formSet: 1, part: 1 },
  { question: 'A writer wants the last sentence of a paragraph about a nursing shortage to build toward its most serious consequence. Which version best accomplishes this goal?', options: ['The shortage lengthens wait times, strains hospital budgets, and costs patients their lives.', 'The shortage costs patients their lives, lengthens wait times, and strains hospital budgets.', 'The shortage strains hospital budgets, costs patients their lives, and lengthens wait times.', 'The shortage costs patients their lives, strains hospital budgets, and lengthens wait times.'], correctAnswer: 0, explanation: 'Climactic order places the gravest item last, so the series rises from inconvenience to cost to loss of life. Every other arrangement buries the deaths at the start or in the middle and lets the sentence end on a weaker consequence, which drains the emphasis the writer wants.', difficulty: 'hard', domain: 'style', topicSlug: 'englang-style-writing', formSet: 2, part: 1 },
  { question: 'A student is adapting a research paper for a middle-school newsletter. The original sentence reads: "Adolescent circadian rhythms exhibit a phase delay that compromises early-morning cognition." Which revision best suits the new audience?', options: ['Adolescent circadian rhythms show a phase delay that harms thinking early in the morning.', 'Teens\' sleep is totally messed up, so mornings are basically the worst, period.', 'A phase delay in adolescent rhythms compromises cognition during the morning.', 'Teenagers\' body clocks run later, so their brains are still groggy early in the day.'], correctAnswer: 3, explanation: 'The revision translates the technical idea into plain words young readers know (body clocks, groggy) without losing the meaning. The versions that keep "phase delay" and "circadian" stay too technical for the audience, and the slang version is so casual and exaggerated that it loses the information.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-style-writing', formSet: 1, part: 1 },
  { question: 'A student believes the surest way to show a sophisticated style in an AP argument essay is to fill it with impressive vocabulary. Which statement best describes how style actually strengthens an AP essay?', options: ['Style strengthens an essay when it adds advanced words to the argument and topic sentences.', 'Style strengthens an essay when every paragraph includes a rhetorical question for the reader.', 'Style strengthens an essay when it stays vivid and persuasive in serving the argument throughout.', 'Style strengthens an essay when it avoids every first-person pronoun and every contraction.'], correctAnswer: 2, explanation: 'Style earns credit when it is purposeful: consistently vivid, persuasive prose that serves the argument is one recognized route to the sophistication point. Decorative vocabulary, formulaic rhetorical questions, and mechanical rules about pronouns are surface features that do not by themselves make writing more controlled or persuasive.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-writing', formSet: 2, part: 1 },
  { question: 'Read the student paragraph: "The council\'s decision to defund the arts program reflects a short-sighted view of education. Research consistently links arts participation to higher attendance and graduation rates. Basically, cutting it is a dumb move that nobody should be cool with." Which revision of the final sentence best keeps the paragraph\'s register and precision?', options: ['Cutting the program trades a lasting benefit for a small saving.', 'Basically, cutting the program is a dumb move that hurts students.', 'Cutting it is, in my humble opinion, a move nobody should support.', 'In conclusion, the arts program matters and should not be cut at all.'], correctAnswer: 0, explanation: 'The revision keeps the formal, analytical voice of the first two sentences and states a precise consequence that follows from the research. The versions with "basically" and "dumb" or "in my humble opinion" keep the abrupt drop in register, and the "in conclusion" version is formal but vague, restating the position without any precision.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-writing', formSet: 1, part: 1 },
  { question: 'A student revises one sentence across three drafts. Draft 1: "Social media is bad for teens." Draft 2: "Social media is really, really bad for a lot of teens." Draft 3: "Platforms engineered for endless scrolling cut into the sleep that teenagers need." Which statement most accurately describes the revisions?', options: ['The second draft adds needed precision; the third makes the claim more emotional.', 'The second draft adds intensity without precision; the third names a clear mechanism.', 'The second draft narrows the claim; the third broadens it to every kind of website.', 'The second draft adds a concession; the third drops it to seem more confident and sure.'], correctAnswer: 1, explanation: 'Draft 2 only stacks intensifiers (really, really, a lot), which makes the claim louder but no more exact; Draft 3 replaces them with a specific cause and effect. Calling Draft 2 more precise confuses emphasis with precision, and neither draft adds a concession or broadens the claim to every website.', difficulty: 'hard', domain: 'style', topicSlug: 'englang-style-writing', formSet: 2, part: 1 },
  { question: 'In a rhetorical analysis essay, a student quotes an author who calls the town\'s water inspections "safety theater," then writes: "This quote shows that the author is making a really good point about the inspections." Which revision best turns the student\'s sentence into precise commentary?', options: ['This quote, which is very important, shows the author\'s good point about inspections.', 'In other words, the author thinks the town\'s inspections are only safety theater.', 'This quote shows that the author uses strong and powerful diction to make a point.', 'The word theater casts the inspections as a show of safety staged for the public.'], correctAnswer: 3, explanation: 'The revision explains what the metaphor does: it recasts inspections as a performance for an audience rather than real protection. The paraphrase only restates the quotation, and the versions that call the point good or the diction powerful praise the language without explaining its effect.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-style-writing', formSet: 1, part: 1 },
  { question: 'Read the paragraph: "Supporters of the four-day school week point to lower transportation costs. ______ Districts that adopted the schedule saved on buses but spent more on childcare stipends for staff." The writer wants to add a sentence in the blank that qualifies the supporters\' point while keeping the paragraph\'s measured tone. Which choice most effectively accomplishes this goal?', options: ['Those savings are real, and they prove the schedule is a sound financial choice.', 'Yet supporters, predictably, ignore the hidden costs that sink the plan.', 'But who cares about bus savings when families pay the hidden price?', 'The savings are real, though they capture only one line in a much larger overall budget.'], correctAnswer: 3, explanation: 'The sentence grants the supporters\' point and then limits it, which sets up the evidence about childcare costs in an even, measured tone. The version calling the schedule a sound choice does not qualify anything, while the sneering "predictably" version and the rhetorical question both qualify the point but break the measured tone.', difficulty: 'hard', domain: 'style', topicSlug: 'englang-style-writing', formSet: 2, part: 1 },
  { question: 'A sentence that delays its main clause until the end, after a series of modifying phrases or clauses, is called a', options: ['periodic sentence', 'cumulative sentence', 'antithetical sentence', 'compound-complex sentence'], correctAnswer: 0, explanation: 'A periodic sentence withholds its main clause until the end, which builds suspense and emphasis. A cumulative sentence does the reverse, stating the main clause first and adding modifiers after it, while antithesis and compound-complex structure describe balance and clause count rather than delay.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-style-writing', formSet: 1, part: 1 },
  { question: 'An AP writing question shows a draft paragraph and asks which revision of one sentence best maintains the writer\'s tone. What should a student check first?', options: ['whether the revision uses the most advanced vocabulary available', 'whether the revision keeps the attitude of the surrounding lines', 'whether the revision is the longest and most detailed choice', 'whether the revision adds a new piece of evidence or statistic'], correctAnswer: 1, explanation: 'Tone questions are answered in context: the right revision keeps the attitude already established in the surrounding sentences. Advanced vocabulary, length, and new evidence are not what the question asks about and can even break the established tone.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-style-writing', formSet: 2, part: 1 },
  // englang-tone-voice-analysis
  { question: 'Read the passage: "The new parking garage, we are told, will \'revitalize\' downtown. Its first achievement has been to replace a bakery, a bookstore, and a shaded park bench with seven stories of concrete." Which choice best describes the writer\'s tone?', options: ['nostalgic grief over the small shops that have been lost', 'neutral reporting on the progress of a construction project', 'sardonic skepticism toward the benefits promised for the project', 'enthusiastic support for new growth in the downtown area'], correctAnswer: 2, explanation: 'The distancing phrase "we are told," the scare quotes around "revitalize," and the mock praise of the garage\'s "first achievement" signal mocking doubt about the promised benefits. The passage notes what was lost, but its attitude is aimed at the project rather than mourning, and nothing about it is neutral or supportive.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 1, part: 1 },
  { question: 'A columnist is known for a dry, understated, wry style. In one column about the death of a close friend, her attitude is mournful, yet her sentences remain spare and understated. Which statement best describes this column?', options: ['Her voice shifts to fit the somber subject.', 'Her tone and her voice both turn mournful.', 'Her tone overwhelms and replaces her voice.', 'Her tone shifts, but her voice persists.'], correctAnswer: 3, explanation: 'Her attitude toward the subject (tone) becomes mournful, while her recognizable stylistic persona (voice) stays spare and understated. Saying her voice shifts or is overwhelmed confuses the local change in attitude with the stable, whole-text identity that voice describes.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 2, part: 1 },
  { question: 'In a speech to the school board, a principal first describes the students who organized a walkout as "stubborn," then revises the word to "persistent." Compared with the original word, the revision most likely conveys', options: ['respect for the students\' determination', 'frustration with the students\' refusal to compromise', 'a neutral description with no attitude at all', 'ironic mockery of the students\' cause'], correctAnswer: 0, explanation: '"Persistent" carries a positive connotation of admirable determination, while "stubborn" suggests unreasonable refusal. Frustration belongs to the original word, the revision is not neutral because it chooses the favorable connotation, and nothing in the context signals irony.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 1, part: 1 },
  { question: 'Read the opening of a magazine article: "Have you ever wondered where your recycling goes after the truck pulls away? Let\'s follow one bottle together." The opening question creates a tone that is best described as', options: ['accusatory, implying that readers have failed to recycle', 'invitational, drawing readers into an inquiry they share', 'sarcastic, mocking readers who trust the recycling system', 'detached, raising a question it does not intend to answer'], correctAnswer: 1, explanation: 'The question invites curiosity, and "Let\'s follow one bottle together" makes the investigation a shared one. Nothing blames or mocks the reader, and the article promises to answer the question rather than leaving it unanswered.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 2, part: 1 },
  { question: 'Read the passage: "We waited. We called. We wrote letters. Nothing changed." The syntax of the passage most directly contributes to which tone?', options: ['a leisurely, reflective tone', 'a clipped, exasperated tone', 'a playful, mocking tone', 'a formal, ceremonial tone'], correctAnswer: 1, explanation: 'The string of short declaratives sounds blunt and worn out, and the final sentence makes the frustration explicit. Long, flowing sentences would be needed for a leisurely tone, and nothing in the diction is playful or ceremonial.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 1, part: 1 },
  { question: 'A commencement speaker says: "They told us the river could not be cleaned. They told us the factories would never change. They told us to wait. We did not wait." What is the main effect of the repeated sentence opening and the final sentence?', options: ['It conveys weary resignation to the limits others set for the graduates.', 'It creates a humorous rhythm that lightens a serious subject.', 'It shows the speaker\'s uncertainty about who issued the warnings.', 'It builds an insistent defiance that peaks when the speaker rejects the advice.'], correctAnswer: 3, explanation: 'The repeated "They told us" piles up the doubters\' claims, and the short reversal "We did not wait" answers all of them at once, creating defiant momentum. Resignation misreads the ending, which rejects the advice rather than accepting it, and the repetition is insistent rather than humorous or uncertain.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 2, part: 1 },
  { question: 'Read the passage: "Granted, the curfew has reduced late-night vandalism, and its supporters deserve credit for that. But a policy that treats every teenager as a suspect carries costs that no vandalism report records." The opening concession mainly contributes to', options: ['a fair-minded voice for the writer', 'a hidden endorsement of the curfew by the writer', 'a mocking, sarcastic register in the passage', 'a sense of the writer\'s doubt about the claim'], correctAnswer: 0, explanation: 'By crediting the curfew\'s real benefit before criticizing it, the writer appears balanced and reasonable, which makes the criticism more credible. The concession does not endorse the curfew, since the next sentence argues against it, and the credit given is sincere rather than sarcastic or uncertain.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 1, part: 1 },
  { question: 'Passage 1: "Let\'s be honest: nobody reads the terms of service. I certainly don\'t, and I wrote a book about privacy." Passage 2: "Empirical studies indicate that very few users open licensing agreements before consenting to them." Which choice best contrasts the voices of the two passages?', options: ['The first is hostile and accusatory; the second is warm and conversational.', 'The first is formal and analytical; the second is self-mocking and witty.', 'The first is casual and self-mocking; the second is formal and detached.', 'The first is grave and mournful; the second is eager and promotional.'], correctAnswer: 2, explanation: 'The first passage uses casual phrasing and pokes fun at its own author, while the second uses impersonal, technical diction. Swapping the labels between the passages is a careless-reading error, and neither passage is hostile, mournful, or promotional.', difficulty: 'hard', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 2, part: 1 },
  { question: 'A principal writing to parents after a lockdown drill wants to reassure them without dismissing their concerns. Which sentence best fits that purpose?', options: ['There is absolutely nothing to worry about, so please stop calling the office.', 'We know the drill was unsettling, and we want to explain each step we took.', 'Lockdown protocol was executed in full accordance with district guidelines.', 'Honestly, these drills scare everyone, and frankly they scare me the most.'], correctAnswer: 1, explanation: 'The sentence acknowledges the parents\' unease and offers a clear explanation, a calm and respectful tone that reassures without brushing concerns aside. Telling parents there is nothing to worry about dismisses them, the bureaucratic version is cold, and admitting personal fear undercuts reassurance.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 1, part: 1 },
  { question: 'A student is analyzing a speech in which council member Ruiz first lays out the levee\'s failures in measured terms and then condemns the board\'s delays. Which thesis most effectively connects Ruiz\'s tone to her purpose?', options: ['Moving from calm diagnosis to open indignation, Ruiz pressures the board to act before the next storm.', 'Ruiz uses a tone that is very serious and also quite emotional throughout her speech to the board.', 'Ruiz uses ethos, pathos, and logos in her speech to persuade the board to fund the repairs.', 'Ruiz\'s tone is indignant, which shows that she feels very angry about the levee\'s failures.'], correctAnswer: 0, explanation: 'This thesis traces the tone\'s progression and ties it to what Ruiz wants the audience to do. The other theses either use vague tone words, list appeals without a claim about tone, or label one tone and stop at the speaker\'s feelings instead of her purpose.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 2, part: 1 },
  { question: 'Read the passage: "For years I defended the standardized test as the fairest yardstick we had. I tutored for it, praised it, and recommended it to every family I knew. Then I watched a brilliant student freeze for three hours and leave convinced she was stupid." The final sentence marks a shift', options: ['from detached analysis to celebratory enthusiasm', 'from playful humor to bitter sarcasm aimed at families', 'from confident advocacy to troubled doubt', 'from quiet grief to renewed faith in the exam'], correctAnswer: 2, explanation: 'The first two sentences show the speaker\'s earlier confidence in the test, and the final sentence introduces an experience that unsettles that confidence. The opening is personal rather than detached, nothing in it is humorous, and the ending moves away from faith in the exam rather than toward it.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 1, part: 1 },
  { question: 'Read the passage: "The committee met for four hours, roughly three hours longer than its agenda required, and devoted most of them to the color of the new letterhead. Then someone mentioned the eviction notices, and the jokes stopped. Forty families have until Friday." Across the passage, which element remains most consistent?', options: ['the writer\'s amused view of the meeting', 'the writer\'s detached attitude toward the families', 'the writer\'s sarcastic register toward the committee', 'the writer\'s precise and understated voice'], correctAnswer: 3, explanation: 'The attitude shifts from wry amusement to gravity once the evictions come up, but the spare, exact, understated style persists from start to finish. Amusement and sarcasm describe only the opening, and the closing sentence is restrained rather than detached in its concern for the families.', difficulty: 'hard', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 2, part: 1 },
  { question: 'A student\'s analysis paragraph reads: "The author uses a sarcastic tone. Sarcasm is when someone says the opposite of what they mean. This makes the passage sarcastic." What is the main weakness of the paragraph?', options: ['It uses tone vocabulary too precise for the passage.', 'It defines sarcasm but never explains what it accomplishes.', 'It quotes too much of the passage instead of summarizing it.', 'It names sarcasm when it should identify the writer\'s voice.'], correctAnswer: 1, explanation: 'The paragraph labels the tone, defines the term, and then circles back to the label without explaining how the sarcasm advances the author\'s purpose. It quotes nothing at all, so the problem is not over-quoting, and naming a tone is appropriate as long as the commentary explains its effect.', difficulty: 'medium', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 1, part: 1 },
  { question: 'A student writing an argument essay wants to convey restrained disappointment in the school board\'s decision rather than outrage or acceptance. Which sentence best achieves this goal?', options: ['The board\'s decision is understandable, yet it falls short of what our students were promised.', 'The board\'s decision is a betrayal so shameless it should end every member\'s career.', 'The board\'s decision is final, and students will adjust to it as they always have.', 'The board\'s decision? Just another gift to people who never bother to show up.'], correctAnswer: 0, explanation: 'The sentence grants the decision some reason before noting the broken promise, which expresses disappointment in measured language. The "betrayal" sentence is outraged, the sentence about students adjusting accepts the decision, and the rhetorical question turns sarcastic.', difficulty: 'hard', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 2, part: 1 },
  { question: 'An essay about a hospital ward makes readers feel uneasy, yet the writer describes the ward in calm, clinical language that reveals no alarm. That calm, clinical attitude toward the subject is best identified as', options: ['the writer\'s voice', 'the passage\'s mood', 'the writer\'s diction', 'the writer\'s tone'], correctAnswer: 3, explanation: 'Tone is the writer\'s attitude toward the subject, here calm and clinical. Mood is the feeling the reader experiences, which in this case is unease; diction is the word choice that creates the tone, and voice is the broader stylistic persona.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 1, part: 1 },
  { question: 'On a multiple-choice question about the tone of a passage, a student narrows the choices to "critical" and "contemptuous." How should the student decide between them?', options: ['pick the more extreme word, since stronger choices are favored', 'pick whichever word matches the student\'s own view of the topic', 'test each word against the specific diction the writer uses', 'pick the milder word, since answers tend to be moderate'], correctAnswer: 2, explanation: 'Tone claims rest on textual evidence, so the student should check whether the diction shows scorn or only disapproval. Rules of thumb about extreme or mild answers ignore the passage, and the student\'s own opinion has nothing to do with the writer\'s attitude.', difficulty: 'easy', domain: 'style', topicSlug: 'englang-tone-voice-analysis', formSet: 2, part: 1 },

  // ── Domain: rhetorical-devices ──────────────────────
  // englang-ethos-pathos-logos
  { question: 'A city council candidate opens her speech: "I have coached youth soccer on these fields every fall since my own kids were small, and I have patched their fences with my own hands." This opening chiefly seeks to establish the speaker\'s', options: ['emotional bond with the parents in the audience', 'logical case for funding new field repairs', 'credibility as someone personally invested in the fields', 'authority as an elected city official'], correctAnswer: 2, explanation: 'Detailing years of hands-on service tells listeners why they should trust her on this issue, which is ethos built from experience. The opening offers no data or reasoning about repairs, so it is not a logical case, and it does not dwell on anyone\'s feelings. She is a candidate, not yet an official, so she cannot claim official authority.', difficulty: 'easy', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 1, part: 1 },
  { question: 'An anonymous blogger with no credentials writes about tax policy, yet readers come to trust her because she quotes primary sources precisely and summarizes opposing positions fairly. Her credibility is best described as', options: ['ethos built within the text', 'ethos borrowed from her reputation', 'pathos disguised as careful research', 'logos that makes ethos unnecessary'], correctAnswer: 0, explanation: 'With no reputation to draw on, the blogger constructs ethos through accurate, fair-minded writing. Calling it borrowed from reputation ignores that she is anonymous. Careful sourcing is not an emotional appeal, and her trustworthiness is itself ethos, so logos has not replaced it.', difficulty: 'easy', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 2, part: 1 },
  { question: 'Every paragraph of a charity\'s fundraising letter describes a different abandoned animal in graphic detail, but the letter never explains how donations are spent or who runs the shelter. The most likely risk of this approach is that readers will', options: ['find the letter cold and quickly lose interest in it', 'see the writer as arrogant and self-important', 'find the details too technical to follow at all', 'feel manipulated and begin to distrust the letter'], correctAnswer: 3, explanation: 'A letter that leans entirely on emotional scenes without facts invites readers to feel exploited, the classic risk of over-relying on pathos. Coldness is the danger of too much logos, and arrogance is the danger of too much ethos. Graphic animal stories are vivid, not technical.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 1, part: 1 },
  { question: 'A student analyzing a senator\'s speech drafts four sentences about the same passage. Which sentence best connects an appeal to the writer\'s purpose and audience?', options: ['The senator uses pathos in her speech when she describes the flooded farmhouse near the river.', 'By describing a flooded farmhouse, the senator makes listeners fear inaction and back the relief bill.', 'The senator first describes a flooded farmhouse, and then she describes a school that had to close.', 'The image of the flooded farmhouse is an extremely powerful and effective use of emotional appeal in the speech.'], correctAnswer: 1, explanation: 'Strong analysis names the effect on the audience and ties it to the purpose, here passing the relief bill. Merely labeling the appeal as pathos identifies without explaining. Listing what the senator describes is summary, and calling the image powerful is vague praise with no explanation of how it works.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 2, part: 1 },
  { question: 'In an op-ed opposing a highway expansion, a writer states: "The planners promise shorter commutes. Yet when nearby Larkin County widened its beltway, rush-hour travel times grew longer within three years." The reference to Larkin County primarily works by', options: ['stirring anger at planners who misled local drivers', 'offering a precedent that undercuts the planners\' prediction', 'building the writer\'s credibility as an engineer', 'conceding that expansion has a few real benefits'], correctAnswer: 1, explanation: 'The writer cites what happened when a comparable project was built, historical precedent that serves as logos against the planners\' prediction. The sentence never accuses planners of deception, so it is not chiefly an appeal to anger. Nothing establishes the writer as an engineer, and the example cuts against expansion rather than granting it benefits.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 1, part: 1 },
  { question: 'Which sentence from a speech supporting longer library hours relies most directly on logos?', options: ['"Our grandparents built this library with their own hands."', '"As a librarian for two decades, I know what patrons need."', '"Imagine a child with nowhere warm to spend the hours after school."', '"Visits rose by a third once hours were extended."'], correctAnswer: 3, explanation: 'A measured change in library visits is statistical evidence, the core of logos. The grandparents line appeals to pride and the image of a cold child appeals to sympathy, both pathos. The librarian\'s years of service build ethos.', difficulty: 'easy', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 2, part: 1 },
  { question: 'Two speakers support the same school-lunch bill. The first quotes a nutrition study linking free lunches to better attention in class; the second describes a student who fell asleep at his desk from hunger. Compared with the first speaker, the second relies more on', options: ['a single story meant to stir sympathy', 'expert testimony meant to build trust', 'statistical evidence meant to show cause', 'a concession meant to seem fair-minded'], correctAnswer: 0, explanation: 'The hungry student is one vivid anecdote designed to make listeners feel for him, which is pathos. Expert testimony and study data belong to the first speaker\'s approach. Neither speaker grants a point to the other side, so there is no concession.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 1, part: 1 },
  { question: 'A nurse testifying for a hospital hand-washing law says: "As someone who has held the hands of patients dying of infections we could have prevented, I can tell you that this rule saves lives." The phrase "As someone who has held the hands of patients dying" functions chiefly as', options: ['proof of expertise with no emotional pull', 'emotional pull with no claim to expertise', 'experience that also carries emotional weight', 'statistical support framed as a personal story'], correctAnswer: 2, explanation: 'The phrase establishes the nurse\'s firsthand experience, which builds ethos, while the image of dying patients evokes grief, which is pathos. Treating it as purely expertise or purely emotion misses that one detail does both jobs. The phrase contains no data, so it is not statistical support.', difficulty: 'hard', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 2, part: 1 },
  { question: 'A teacher writes to the school board: "I have taught chemistry here for thirty years. In that time, lab budgets have fallen by half while enrollment has doubled. Last spring, forty students shared one balance, waiting in line until the bell rang." Which choice best describes how the three sentences work together?', options: ['Credibility, then a concession, then a demand', 'Emotion, then a statistic, then a credential', 'Credibility, then an anecdote, then data', 'Credibility, then data, then a vivid human scene'], correctAnswer: 3, explanation: 'The letter opens with the teacher\'s experience, an ethos move, then gives budget and enrollment figures, logos, then closes on a concrete image of students waiting, pathos. No sentence concedes a point or makes a demand. The other sequences scramble the actual order of the appeals.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 1, part: 1 },
  { question: 'A report urging a town to fund a teen center offers pages of budget tables and usage projections but never mentions a single teenager or the writer\'s ties to the town. A reader\'s most likely reaction is that the report feels', options: ['manipulative and overly emotional', 'arrogant and full of self-promotion', 'cold and emotionally distant', 'unfair to those who hold other views'], correctAnswer: 2, explanation: 'An argument that relies only on logos risks feeling cold and disconnected, so readers may disengage. Manipulation is the risk of too much pathos, and arrogance is the risk of too much ethos. Nothing in the report mistreats opposing views; the problem is the absence of any human connection.', difficulty: 'easy', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 2, part: 1 },
  { question: 'A commencement speaker spends her first paragraph on graduation rates and enrollment trends, then pauses: "But numbers cannot tell you about Marisol, who studied by the light of a gas-station sign." The shift in the second part primarily serves to', options: ['discredit the statistics she has just presented', 'give a human face to the figures she has cited', 'establish her own authority on education', 'concede that the audience doubts her figures'], correctAnswer: 1, explanation: 'The speaker moves from logos to pathos so that one student\'s story makes the abstract numbers felt. She does not reject her figures; "cannot tell you" means the numbers are incomplete, not wrong. The anecdote is about Marisol, not the speaker\'s expertise, and nothing suggests the audience doubts the data.', difficulty: 'hard', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 1, part: 1 },
  { question: 'A letter to the editor first calls the empty storefronts on Main Street "a betrayal by every official who looked away," then closes by picturing "a street of open doors and lit windows by next summer." The movement in emotional appeal is best described as', options: ['from anger at negligent leaders toward hope', 'from fear of decline toward resignation', 'from sympathy for the shop owners toward outrage', 'from pride in the town toward nostalgia'], correctAnswer: 0, explanation: 'Calling the vacancies a betrayal highlights wrongdoing, which stirs anger, and the closing image of lit windows paints a better future, which offers hope. The letter never accepts decline, so it does not end in resignation. It also does not end in outrage or look backward with nostalgia; it looks forward.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 2, part: 1 },
  { question: 'A student argues that the high school should begin classes later in the morning. She wants to add a sentence that supports the claim with logos. Which choice most effectively does so?', options: ['After a nearby district delayed its first bell, tardiness fell by a quarter.', 'Every tired teenager deserves the chance to sleep in and feel rested at school.', 'As a junior who has been late twice, I know this problem very well myself.', 'Many of the other students I have talked to in my classes agree with this idea.'], correctAnswer: 0, explanation: 'Data from a comparable district offers measurable evidence that the change works, which is logos. The tired-teenager line appeals to sympathy, and the junior\'s experience is a thin bid for ethos. Saying many students agree shows popularity, not evidence that the policy succeeds.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 1, part: 1 },
  { question: 'A draft argument for a town recycling mandate is built almost entirely on dire images of overflowing landfills and choking seabirds. Which revision would best balance the draft\'s appeals?', options: ['Add a more graphic scene of harmed wildlife', 'Add cost data from comparable towns', 'Remove the images and add nothing in their place', 'Add a vivid story about a polluted local beach'], correctAnswer: 1, explanation: 'The draft over-relies on pathos, so adding evidence such as cost data introduces logos and makes the case less vulnerable to seeming manipulative. More graphic scenes or another vivid story only deepen the imbalance. Cutting the images without replacing them weakens the argument rather than balancing it.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 2, part: 1 },
  { question: 'A student writes in a rhetorical analysis essay: "The author uses ethos, pathos, and logos to persuade the audience." This sentence is weak chiefly because it', options: ['names appeals the passage does not contain', 'relies too heavily on quoted textual evidence', 'never explains how a choice affects readers', 'focuses on purpose and neglects the audience'], correctAnswer: 2, explanation: 'The sentence merely labels appeals without quoting the text or explaining how any choice works on the audience, the step that earns credit for commentary. Nothing shows the appeals are absent from the passage. The sentence quotes nothing, and it does not discuss purpose at all.', difficulty: 'easy', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 1, part: 1 },
  { question: 'Which thesis for a rhetorical analysis of a mayor\'s speech after a flood is strongest?', options: ['The mayor uses many different rhetorical strategies and appeals in her speech to the town about the flood.', 'The mayor\'s speech is very persuasive and uses ethos, pathos, and logos well to make her point to the residents of the town.', 'The flood caused great damage to the town, and the mayor wants the residents to rebuild what was lost.', 'The mayor pairs grim damage reports with scenes of neighbors helping neighbors to rally residents behind rebuilding.'], correctAnswer: 3, explanation: 'A strong thesis names specific choices and ties them to the purpose, here rallying residents to rebuild. Saying the mayor uses many strategies or uses all three appeals well makes no defensible claim about how they work. Summarizing the flood and the mayor\'s wish describes the situation without analyzing her choices.', difficulty: 'hard', domain: 'rhetorical-devices', topicSlug: 'englang-ethos-pathos-logos', formSet: 2, part: 1 },
  // englang-logical-fallacies
  { question: '"Councilwoman Reyes wants a curfew for teenagers, but she has never even raised a teenager, so her plan should be ignored." The reasoning in this statement is flawed because it', options: ['distorts the plan to make it easier to reject', 'assumes one event caused a later event', 'attacks her background rather than the plan itself', 'offers only two options when others exist'], correctAnswer: 2, explanation: 'Dismissing the curfew because of the councilwoman\'s personal life targets the person rather than the proposal, which is ad hominem. The statement describes her plan accurately, so it is not a straw man. It makes no causal claim and presents no either-or choice.', difficulty: 'easy', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 1, part: 1 },
  { question: '"Advocates of a four-day school week say students need more rest, but what they are really proposing is that students skip school whenever they like." This statement is best described as a', options: ['straw man', 'ad hominem', 'false dilemma', 'slippery slope'], correctAnswer: 0, explanation: 'The speaker replaces the advocates\' actual position with a distorted, easier-to-attack version, which is a straw man. The statement does not attack the advocates\' character, so it is not ad hominem. It neither limits the choices to two nor predicts a chain of worsening events.', difficulty: 'easy', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 2, part: 1 },
  { question: 'A columnist writes: "Last week two delivery drones crashed in our county. Clearly, drone delivery is too dangerous to allow anywhere." The columnist\'s reasoning is weakest because it', options: ['attacks the companies that build the drones', 'assumes the crashes caused new regulations', 'restates its conclusion as its evidence', 'draws a sweeping rule from a tiny sample'], correctAnswer: 3, explanation: 'Two local crashes cannot support a ban everywhere, so the argument is a hasty generalization. The columnist criticizes the technology, not the companies. No causal link to regulations is claimed, and the conclusion rests on the crashes rather than on a restatement of itself.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 1, part: 1 },
  { question: 'An advertisement claims: "Over ten million households start their day with BrightBrew, so it has to be the healthiest coffee on the market." The ad\'s reasoning confuses', options: ['a product\'s high price with its overall quality', 'how widely a product is used with its merit', 'an expert\'s endorsement with real evidence', 'one happy customer with every customer'], correctAnswer: 1, explanation: 'The ad treats the number of buyers as proof of health benefits, an appeal to popularity. It never mentions price or an expert. It cites millions of households rather than one customer, so it is not generalizing from a single case.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 2, part: 1 },
  { question: 'A campaign flyer reads: "Either you vote for Measure 9, or you are voting to let our parks rot." Which choice best explains why this framing can persuade despite its flaw?', options: ['It cites figures that voters can check for themselves.', 'Its simple split pushes voters to decide quickly and without doubt.', 'It builds trust by granting the other side\'s points.', 'It shows the writer\'s expertise in park planning.'], correctAnswer: 1, explanation: 'Reducing a complex issue to two options is a false dilemma, and such simplified framing persuades by making the decision feel obvious and urgent. The flyer offers no figures, concedes nothing to opponents, and makes no claim to expertise.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 1, part: 1 },
  { question: 'A student spots a slippery slope in an editorial. Identifying this fallacy most accurately', options: ['proves that the claim itself is false', 'shows that the writer intends to deceive', 'means the argument has no rhetorical force', 'exposes a weakness in its logic'], correctAnswer: 3, explanation: 'A fallacy reveals flawed reasoning but does not by itself disprove the claim, which might still be true for other reasons. Spotting a fallacy says nothing certain about the writer\'s intent. A flawed argument can still be rhetorically powerful.', difficulty: 'easy', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 2, part: 1 },
  { question: '"If the district lets students retake one test, they will expect to retake every test, and soon grades will mean nothing at all." This argument is better classified as a slippery slope than as a post hoc fallacy because it', options: ['predicts a chain of future consequences', 'infers a cause from events already past', 'offers only two choices to the district', 'attacks the students instead of the policy'], correctAnswer: 0, explanation: 'A slippery slope claims one step will inevitably lead to an extreme outcome, and this argument forecasts exactly such a chain. Post hoc reasoning looks backward and treats an earlier event as the cause of a later one, which this argument does not do. It neither presents a binary choice nor insults the students.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 1, part: 1 },
  { question: 'A school board member argues: "Students who eat breakfast at school earn higher grades, so serving breakfast to everyone will raise grades." Which observation most directly exposes the flaw in this reasoning?', options: ['Many parents in the district strongly support the school breakfast program.', 'The board member has never taught students in a classroom.', 'Students who choose school breakfast may differ in other important ways.', 'Breakfast programs cost money that could fund other needs.'], correctAnswer: 2, explanation: 'The argument treats a correlation as causation, and families who use school breakfast may differ in routines, attendance, or support that also affect performance. Parental support is an appeal to popularity, not a test of the logic. The board member\'s résumé is irrelevant, and cost bears on the policy\'s wisdom rather than on the causal claim.', difficulty: 'hard', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 2, part: 1 },
  { question: 'At a town meeting, a speaker holds up a photo of a cracked sidewalk outside an elementary school and says: "One child tripped here last month. Our entire city is a death trap for children." Which evaluation best separates the passage\'s rhetorical force from its logical validity?', options: ['It is weak on both counts since it relies on a photo.', 'It is sound logic because the photo proves its point.', 'It is emotionally flat but reasons with care from data.', 'It moves listeners but generalizes from a single incident.'], correctAnswer: 3, explanation: 'The image of an endangered child has real emotional power, yet one fall cannot support a claim about the entire city, a hasty generalization. A photo does not make the argument weak by itself, nor does it prove a citywide claim. The passage is emotionally charged and offers no data, so it is not flat or carefully reasoned.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 1, part: 1 },
  { question: 'In a debate, a candidate answers her rival\'s housing data by saying, "This from a man who has been sued by his own tenants." For undecided listeners who want to weigh evidence, the remark most likely', options: ['strengthens her case by refuting his data', 'builds her image as a fair-minded rival', 'weakens her appeal to reason', 'adds logical support through precedent'], correctAnswer: 2, explanation: 'The remark is ad hominem: it shifts attention from the housing data to the rival\'s personal history, which may energize supporters but undermines rational persuasion. It never addresses the data, so it refutes nothing. A personal jab makes her look less fair-minded, and a lawsuit is not a precedent bearing on his numbers.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 2, part: 1 },
  { question: 'Which statement commits the post hoc fallacy rather than offering a supported causal claim?', options: ['"When the bridge closed for repairs, downtown traffic rose; city sensors traced the added cars to the detour."', '"After the new mascot debuted, our team won every game that followed, so the mascot turned the season around."', '"Ticket sales fell after prices doubled, and surveys of lapsed fans named the price as their main reason."', '"Asthma visits dropped after the factory closed, tracking a measured fall in airborne particulates nearby."'], correctAnswer: 1, explanation: 'The mascot claim rests only on the order of events, assuming that what came first must be the cause. The other statements also involve sequences, but each adds independent evidence, such as sensor data, survey responses, or air measurements, that links cause and effect. Sequence plus supporting evidence is reasoning; sequence alone is post hoc.', difficulty: 'hard', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 1, part: 1 },
  { question: 'An op-ed warns: "If the town lets one food truck park downtown, restaurants will close, Main Street will empty, and we will be left with a ghost town." The central weakness in this warning is that it', options: ['treats each step as inevitable with no support', 'relies on statistics that are out of date', 'attacks food-truck owners instead of the policy', 'gives readers only two options to choose from'], correctAnswer: 0, explanation: 'This is a slippery slope: the writer asserts a chain of escalating consequences without evidence that any step will actually follow. The op-ed cites no statistics at all. It does not insult the vendors, and it predicts a sequence rather than framing an either-or choice.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 2, part: 1 },
  { question: 'A student\'s argument essay includes this sentence: "Anyone who opposes later school start times simply does not care about teenagers\' health." Which revision best removes the fallacy while keeping the student\'s position?', options: ['Some opponents worry about bus costs, but staggered routes can offset those costs for the district.', 'Opponents of later start times are wrong, and their arguments do not deserve attention.', 'Everyone who cares about teenagers must support later start times right away.', 'Opponents of later start times are selfish people who ignore the research.'], correctAnswer: 0, explanation: 'The original sentence attacks opponents\' motives instead of engaging their actual concerns. The revision represents a real objection accurately and answers it, which keeps the position while repairing the reasoning. The other revisions dismiss opponents, recast the issue as a loyalty test, or insult them.', difficulty: 'medium', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 1, part: 1 },
  { question: 'Which strategy best helps a writer avoid hasty generalization in her own argument?', options: ['Open with a vivid personal story', 'Rely on representative evidence', 'Repeat the main claim in the conclusion', 'Cite the most dramatic case she can find'], correctAnswer: 1, explanation: 'A hasty generalization draws a broad conclusion from too little or unusual evidence, so using representative evidence is the direct remedy. A personal story or the most dramatic case is exactly the kind of thin or atypical support that produces the fallacy. Repeating the claim adds no support at all.', difficulty: 'easy', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 2, part: 1 },
  { question: 'Which sentence offers the strongest analysis of a fallacy in a passage about a bike-lane proposal?', options: ['The author uses a straw man fallacy in the second paragraph of the passage.', 'The author\'s logic here is bad, and the argument is unfair to the other side.', 'Recasting the bike-lane plan as a car ban lets the writer dodge the plan\'s actual merits.', 'The passage includes several different fallacies, and they all weaken the argument greatly.'], correctAnswer: 2, explanation: 'Strong analysis names the specific distortion and explains its consequence for the argument. Merely naming the straw man and its location identifies without explaining. Calling the logic bad or noting several fallacies is vague and shows no understanding of how the flaw works.', difficulty: 'easy', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 1, part: 1 },
  { question: 'A student labels this sentence a slippery slope: "If the reservoir keeps dropping at its current rate, the city will need to ration water by August, according to the utility\'s own projections." The best evaluation of the label is that it', options: ['is accurate since the sentence predicts a dire outcome', 'is inaccurate; the sentence is really post hoc', 'is accurate since any dire forecast is a fallacy', 'mistakes a well-supported warning for a fallacy'], correctAnswer: 3, explanation: 'A slippery slope asserts an extreme chain without support, but this warning rests on a measured trend and the utility\'s projections. The student has over-labeled a reasonable forecast. Predicting a bad outcome is not itself a fallacy, and the sentence makes no claim that a past event caused a later one.', difficulty: 'hard', domain: 'rhetorical-devices', topicSlug: 'englang-logical-fallacies', formSet: 2, part: 1 },

  // ── Domain: synthesis-argument ──────────────────────
  // englang-synthesis
  { question: 'A student drafts this body paragraph: "Source A reports that students who tend a school garden eat more vegetables. Source C describes a garden program at one Ohio middle school. Source E notes that gardens cost money to maintain." What is the most significant weakness of this paragraph as synthesis?', options: ['It draws on too few sources to meet the requirements of the synthesis task', 'It relays what each source says without using them to advance a claim of the writer\'s own', 'It refers to the sources by letter rather than by author and title', 'It includes a source about costs that undercuts the writer\'s position'], correctAnswer: 1, explanation: 'The paragraph is a source parade: it relays three findings in turn but never states or develops a position, so the sources are not serving an argument. Three sources meets the minimum, and citing sources by letter is standard practice on the exam. The cost detail cannot undercut a position, since the paragraph never takes one.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 1, part: 1 },
  { question: 'A student writes: "Source B shows that later school start times improve attendance, but Source F\'s data suggest the gain appears only in districts with reliable bus service." The student\'s use of Source F is best described as', options: ['Corroborating Source B\'s finding', 'Summarizing Source B\'s finding', 'Conceding to Source B\'s finding', 'Qualifying Source B\'s finding'], correctAnswer: 3, explanation: 'Source F does not overturn Source B; it adds a condition, reliable buses, under which the attendance gain holds, and that is what qualifying means. Corroborating would mean Source F simply confirms Source B, and summarizing would report Source F without relating it to Source B. Conceding means granting a point to an opposing view, but here the student is narrowing Source B\'s claim, not yielding to it.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 2, part: 1 },
  { question: 'A student argues that the city should ban single-use plastic bags. The student wants to acknowledge Source D, which argues that such a ban burdens low-income shoppers, without abandoning that position. Which sentence most effectively accomplishes this goal?', options: ['Although Source D rightly notes the cost to low-income shoppers, offering free reusable bags would ease that burden.', 'Source D argues that a ban burdens low-income shoppers, which shows that the issue has two sides.', 'Because Source D notes the burden on low-income shoppers, the city should wait to act until reusable bag prices fall.', 'Source D\'s concern about low-income shoppers is beside the point in a debate about pollution.'], correctAnswer: 0, explanation: 'The concession sentence grants Source D\'s point and then answers it with a remedy, so the writer\'s position survives. Labeling the issue two-sided merely summarizes the source, and delaying the ban gives up the thesis. Calling the concern beside the point dismisses the source rather than acknowledging it.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 1, part: 1 },
  { question: 'A student quotes Source C: "Teens who sleep fewer than seven hours a night are involved in twice as many car crashes." Which sentence of commentary best explains how this evidence supports the claim that high schools should begin classes later in the morning?', options: ['This statistic is alarming, and it proves that getting enough sleep matters a great deal for every single teenager in the whole country.', 'Source C comes from a respected highway safety group, so readers can trust that its findings about teens are accurate.', 'If an early first bell is what cuts teens\' sleep short, then pushing it back could reduce a danger that follows them onto the road.', 'In other words, teens who do not get enough sleep at night end up in more car crashes than their rested peers do.'], correctAnswer: 2, explanation: 'The strongest commentary draws the causal link the claim depends on: early start times shorten sleep, and short sleep raises crash risk, so later starts address the danger. Calling the statistic alarming and restating it in other words add no reasoning. Vouching for the source\'s credibility does not explain how the evidence connects to start times.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 2, part: 1 },
  { question: 'Before reading the sources for a synthesis prompt, what should a student do first to set up an effective essay?', options: ['Skim each source and summarize its main idea in the margin', 'Draft a thesis that would fit any answer to the prompt’s question', 'Read the prompt closely to pin down what position the task requires', 'Pick out the three shortest sources so quoting goes quickly'], correctAnswer: 2, explanation: 'The first step in the synthesis process is defining the task, because the prompt determines what position the essay must take and which source evidence will matter. Summarizing every source first invites a source-by-source essay, and a thesis built to fit any answer is not defensible. Choosing sources by length ignores their relevance.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 1, part: 1 },
  { question: 'A student writes: "Source E shows that towns that added protected bike lanes saw fewer traffic deaths the following year, which proves that bike lanes by themselves saved those lives." Which choice best identifies the flaw in the student\'s reasoning?', options: ['It treats a correlation as proof of cause', 'It misreports the figures provided in Source E', 'It relies on a source with an obvious agenda', 'It uses a source too dated to be relevant now'], correctAnswer: 0, explanation: 'The source reports that fewer deaths followed the new lanes, but the student leaps to the claim that the lanes alone caused the drop, ignoring other factors that could explain it. Nothing in the sentence suggests the figures are misreported. The stem also gives no sign that the source is biased or out of date.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 2, part: 1 },
  { question: 'Source D is a case study of one rural district that moved to a four-day school week and saw teacher retention improve. A student arguing that every district in the nation should adopt four-day weeks cites Source D as proof. What is the most serious problem with this use of the source?', options: ['Case studies are never accepted as legitimate evidence in an AP synthesis essay', 'Teacher retention is unrelated to the question of how school districts choose to set their calendars', 'The student should have quoted the district\'s own statistics directly', 'One district\'s experience cannot by itself show what would happen across the country'], correctAnswer: 3, explanation: 'A case study illustrates what happened in one setting; using a single rural district to prove a national policy overgeneralizes from too narrow a base. Case studies are legitimate evidence when used as illustrations, and retention clearly bears on a schedule change. Quoting the statistics directly would not fix the overreach.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 1, part: 1 },
  { question: 'A student outlines a synthesis essay this way: body paragraph one covers Source A, body paragraph two covers Source B, and body paragraph three covers Source C. Which revision would most improve the essay\'s organization?', options: ['Add a fourth body paragraph devoted entirely to Source D to show the breadth of the student\'s reading', 'Build each body paragraph around a reason for the thesis and draw on the sources that support it', 'Arrange the paragraphs so the sources appear in order of publication date', 'Combine the three body paragraphs into a single paragraph that summarizes every source'], correctAnswer: 1, explanation: 'The outline is organized source by source, which produces a source parade; claim-driven paragraphs built around reasons let the writer combine sources within each paragraph. Adding another single-source paragraph or reordering by date keeps the same flawed structure. Merging everything into one summary removes the argument entirely.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 2, part: 1 },
  { question: 'Source A states, "Households enrolled in community solar programs cut their electric bills by an average of 10 percent." Source C states, "Savings from community solar shrink sharply in regions that receive little sunlight." Which sentence most effectively synthesizes the two sources?', options: ['Source A finds that community solar lowers bills, and Source C finds that savings are smaller in some regions.', 'Source C disproves Source A, so community solar does not actually save households any money at all.', 'Both sources agree that community solar is a dependable way for households to save money.', 'Community solar can lower household bills, but Source C suggests that the savings Source A reports depend heavily on how sunny a region is.'], correctAnswer: 3, explanation: 'The strongest sentence relates the sources, using Source C to qualify Source A by identifying the condition, sunlight, on which the savings depend. Setting the two findings side by side with a simple "and" is summary, not synthesis. Source C limits Source A rather than disproving it, and the sources do not agree that solar savings are dependable everywhere.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 1, part: 1 },
  { question: 'A student is writing a synthesis essay defending the claim that public libraries should shift most of their budgets from print books to digital lending. Which source would most directly complicate that claim?', options: ['A report that print circulation has fallen each year since 2015', 'A survey finding that many patrons lack home internet', 'An audit showing digital loans cost less per use than print loans', 'A librarian\'s essay praising e-books for homebound readers'], correctAnswer: 1, explanation: 'If many patrons cannot get online at home, moving budgets to digital lending would cut off people the library serves, and that complicates the claim. Cheaper digital loans and praise for e-books both support the shift. The falling print numbers sound like bad news, but they actually strengthen the case for going digital.', difficulty: 'hard', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 2, part: 1 },
  { question: 'Source B, published in 2009, reports that few teenagers own smartphones; Source E, published in 2024, reports that nearly all of them do. A student cites only Source B to argue that a school phone ban would affect very few students. What is the main problem with this choice?', options: ['It cites a statistic where an expert\'s opinion would be stronger', 'It uses too few sources to support a claim about school policy', 'It relies on outdated data that the more recent source contradicts', 'It refers to the source by letter instead of by its author\'s full name'], correctAnswer: 2, explanation: 'Smartphone ownership changed dramatically between 2009 and 2024, so building a current argument on the older figure misrepresents the situation the newer source documents. Statistics are often strong evidence, and the problem is the source\'s age rather than the number of sources. Letter citations are acceptable on the exam.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 1, part: 1 },
  { question: 'Source D, a table, shows youth visits to a county\'s libraries falling every year from 2015 through 2019 and then rising every year from 2020 through 2024. Which claim most accurately reflects Source D?', options: ['Youth visits declined for five years and then reversed into steady growth', 'Youth visits declined steadily throughout the entire ten-year period shown in the table', 'Youth visits stayed roughly level across the ten years the table covers', 'Youth visits rose sharply at first and then fell for the last five years'], correctAnswer: 0, explanation: 'The table shows two trends, a five-year decline followed by five years of growth, so an accurate claim must capture the reversal. Describing the whole decade as a steady decline or as flat ignores the second half. The rise-then-fall pattern reverses the actual order.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 2, part: 1 },
  { question: 'Source F, a bar graph, shows that 62 percent of surveyed teachers support a ban on phones during class, compared with 31 percent of surveyed students. Which sentence uses Source F most accurately?', options: ['Source F indicates that teachers back a classroom phone ban about twice as often as students do', 'Source F proves that most students in the country oppose any limit on phones in school', 'Source F shows that teachers and students largely agree about banning phones in class', 'Source F shows that nearly a third of teachers actively oppose banning phones in class'], correctAnswer: 0, explanation: 'Sixty-two percent is roughly double thirty-one percent, so the accurate sentence describes the gap without stretching it. The graph covers only surveyed students and says nothing about opposition to any limit nationwide, and the two groups clearly disagree. The teachers who did not express support may be undecided rather than opposed.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 1, part: 1 },
  { question: 'Source B\'s data on a city\'s fare-free bus pilot show that bus ridership rose 18 percent while car trips into downtown fell 2 percent. A student\'s draft claims, "Free fares will get people out of their cars." Which revision of the claim best fits the evidence?', options: ['Free fares will sharply reduce car traffic in the downtown area', 'Free fares had no measurable effect on how residents chose to travel', 'Free fares drew new passengers but did little to curb driving', 'Free fares pulled drivers into downtown and increased car trips'], correctAnswer: 2, explanation: 'Ridership clearly rose, but a 2 percent drop in car trips is modest, so the accurate revision credits the gain in passengers while limiting the claim about driving. Predicting a sharp reduction overstates the data, and saying there was no effect ignores the ridership jump. Claiming car trips increased reverses what the source reports.', difficulty: 'hard', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 2, part: 1 },
  { question: 'A synthesis prompt asks whether cities should ban gas-powered leaf blowers. Which thesis would most clearly earn the thesis point?', options: ['Gas-powered leaf blowers are an issue that many cities and towns have debated at length in recent years.', 'Cities should phase out gas leaf blowers, since their noise and fumes harm the workers who run them.', 'This essay will examine the arguments on both sides of the leaf blower debate.', 'Leaf blowers are loud, and some sources say they pollute, while others disagree.'], correctAnswer: 1, explanation: 'The thesis point requires a defensible position that responds to the prompt, and only the phase-out sentence takes one and signals a line of reasoning. Noting that cities have debated the issue and announcing an examination of both sides avoid committing to a position. Listing what different sources say is likewise a summary, not a claim.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 1, part: 1 },
  { question: 'A student\'s working thesis reads, "Schools should ban phones." Which revision would best demonstrate the complexity rewarded by the sophistication point?', options: ['Schools must ban phones at once, as Sources A, B, C, D, and F all confirm with overwhelming evidence.', 'Like a siren luring sailors onto jagged rocks, the glowing smartphone draws young students away from real learning and simply must be banned outright.', 'Should schools ban phones? It is a complex question with many sides, and each reader must decide for themselves.', 'Schools should restrict phones during instruction, yet the parent safety concerns raised in Source E argue against an outright ban.'], correctAnswer: 3, explanation: 'Sophistication rewards nuance, such as qualifying a claim in light of a credible counterargument, and the restrict-rather-than-ban revision does exactly that. Piling up source letters shows quantity rather than complexity, and vivid figurative language without nuanced reasoning does not earn the point. The rhetorical question abandons a defensible position altogether.', difficulty: 'hard', domain: 'synthesis-argument', topicSlug: 'englang-synthesis', formSet: 2, part: 1 },
  // englang-synthesis-essay
  { question: 'A student\'s introduction argues that the town should build a public skatepark. The body paragraphs gradually shift to arguing that all of the town\'s parks are underfunded, and the conclusion calls for hiring more park rangers. What is the main problem with this essay?', options: ['It does not cite enough sources to satisfy the synthesis task', 'Its conclusion restates the thesis too closely to add anything new', 'Its argument drifts away from the position the thesis committed to at the start', 'It takes a position that is too narrow to argue with sources'], correctAnswer: 2, explanation: 'This is claim drift: the essay starts with a skatepark, wanders to park funding in general, and ends on rangers, so no single defensible claim is developed throughout. Nothing indicates a shortage of sources, and the conclusion introduces a new claim rather than repeating the thesis. A focused local proposal is easy to support with sources.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 1, part: 1 },
  { question: 'An essay argues that the state should require financial literacy courses for high school graduation. Which concluding sentence best reasserts the stakes of the argument?', options: ['Students who leave school unable to manage debt will pay for that gap for decades.', 'In conclusion, the state should require financial literacy courses for high school graduation.', 'Sources A, C, and E all discussed financial literacy, and each one made several important points.', 'Some argue the courses would crowd out electives, but schools could fit them into existing classes.'], correctAnswer: 0, explanation: 'A strong conclusion projects implications, showing why the argument matters beyond the essay, and the sentence about years of debt does that. Repeating the thesis word for word adds nothing, and listing sources is summary. Raising and answering a new objection belongs in the body; in the final sentence it shifts focus to a side issue instead of the stakes.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 2, part: 1 },
  { question: 'Consider this draft paragraph: (1) Cities should limit new parking garages downtown. (2) Source A reports that a 40 percent cut in downtown parking in one city coincided with a sharp rise in transit use. (3) Source D adds that nearby businesses saw no drop in sales. (4) Less parking, then, need not mean fewer customers. The writer wants to add this sentence: "That shift suggests many drivers simply switched to buses and trains once parking grew scarce." Where should it be placed?', options: ['Directly after sentence 1', 'Directly after sentence 2', 'Directly after sentence 3', 'Directly after sentence 4'], correctAnswer: 1, explanation: 'The new sentence comments on the rise in transit use, so it belongs right after the Source A evidence it explains, following the claim, evidence, commentary pattern. Placed after the sales evidence, the phrase "That shift" would point to the wrong finding. Placing it before any evidence or after the closing link would separate the commentary from the data it interprets.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 1, part: 1 },
  { question: 'After quoting Source B, "Cities that planted street trees recorded summer temperatures up to 9 degrees cooler on shaded blocks," a student argues that the city should fund a tree-planting program. Which sentence would work best as commentary?', options: ['In other words, shaded blocks with street trees were up to 9 degrees cooler than the rest of the city\'s streets.', 'Source B was published by a respected urban forestry institute, so its data can be trusted.', 'Trees are beautiful, and everyone enjoys a shady, green street on a hot summer afternoon.', 'Shaded blocks mean fewer heat emergencies, so funding trees protects residents\' health, not just looks.'], correctAnswer: 3, explanation: 'Effective commentary explains why the evidence matters for the claim, here by tying cooler blocks to fewer heat emergencies and thus to residents\' health. Restating the statistic is summary, and vouching for the publisher addresses credibility rather than reasoning. Praising shady streets is vague and unconnected to the policy.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 2, part: 1 },
  { question: 'On a practice synthesis essay, a student spends 25 of the 40 writing minutes rereading sources and finishes only an introduction and one body paragraph. Which change to the student\'s process would most improve the result?', options: ['Use about ten minutes to group sources by idea and sketch a thesis', 'Write the full essay first and add source citations in the final minutes', 'Read every source twice more slowly to avoid any misreading of claims', 'Write a body paragraph for each source as soon as it has been read'], correctAnswer: 0, explanation: 'The recommended workflow spends only about the first ten minutes reading, grouping sources by idea, and planning a thesis, leaving most of the time for writing. Drafting first and tacking citations on at the end produces an argument that is not built from the sources, which is what synthesis requires. Rereading more slowly worsens the time problem, and drafting a paragraph per source produces a source-by-source summary.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 1, part: 1 },
  { question: 'Consider this draft: (1) Cities should replace grass medians with native plants. (2) Source B reports that native plantings need 60 percent less water than turf. (3) This shows that native plants use less water than grass. Which choice best describes the weakness of sentence 3?', options: ['It draws a conclusion broader than the data in Source B allow', 'It contradicts the position taken in the opening sentence', 'It cites a statistic without naming who produced the data', 'It restates the evidence instead of analyzing it'], correctAnswer: 3, explanation: 'Sentence 3 merely repeats Source B\'s finding in different words, so it adds no commentary explaining why water savings justify replacing medians, such as drought costs or maintenance budgets. Its claim matches the data rather than overreaching, and it agrees with the opening sentence. It also does not introduce a new statistic.', difficulty: 'hard', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 2, part: 1 },
  { question: 'Source C, a city audit, finds that a downtown bike-share program covers its costs. Source E, a news report, finds that the same program has almost no stations in low-income neighborhoods. A student argues that the city should expand bike share. Which sentence most effectively uses the two sources together?', options: ['Source C says the program covers its own operating costs, while Source E says it has few stations in low-income neighborhoods.', 'Since Source E finds no stations in poor neighborhoods, the audit in Source C must be unreliable and should be ignored.', 'Because Source C shows the program pays for itself, the gaps Source E documents tell the city where to add stations first.', 'Source C and Source E agree that the bike-share program is a success that requires no changes.'], correctAnswer: 2, explanation: 'The strongest sentence combines the sources into one argumentative move: the audit shows the program is affordable, and the news report identifies where growth is most needed. Placing the findings side by side is summary, and the two sources address different questions, so neither discredits the other. Source E\'s finding shows the program does need changes.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 1, part: 1 },
  { question: 'Source D describes one hospital where a four-day workweek for nurses reduced staff turnover. How should a student arguing that hospitals should pilot shorter workweeks most effectively use this source?', options: ['As proof that every hospital would see exactly the same result', 'As a concrete case that illustrates the benefit such a program might produce', 'As the sole support for the essay\'s thesis, since it is so specific and vivid', 'As background to summarize before the essay\'s argument begins'], correctAnswer: 1, explanation: 'A case study is most useful as an illustration of what a policy can achieve, which suits an argument for a pilot. Treating one hospital as proof for all hospitals overgeneralizes, and resting the thesis on a single source is thin support. Summarizing it as background wastes its value as evidence.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 2, part: 1 },
  { question: 'A student\'s thesis argues that the school district should replace letter grades in ninth grade with narrative feedback. A body paragraph presents Source A\'s finding that students who receive written feedback revise their work more often. Which sentence most effectively ends the paragraph by linking it back to the thesis?', options: ['Overall, Source A is one of the most convincing sources in this set because its study is recent.', 'Since comments push students to keep revising, they serve ninth graders better than one grade.', 'Many ninth graders also find letter grades stressful, which is a separate issue worth exploring.', 'Thus, written feedback leads students to revise their work more often, just as Source A found.'], correctAnswer: 1, explanation: 'The best closing sentence connects the evidence about revision back to the thesis by explaining why feedback that prompts improvement would serve ninth graders better than grades. Praising the source\'s recency evaluates the source instead of advancing the argument, and raising stress introduces a separate issue. Restating Source A\'s finding repeats evidence without linking it to the claim.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 1, part: 1 },
  { question: 'An essay argues that the state should raise the minimum driving age to 18. Source F, a rural sheriff\'s statement, notes that many rural teens drive to jobs and farms where no public transit exists. Which response to Source F would most strengthen the essay?', options: ['Leave Source F out of the essay since it undercuts the argument', 'Quote Source F at length to show that the essay is fair-minded', 'Grant the concern and propose an exemption for work travel', 'Dismiss Source F on the grounds that a sheriff is not a traffic expert'], correctAnswer: 2, explanation: 'Ignoring the strongest opposing source is a common pitfall; conceding its valid point and qualifying the proposal with a work exemption answers the concern while keeping the thesis. Leaving the source out leaves the objection standing, and quoting it at length without answering it gives it more force. Attacking the sheriff\'s expertise dodges a factual point about transit.', difficulty: 'hard', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 2, part: 1 },
  { question: 'A student\'s introduction argues that the town should keep its weekly farmers market downtown, but the conclusion argues that the market should move to the fairgrounds. Which question from a final revision checklist would have caught this problem?', options: ['Are at least three sources used accurately and cited?', 'Is every piece of source evidence followed by commentary?', 'Is a counterargument from the sources addressed and answered?', 'Does the essay still defend the position its thesis takes?'], correctAnswer: 3, explanation: 'The introduction and conclusion take opposite positions, which is claim drift, and only the check on whether the essay still defends its thesis targets that. The checks on source count, commentary, and counterargument are useful but would not flag a reversed position.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 1, part: 1 },
  { question: 'Source A, a 1998 study, found that most adults learned about local news from a daily newspaper. Source F, a 2023 survey, found that most adults now learn about local news from social media. A student argues that towns should fund local journalism. Which sentence most effectively uses both sources?', options: ['Sources A and F trace a move from daily papers to social media, suggesting local news has lost the steady audience it once had.', 'Source A shows that most adults read a daily newspaper, so newspapers remain the main source of local news.', 'Source A found that adults mostly read newspapers back in 1998, and Source F found that adults mostly used social media in 2023.', 'Source F shows that social media has replaced newspapers, so towns no longer have any need to fund journalism at all.'], correctAnswer: 0, explanation: 'Using both sources together reveals a change over time, and the strongest sentence draws an inference from that change that supports funding local journalism. Relying on the 1998 figure ignores the newer data, and listing the two findings side by side is summary. Concluding that funding is unnecessary contradicts the student\'s own claim.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 2, part: 1 },
  { question: 'Source C is a line graph showing that a state\'s average household water use fell from 140 gallons per day in 2015 to 105 gallons per day in 2023, the period after a tiered water pricing policy took effect. Which sentence integrates this source most accurately into an argument for tiered pricing?', options: ['Tiered pricing cut every household’s water use by exactly 35 gallons a day (Source C).', 'Source C proves that tiered pricing was the only reason the state’s water use declined.', 'Water use in the state rose steadily after tiered pricing began, as Source C shows.', 'Use per home fell about a quarter after tiered pricing began (Source C), a promising sign.'], correctAnswer: 3, explanation: 'The graph reports a state average falling from 140 to 105 gallons, a drop of one quarter, and the accurate sentence reports that change while drawing only a modest conclusion. An average cannot show that every household cut exactly 35 gallons, and the data cannot rule out other causes of the decline. The graph shows use falling, not rising.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 1, part: 1 },
  { question: 'Source B, a survey of 400 remote workers at one software company, found that 70 percent reported higher productivity at home. A student writes: "Source B proves that remote work makes all employees more productive." What is the most serious problem with this use of Source B?', options: ['It cites a percentage instead of the number of workers surveyed', 'It overgeneralizes from a narrow sample of self-assessments', 'It names the source by letter instead of by its author or title', 'It uses a statistic where a quotation from a worker would be stronger'], correctAnswer: 1, explanation: 'The survey covered one company\'s workers and measured how productive they felt, yet the student stretches it to all employees as if it were proof. Citing a percentage is accurate reporting, and letter attribution is acceptable on the exam. A statistic is not weaker evidence than a single worker\'s quotation.', difficulty: 'hard', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 2, part: 1 },
  { question: 'A synthesis essay has a defensible thesis and cites four sources accurately, but each quotation is followed only by a paraphrase of what it says. Which rubric row most limits this essay\'s score?', options: ['The row for evidence and commentary', 'The row for the thesis statement', 'The row for sophistication of thought', 'The row for grammar and mechanics'], correctAnswer: 0, explanation: 'Evidence and commentary is worth up to 4 of the 6 points, and paraphrasing each quotation is summary rather than commentary that explains how the evidence supports the thesis. The thesis is already defensible, and although weak commentary also makes the sophistication point unlikely, that row is worth only 1 point. The rubric has no separate row for grammar.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 1, part: 1 },
  { question: 'A synthesis essay states a defensible thesis, uses three sources accurately with thorough commentary, and earns the top score in the evidence and commentary row, but it never qualifies its claim or engages any complexity. What is the highest total score this essay can earn?', options: ['4 out of 6 points', '6 out of 6 points', '5 out of 6 points', '3 out of 6 points'], correctAnswer: 2, explanation: 'The thesis row awards 1 point and the evidence and commentary row awards up to 4, so this essay can reach 5. The sixth point, sophistication, requires nuance or complexity such as qualifying the claim, which the essay never shows. Lower totals would undercount the rows it does earn.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-synthesis-essay', formSet: 2, part: 1 },
  // englang-developing-arguments
  { question: 'A student drafts this thesis for an argument essay: "Social media is bad for teenagers." Which revision would most improve the thesis as a starting point for a developed argument?', options: ['Social media is extremely bad for teenagers and must be stopped right away.', 'Many people today have strong opinions about teenagers and social media.', 'Though social media connects teens, late-night scrolling harms their sleep.', 'Social media affects teenagers in many different ways, both good and bad.'], correctAnswer: 2, explanation: 'The revision concedes a real benefit and narrows the claim to a specific behavior and a specific harm, so it is defensible and leaves room for evidence and qualification. Adding intensity only makes the blunt assertion louder, while noting that people disagree or that effects vary states no position at all.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 1, part: 1 },
  { question: 'A student\'s argument essay on school uniform policies has five body paragraphs, each offering a different reason in two or three sentences. Which revision advice best follows the principle for developing an argument?', options: ['Cut to the strongest reasons and analyze each one in more depth', 'Add a sixth reason so the essay covers every possible angle', 'Merge all five reasons into a single, longer body paragraph', 'Open each paragraph with a quotation to make it more vivid'], correctAnswer: 0, explanation: 'Developing an argument means deepening fewer points with stronger analysis rather than adding more of them, so the essay gains most from fully explaining its best reasons. Another reason makes the list longer and thinner. Merging the reasons only changes the layout, and an opening quotation adds decoration without analysis.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 2, part: 1 },
  { question: 'Read this excerpt from a student argument: "Critics are right that a four-day school week leaves some working parents scrambling for Friday childcare. Yet districts that adopted the schedule paired it with low-cost Friday enrichment programs, and attendance among teachers rose." The first sentence primarily functions to', options: ['state the central claim the writer will defend', 'provide evidence that supports the four-day schedule', 'reveal the writer\'s doubts about the proposed change', 'concede a legitimate objection before answering it'], correctAnswer: 3, explanation: 'The writer grants that critics have a real point about childcare, and the word "Yet" then introduces the rebuttal, which is the classic concession move. The sentence is not the writer\'s own claim or support for the schedule, and it does not signal doubt, since the next sentence immediately answers the objection.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 1, part: 1 },
  { question: 'A student\'s paragraph about the costs of fast fashion ends: "Clearly, cheap clothing harms garment workers." The next paragraph will argue that fast fashion also damages local water supplies. Which closing sentence would best connect the two paragraphs?', options: ['In conclusion, fast fashion is a serious problem that everyone should think about.', 'If workers bear the human cost, nearby rivers bear an environmental one.', 'Garment workers deserve fair wages, and shoppers should demand change.', 'Water pollution is another major problem that people tend to overlook.'], correctAnswer: 1, explanation: 'The conditional sentence sums up the first paragraph\'s point and forecasts the next, so the reasoning visibly progresses from workers to the environment. A generic conclusion ends the line of reasoning too early, a call for fair wages stays on the first point, and announcing "another problem" adds a topic without showing how it builds on the last.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 2, part: 1 },
  { question: 'A student\'s argument that cities should replace parking minimums with transit investment ends with a summary of its three reasons. Which addition would most deepen the conclusion?', options: ['A restatement of the thesis using different words for emphasis', 'A sentence projecting what the change could mean for housing costs and car-free residents', 'A final statistic about how many parking spaces downtown has', 'A brief list that repeats the three reasons in the same order as before'], correctAnswer: 1, explanation: 'Projecting implications, such as effects on housing and on residents without cars, extends the reasoning beyond recap, a mark of mature development. Restating the thesis or repeating the reasons is the common problem of ending without implications, and a new statistic in the final lines adds evidence without analysis.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 1, part: 1 },
  { question: 'A student claims that later school start times improve grades and offers this evidence: "At Ridgeview High, GPAs rose after the start time moved to 8:45." Which added commentary best explains how the evidence supports the claim?', options: ['This shows that Ridgeview made a smart choice that other schools should copy.', 'This statistic proves beyond doubt that start times matter more than anything.', 'Ridgeview is only one of many schools that have moved their start times later.', 'Rested teens focus better in class and so learn more and score higher.'], correctAnswer: 3, explanation: 'Commentary should explain the mechanism linking evidence to claim: more sleep leads to better focus, which leads to better grades. Praising the school\'s decision or overstating the statistic as proof skips that causal explanation, and noting that other schools have changed schedules adds context rather than reasoning.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 2, part: 1 },
  { question: 'A draft argues: "Since the town opened its new library, juvenile arrests have dropped by 20 percent. The library is clearly keeping young people out of trouble." Which revision would most strengthen the reasoning in the second sentence?', options: ['Explain how library programs could occupy teens and weigh other possible causes', 'Replace "clearly" with "undeniably" so the claim sounds even more confident', 'Add that the library was expensive to build and took several years', 'Add a vivid anecdote about one teenager who now spends every afternoon at the library'], correctAnswer: 0, explanation: 'The draft assumes that because arrests fell after the library opened, the library caused the drop; explaining a plausible mechanism and considering other causes turns that assumption into reasoning. A stronger adverb only intensifies the unsupported leap, the building\'s cost is irrelevant to the causal claim, and a single anecdote adds an example without addressing alternative explanations.', difficulty: 'hard', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 1, part: 1 },
  { question: 'Which sequence best describes the structure of a well-developed body paragraph in an argument essay?', options: ['Evidence first, then the claim, then a new piece of evidence', 'Claim, then several quotations placed one after another', 'Claim, then evidence, then commentary tying it to the thesis', 'Claim, then commentary, then evidence with no further discussion'], correctAnswer: 2, explanation: 'A developed paragraph states a claim, supports it with evidence, and then interprets that evidence, linking it back to the thesis. Stacking quotations or ending on evidence leaves the evidence uninterpreted, and opening with evidence before any claim leaves the reader unsure what it is meant to prove.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 2, part: 1 },
  { question: 'A student arguing that public art strengthens neighborhoods writes: "Art makes communities better in many ways." Which replacement provides the most specific example?', options: ['Murals have become popular in a great many cities around the country today.', 'Experts agree that public art has always helped neighborhoods come together.', 'Public art can make people feel happier and calmer when they walk outside.', 'After teens painted a mural on a vacant laundromat, nearby shops got busier.'], correctAnswer: 3, explanation: 'A concrete case, one mural on one building followed by an observable change, gives the reader something to picture and analyze. The other choices stay general: popularity across cities, an appeal to unnamed experts, and a vague claim about happiness all restate the idea without grounding it in a particular instance.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 1, part: 1 },
  { question: 'A student argues that four-day workweeks boost productivity and cites one software firm that adopted the schedule. A classmate suggests adding a contrasting case: a hospital where the change caused staffing gaps. How would including that case most likely affect the argument?', options: ['It would undermine the thesis and should be left out of the essay entirely.', 'It would prove that the schedule only works in technology companies.', 'It would let the writer qualify where the claim holds.', 'It would distract readers from the main example and weaken the focus.'], correctAnswer: 2, explanation: 'Comparing a case where the policy succeeds with one where it struggles lets the writer refine the claim, perhaps limiting it to certain kinds of work, which strengthens credibility. A single counterexample does not prove a sweeping new rule, and leaving it out or treating it as a distraction misses the chance to show complexity.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 2, part: 1 },
  { question: 'An essay outline lists three reasons a city should fund free public Wi-Fi: it helps students finish homework, it lets job seekers apply online, and it attracts small businesses. Which organizing choice would best show how the reasons interconnect?', options: ['Treat each reason as a separate paragraph with no transitions between them', 'Move from individual benefits to community gains, linking each step to the last', 'Fold all three reasons into one long paragraph so the essay stays brief and focused', 'Open with the weakest reason so the strongest one stays a surprise'], correctAnswer: 1, explanation: 'Ordering the reasons so they build from personal benefits to broader economic effects, with transitions that tie each to the one before, shows a progressing line of reasoning. Isolated paragraphs or a single merged paragraph hide the relationships, and saving a strong point for surprise is a dramatic choice rather than a logical one.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 1, part: 1 },
  { question: 'A body paragraph argues that homework limits reduce student burnout. Its last sentence reads: "Burnout is also a problem for teachers." Why is this ending a weakness?', options: ['It introduces a new issue instead of linking the point back to the thesis.', 'It concedes too much ground to the opposing side of the debate over homework.', 'It uses informal diction that is inappropriate for an academic audience.', 'It repeats the topic sentence without adding any new information.'], correctAnswer: 0, explanation: 'The sentence drifts to a related but different subject, teachers\' burnout, so the paragraph ends without explaining how its evidence advances the thesis about students. It grants nothing to the other side, its diction is not the problem, and it does not restate the topic sentence; it simply fails to close the reasoning.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 2, part: 1 },
  { question: 'A school board member defends an old rule: "Phones were distractions when this policy was written in 1998, so the rule still makes sense." Which rebuttal most directly exposes the weakness in this reasoning?', options: ['Today’s phones hold textbooks and planners, so the 1998 conditions no longer apply.', 'The board member is too old to understand how teenagers actually use their phones.', 'Many students dislike the rule and have signed a petition asking the board to drop it.', 'Other districts banned phones long ago and later reversed that choice after complaints.'], correctAnswer: 0, explanation: 'The argument assumes that what was true of phones in 1998 is still true, so showing how the technology and its classroom uses have changed attacks that assumption directly. Attacking the speaker\'s age targets the person rather than the reasoning, student dislike is an appeal to popularity, and other districts\' reversals report what others did rather than why the reasoning fails.', difficulty: 'hard', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 1, part: 1 },
  { question: 'A writer arguing for a redesigned bus network includes this sentence: "Although the town\'s bus routes have barely changed since the 1970s, where residents live and work has changed dramatically." The sentence primarily serves to', options: ['concede that the current routes have served riders well', 'present the current routes as out of date', 'supply statistical evidence about how residents commute', 'shift the focus from riders to the needs of drivers'], correctAnswer: 1, explanation: 'By contrasting routes that have stayed the same with travel needs that have shifted, the sentence casts the existing network as a holdover from another era, setting up the case for redesign. It does not grant that the routes work well, it offers no statistics, and it says nothing about drivers.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 2, part: 1 },
  { question: 'A student claims that a city\'s new bike lanes have made streets safer and cites this finding: "Since the lanes opened, total bicycle crashes rose from 40 to 52 per year, while the number of daily cyclists tripled." Which commentary interprets the data most accurately?', options: ['The rise in crashes shows that the new lanes have made cycling more dangerous.', 'The data cannot support any claim because crash numbers went up.', 'The number of cyclists proves that everyone in the city now feels safe.', 'Crashes rose far more slowly than ridership, so the risk per cyclist fell.'], correctAnswer: 3, explanation: 'Crashes grew by less than a third while ridership tripled, so the crash rate per rider dropped, which supports the safety claim once the writer explains it. Reading the raw increase as proof of danger ignores the larger pool of riders, dismissing the data overlooks that rate, and claiming everyone feels safe goes far beyond what crash counts can show.', difficulty: 'hard', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 1, part: 1 },
  { question: 'A student argues that the town should build protected bike lanes on Elm Street. A city report finds that bike commuting on Elm rose sharply after painted lanes were added, yet most riders surveyed said they feel unsafe beside traffic. Which use of the report best supports the student\'s argument?', options: ['Citing only the jump in commuting to show painted lanes already fixed the problem', 'Citing only the survey to show that Elm is too dangerous for anyone to cycle on', 'Pairing the jump in commuting with the survey to show demand that fear holds back', 'Setting the report aside since riders\' survey answers are only personal opinion'], correctAnswer: 2, explanation: 'Read together, the two findings show that people want to ride on Elm and that fear of traffic still limits them, which is exactly the gap protected lanes would close. Using the commuting figure alone suggests the current lanes are enough, and using the survey alone argues against cycling on Elm at all. Discarding the report wastes evidence that directly supports the proposal.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 2, part: 1 },
  { question: 'An argument prompt asks students to take a position on whether communities should preserve historic buildings or replace them with new housing. Which thesis responds most effectively to the prompt?', options: ['Historic buildings and new housing are both important topics in many communities today.', 'Cities should keep historic buildings that anchor local identity but open underused lots to new housing.', 'This essay will discuss the debate about historic buildings and new housing.', 'Old buildings are beautiful, and many people enjoy visiting them on weekends.'], correctAnswer: 1, explanation: 'A strong thesis takes a defensible, qualified position that answers the prompt\'s question and suggests a line of reasoning. Announcing what the essay will discuss or calling both sides important avoids taking a position, and praising old buildings\' beauty offers an opinion that does not address the choice the prompt poses.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 1, part: 1 },
  { question: 'A student\'s draft commentary reads: "This evidence is very important and really proves my point about the issue." Which revision best addresses the most common problem with this commentary?', options: ['Add another quotation after the evidence to support the same point', 'Replace "very important" with "extremely significant" for emphasis', 'State precisely how the evidence advances the claim', 'Move the sentence to the start of the paragraph as a topic sentence'], correctAnswer: 2, explanation: 'The commentary only asserts that the evidence matters; precise commentary explains how the evidence supports the claim, which is what earns credit for evidence and commentary. A more forceful synonym, an extra quotation, or relocating the sentence leaves the reasoning just as vague.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-developing-arguments', formSet: 2, part: 1 },
  // englang-writing-for-audience
  { question: 'A student is writing to neighborhood residents who oppose a proposed homeless shelter on their street. Which sentence would be the most effective opening for this audience?', options: ['Opponents of the shelter are letting fear override basic compassion for others.', 'Like you, I want our street to stay safe and welcoming as the shelter plans move forward.', 'The shelter is coming to this street whether residents like it or not.', 'Homelessness is a complex issue that has existed throughout human history.'], correctAnswer: 1, explanation: 'Hostile readers are more open to an argument that starts from values they already hold, so appealing to a shared desire for safety lowers defensiveness. Accusing opponents of fear and announcing that resistance is pointless both alienate this audience, and a sweeping remark about history sidesteps the local concern entirely.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 1, part: 1 },
  { question: 'A public-health agency is drafting a flyer for parents about a new vaccine schedule. The draft reads: "Seroconversion rates exceeded 95 percent across cohorts." Which revision best suits the audience?', options: ['Over 95 percent of cohorts showed seroconversion in clinical trials.', 'Seroconversion, a key immune marker, was very high in all cohorts.', 'The vaccine is so good that parents have nothing at all to worry about.', 'Almost all children in the trials became protected.'], correctAnswer: 3, explanation: 'Parents reading a flyer are a general audience, so the revision translates the technical finding into plain words without changing its meaning. Keeping or merely glossing the jargon still burdens the reader, and claiming there is nothing to worry about overstates the evidence, which ethical adaptation rules out.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 2, part: 1 },
  { question: 'A student supports a citywide ban on gas-powered leaf blowers and must address the owners of local landscaping companies. Which approach would most likely persuade this audience?', options: ['Stress a phased timeline and rebates that ease the switch to electric tools', 'Describe the noise complaints residents have filed against loud crews', 'Argue that landscapers who resist the ban care more about profit than people', 'Drop the ban and propose voluntary quiet hours as a compromise'], correctAnswer: 0, explanation: 'Business owners care about cost and predictable compliance, so a gradual timeline with rebates speaks to their real concerns while keeping the claim intact. Residents\' complaints matter to a different audience, attacking owners\' motives alienates them, and abandoning the ban changes the core claim rather than adapting the framing.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 1, part: 1 },
  { question: 'Writing to persuade parents to support a later school start time, a student considers several strategies. Which strategy crosses the line from audience adaptation into manipulation?', options: ['Opening with a short account of a typical student\'s exhausted morning', 'Explaining how a later start would affect family morning routines', 'Presenting the single favorable study and omitting conflicting ones', 'Defining the term circadian rhythm in plain everyday language'], correctAnswer: 2, explanation: 'Cherry-picking a favorable study while hiding contrary findings misrepresents the evidence, the kind of distortion ethical adaptation forbids. A representative anecdote, attention to families\' routines, and plain-language definitions all fit the message to parents without misleading them.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 2, part: 1 },
  { question: 'A student who wrote an op-ed about microplastics for the school newspaper is now revising it for a panel of environmental scientists. Which revision would best suit the new audience?', options: ['Adding vivid images of polluted beaches to make the problem feel urgent', 'Simplifying the explanation so readers with no background can follow', 'Specifying how the cited studies measured particle concentrations and noting their limits', 'Removing the counterargument because experts already know both sides'], correctAnswer: 2, explanation: 'Expert readers expect methodological precision and an honest account of a study\'s limits, so detailing measurement methods meets their standards. Vivid images suit a general audience, simplifying risks the oversimplification experts reject, and cutting the counterargument removes the nuance specialists look for.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 1, part: 1 },
  { question: 'A columnist writing to readers who oppose a new bike lane begins: "Only people stuck in the last century could object to something as obvious as safer streets." What effect is this opening most likely to have on its intended readers?', options: ['It will make them less willing to keep reading.', 'It will persuade them by appealing to their shared values.', 'It will build the writer\'s credibility through humor.', 'It will clarify the evidence supporting the bike lane.'], correctAnswer: 0, explanation: 'Mocking opponents as stuck in the past insults the very readers the columnist needs to win over, so they are likely to stop listening. The line appeals to no value they share, its ridicule damages rather than builds credibility, and it offers no evidence about the bike lane.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 2, part: 1 },
  { question: 'A nonprofit is asking a state legislature\'s budget committee to fund a tutoring program. The current draft relies on three heartfelt letters from students. Why might the draft fail with this audience?', options: ['The letters are too formal for a committee that prefers a casual tone.', 'Legislators are a hostile audience that rejects any emotional appeal at all.', 'Student letters are inadmissible as evidence in any legislative hearing.', 'The committee needs cost and outcome data to justify spending public money.'], correctAnswer: 3, explanation: 'A policy audience weighs cost-benefit evidence and feasibility, so a request built only on anecdotes gives the committee nothing to justify the expense. Formality is not the issue, legislators can be moved by personal stories used as supplements, and nothing bars such letters from a hearing.', difficulty: 'hard', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 1, part: 1 },
  { question: 'Version 1, for a school assembly: "Recycling here is easy, so grab a blue bin and help us cut our trash in half!" Version 2, for the district facilities office: "A recycling program at our school could cut waste-hauling fees by roughly 30 percent." Which statement best describes how the writer adapted the message?', options: ['The second version abandons the original claim to satisfy budget officials.', 'The claim holds steady while the evidence and tone shift for each reader.', 'Both versions rely on the same urgent tone and the same kind of evidence.', 'The first version is more persuasive because it ends with an exclamation.'], correctAnswer: 1, explanation: 'Both versions push for recycling, but the assembly version uses an energetic call to action while the facilities version offers cost savings in a measured tone. The claim is never abandoned, the evidence and tone clearly differ, and an exclamation point alone does not make a message more persuasive to a budget office.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 2, part: 1 },
  { question: 'A writer is urging a town\'s general public to support a new water-treatment plant. Which piece of evidence is best suited to this audience?', options: ['A comparison showing the monthly bill increase costs less than a cup of coffee', 'A table of contaminant concentrations measured in parts per billion', 'A quotation from an engineering journal on filtration membrane design', 'A list of every federal statute governing municipal water quality'], correctAnswer: 0, explanation: 'General readers respond to clear terms and relatable examples, so translating the cost into a familiar daily expense makes the evidence meaningful. Concentration tables, engineering research, and statute lists are precise but suit expert or policy audiences and would likely lose ordinary residents.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 1, part: 1 },
  { question: 'Two student drafts argue that a city should plant more street trees. One, written for a garden club newsletter, ends: "Join us at Saturday\'s planting!" The other, written for the city council, ends: "We ask the council to fund 500 trees in next year\'s budget." What does the difference in endings most clearly reflect?', options: ['The newsletter draft lacks a clear claim about trees.', 'Each closes with an action its reader can take.', 'The council draft relies on emotion rather than evidence.', 'Each writer changed the central claim for the new readers.'], correctAnswer: 1, explanation: 'The sympathetic club members can show up and plant, while the council\'s power is to fund, so each ending asks for the action its audience can actually take. Neither draft drops the claim that the city needs trees, and a specific budget request is a practical appeal rather than an emotional one.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 2, part: 1 },
  { question: 'A student is writing a speech urging classmates to vote in the student council election, which has had record-low turnout. Which revision best connects the purpose of the speech to its audience and context?', options: ['Explaining the history of student government in American public schools', 'Listing the council\'s bylaws so listeners understand every rule of the election', 'Warning that students who do not vote are irresponsible and immature', 'Noting last year\'s empty polling tables and asking peers what they would change'], correctAnswer: 3, explanation: 'Pointing to last year\'s empty tables addresses the low-turnout context, and asking peers what they would change invites the participation the speech aims for. A history lesson and a list of bylaws ignore the immediate exigence, and scolding nonvoters alienates the classmates the speaker needs.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 1, part: 1 },
  { question: 'After a chemical spill shuts down the town\'s water supply, the mayor must address residents tonight. Which sentence best fits the rhetorical situation?', options: ['Many factors contributed to this incident, and a thorough review will be conducted in due time.', 'This is a terrifying disaster, and frankly no one can say what will happen next.', 'Do not drink tap water until we say it is safe, and pick up bottled water at any fire station.', 'Water quality is a complex topic that scientists have studied for many decades.'], correctAnswer: 2, explanation: 'An urgent crisis calls for a firm, clear, solution-oriented tone, and this sentence gives residents the two instructions they need right now. Promising a future review dodges the immediate need, voicing panic undermines the mayor\'s authority, and a general remark about water science ignores the emergency.', difficulty: 'hard', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 2, part: 1 },
  { question: 'A student\'s speech arguing that the school should offer more arts electives won cheers at a pep rally. She will now present the same argument to the school board. Which change is most appropriate?', options: ['Drop the claim about electives and ask only for a larger art club budget', 'Keep the jokes and chants that energized the crowd at the pep rally', 'Replace all evidence with a personal story about her love of painting', 'Add scheduling and staffing details showing how the new electives could be funded'], correctAnswer: 3, explanation: 'A school board is a policy audience that weighs feasibility, so showing how the electives could be staffed and funded adapts the evidence while keeping the claim. Abandoning the claim is not adaptation, pep-rally chants suit a sympathetic crowd rather than decision makers, and a single personal story cannot carry a budget request.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 1, part: 1 },
  { question: 'When a writer adapts an argument for a different audience, which element should generally stay the same?', options: ['The position being defended', 'The examples chosen to illustrate it', 'The level of formality in the diction', 'The type of evidence offered as support'], correctAnswer: 0, explanation: 'Adaptation changes framing, evidence, and tone to fit readers, but the position itself should remain stable. The examples, the formality of the diction, and the kind of evidence are exactly the levers a writer adjusts for a new audience.', difficulty: 'easy', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 2, part: 1 },
  { question: 'A student arguing for a crosswalk near an elementary school will present to parents at a PTA meeting. Which way of presenting the traffic data would best serve this audience?', options: ['Showing a regression table of vehicle speeds with confidence intervals', 'Translating hourly traffic counts into how many cars pass during morning drop-off', 'Omitting the numbers entirely and describing the corner as a deathtrap', 'Reading aloud each hourly count recorded in the city\'s complete yearly traffic report'], correctAnswer: 1, explanation: 'Parents are a general audience, so converting raw counts into the moment they care about, morning drop-off, makes the data concrete and relevant. A regression table suits experts, a full recitation buries the point, and dropping the data for alarmist language trades accuracy for fear.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 1, part: 1 },
  { question: 'A writer wants to persuade a skeptical town meeting that a new recycling fee is worth it. Which presentation of the evidence is both persuasive and ethical?', options: ['Reporting only the projected landfill savings and leaving the fee\'s cost out entirely', 'Describing the fee as "pennies" without giving its actual yearly amount', 'Stating the fee\'s annual cost per household beside the projected landfill savings', 'Presenting the landfill data in technical units that few residents would know'], correctAnswer: 2, explanation: 'Skeptical readers trust a writer who represents costs and benefits fairly, and setting the fee beside the savings lets them judge for themselves. Omitting the cost is cherry-picking, calling the fee pennies without a figure hides information, and unfamiliar technical units fail to reach a general audience.', difficulty: 'hard', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 2, part: 1 },
  { question: 'A student is writing to town residents in support of a new dog park. The writer wants to add a sentence that anticipates an objection from people who live near the proposed site. Which sentence best accomplishes this goal?', options: ['Neighbors worried about noise should know the plan adds a tall hedge and closes the park at dusk.', 'Dogs that get regular exercise are healthier and calmer than dogs that do not.', 'Several nearby towns have built dog parks that their neighbors now use daily.', 'Anyone who opposes a dog park simply does not care about animals.'], correctAnswer: 0, explanation: 'People living next to the site are most likely to worry about noise and late-night activity, so naming that concern and answering it with concrete measures anticipates resistance directly. Benefits for dogs and examples from other towns support the proposal but do not address nearby residents, and dismissing opponents as uncaring would harden their resistance.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 1, part: 1 },
  { question: 'A student\'s letter to the principal requesting a later lunch period reads: "We respectfully ask that you consider moving lunch to 12:15. Lunch at 10:40 is way too early." The writer wants to revise the second sentence so it keeps the letter\'s respectful tone. Which choice best accomplishes this?', options: ['Honestly, the current lunch time is completely ridiculous.', 'Many of us start to feel lightheaded by late morning.', 'Whoever picked this lunch time clearly never ate it themselves.', 'The present schedule constitutes an egregious institutional failure.'], correctAnswer: 1, explanation: 'A respectful request is best served by a calm, factual description of the problem, which this sentence gives without blaming anyone. Calling the schedule ridiculous or mocking whoever set it sounds hostile, and the inflated charge of institutional failure is both stiffly formal and accusatory.', difficulty: 'medium', domain: 'synthesis-argument', topicSlug: 'englang-writing-for-audience', formSet: 2, part: 1 },
]


export function generateExitQuiz(count = 10, topicSlug?: string): { id: string; question: string; options: string[]; correctIndex: number; explanation: string; category: string; partNumber?: number }[] {
  let pool = engLangQuestionPool
  if (topicSlug) pool = relevantPool(pool, topicSlug)
  return shuffleArray(pool).slice(0, count).map((q, i) => ({
    id: `${q.topicSlug}-q${i}`,
    question: q.question,
    options: q.options,
    correctIndex: q.correctAnswer,
    explanation: q.explanation,
    category: q.domain,
    topicSlug: q.topicSlug,
    partNumber: q.part,
  }))
}
